			if(f1 == f2) continue;
			else sfa[f1] = f2, sz[f2] += sz[f1];
		}
		else a[++ cnt] = anode(u,v);
	}
	if(!flag) {
		puts("No");
		return 0;
	}
	if(m == n - 1) {
		if(cnt) puts("No");
		else puts("Yes");
		return 0;
	}
	for(int i = 1;i <= cnt;i ++) {
		int u = a[i].u, v = a[i].v;
		int f1 = findfa(u), f2 = findfa(v);
		if(f1 == f2) flag = 0;
	}
	if(!flag) {
		puts("No");
		return 0;
	}
	int num = 0;
	for(int i = 1;i <= n;i ++) if(sfa[i] == i) num ++;
	m -= n - num;
	if(num <= 2) {
		if(cnt) puts("No");
		else puts("Yes");
		return 0;
	}
	ll lim = (ll)max(0,num * (num - 1) / 2);
	if(m <= lim) puts("Yes");
	else puts("No");
	return 0;
}

