struct Dsu {
	vi par;
	vi size;
	Dsu() {};
	Dsu(int n) {
		fi(0, n - 1) par.pb(i), size.pb(1);
	}
	int find(int x) {
		if (par[x] == x) return x;
		return par[x] = find(par[x]);
	}
	bool uni(int a, int b) {
		a = find(a);
		b = find(b);
		if (a == b) return false;
		size[a] += size[b];
		par[b] = a;
		return true;
	}
};

void solve () {
	Dsu dsu1(n), dsu2(n);
	for (auto z : edges[0]) {
		dsu1.uni(z.first, z.second);
	}
	for (auto z : edges[1]) {
		int x = z.first;
		int y = z.second;
		if (!dsu1.uni(x, y)) {
			if (!dsu2.uni(x, y)) {
				no();
			}
		} else {
			dsu2.uni(x, y);
		}
	}
	vi cnt(n, 0);
	fi(0, n - 1) {
		int p = dsu2.find(i);
		if (i != p) continue;
		if (dsu2.size[p] == 2) {
			int pp = dsu1.find(i);
			cnt[pp]++;
		}
	}	
	vpii a;
	fi(0, n - 1) {
		int p = dsu1.find(i);
		if (p == i) {
			a.pb(mp(cnt[i], i));
		}
	}
	sort(a.rbegin(), a.rend());
	if (!sz(a)) {
		yes();
	}
	int have = a[0].first;
	fi(1, sz(a) - 1) {
		int q = a[i].first;
//		int x = a[i].second;
		int decr = 0;
		if (have >= 0) {
			decr++;
		}
		if (q >= 0) {
			decr++;
		}
		have += q;
		have -= decr;
	}
	if (have > 0) {
		no();
	} else {
		yes();
	}
}

