using namespace std;

class MFSetCell
{
public:

  int mId;

  MFSetCell* mParent;

  int mRank;

};

class MFSet
{
public:

  MFSet(int num);

  ~MFSet() = default;

  int
  find(int id);

  int
  merge(int id1,
	int id2);


private:

  MFSetCell*
  _find_top(MFSetCell* cell);

  vector<MFSetCell> mArray;

};


MFSet::MFSet(int num) :
  mArray(num)
{
  for ( int i = 0; i < num; ++ i ) {
    MFSetCell& cell = mArray[i];
    cell.mId = i;
    cell.mParent = &cell;
    cell.mRank = 0;
  }
}

int
MFSet::find(int id)
{
  auto tmp = &mArray[id];
  auto top = _find_top(tmp);
  return top->mId;
}

MFSetCell*
MFSet::_find_top(MFSetCell* cell)
{
  auto parent = cell->mParent;
  while ( parent->mParent != parent ) {
    cell = cell->mParent = parent->mParent;
    parent = cell->mParent;
  }
  return parent;
}

int
MFSet::merge(int id1,
	     int id2)
{
  auto cell1 = &mArray[id1];
  auto cell2 = &mArray[id2];

  if ( cell1->mParent != cell1 ) {
    cell1 = _find_top(cell1);
  }
  if ( cell2->mParent != cell2 ) {
    cell2 = _find_top(cell2);
  }
  if ( cell1 == cell2 ) {
    return cell1->mId;
  }

  if ( cell1->mRank > cell2->mRank ) {
    cell2->mParent = cell1;
    return cell1->mId;
  }
  else if ( cell1->mRank == cell2->mRank ) {
    ++ cell1->mRank;
    cell2->mParent = cell1;
    return cell1->mId;
  }
  else {
    cell1->mParent = cell2;
    return cell2->mId;
  }
}

void
no()
{
  cout << "No" << endl;
  exit(0);
}

void
yes()
{
  cout << "Yes" << endl;
  exit(0);
}

int
main(int argc,
     char** argv)
{
  cin.tie(0);
  ios::sync_with_stdio(0);

  int N;
  int M;
  int Q;
  cin >> N
      >> M
      >> Q;

  MFSet mfset(N);

  vector<pair<int, int>> single_pair_list;
  vector<pair<int, int>> multi_pair_list;
  bool has_single = false;
  for ( int i = 0; i < Q; ++ i ) {
    int a, b, c;
    cin >> a >> b >> c;
    if ( c == 0 ) {
      single_pair_list.push_back(make_pair(a, b));
      mfset.merge(a, b);
      has_single = true;
    }
    else {
      multi_pair_list.push_back(make_pair(a, b));
    }
  }

  if ( M == N - 1 ) {
    // M = N - 1 の時は木構造のグラフとなる．
    if ( multi_pair_list.size() > 0 ) {
      // その場合複数経路はありえない．
      no();
    }
    else {
      yes();
    }
  }

  if ( !has_single ) {
    yes();
  }

  for ( auto p: multi_pair_list ) {
    int a = p.first;
    int b = p.second;
    if ( mfset.find(a) == mfset.find(b) ) {
      no();
    }
  }

  int K = 0;
  for ( int i = 0; i < N; ++ i ) {
    if ( mfset.find(i) == i ) {
      ++ K;
    }
  }

  int M_max = N - K + (K * (K - 1)) / 2;
  if ( M > M_max ) {
    no();
  }

  yes();

  return 0;
}

