struct ufds {
  int n;
  vector<int> p, s;
  ufds(int n = 0) : n(n), p(n), s(n, 1) {
    for (int i = 0; i < n; i++)
      p[i] = i;
  }
  int findSet(int i) {
    return p[i] == i ? i : (p[i] = findSet(p[i]));
  }
  bool inSameSet(int i, int j) {
    return findSet(i) == findSet(j);
  }
  int getSizeOfSet(int i) {
    return s[findSet(i)];
  }
  void unionSet(int i, int j) {
    i = findSet(i); j = findSet(j);
    if (i != j) {
      if (s[i] < s[j])
        swap(i, j);
      s[i] += s[j]; p[j] = i;
    }
  }
};

int n, m, q;
bool c1[200000];

int main() {
  ios_base::sync_with_stdio(false);
  cin.tie(0);
  cout << fixed << setprecision(10);
  cin >> n >> m >> q;
  ufds u(n);
  vector<pair<int, int>> e;
  int a, b, c;
  for (int i = 0; i < q; i++) {
    cin >> a >> b >> c;
    if (c == 0) {
      if (!u.inSameSet(a, b))
        u.unionSet(a, b), n--, m--;
    } else
      e.push_back({a, b});
  }
  int cc = 0;
  for (pair<int, int> ed : e) {
    a = ed.first, b = ed.second;
    if (u.inSameSet(a, b)) {
      cout << "No\n";
      return 0;
    }
    if (!c1[u.findSet(a)])
      c1[u.findSet(a)] = true, cc++;
    if (!c1[u.findSet(b)])
      c1[u.findSet(b)] = true, cc++;
  }
  if (cc > 0 && n < 3) {
    cout << "No\n";
    return 0;
  }
  int me = cc == 0 ? 0 : max(3, cc + 1);
  int ma = n * (n - 1) / 2;
  if (m < me || m > ma) {
    cout << "No\n";
    return 0;
  }
  cout << "Yes\n";
}

