#define Maxn 200000
#define ll long long
int n,k;
ll m;
int fa[Maxn+5],left[Maxn+5],right[Maxn+5];
int ask(int x){
	return x==fa[x]?x:fa[x]=ask(fa[x]);
}
int main(){
	scanf("%d%lld%d",&n,&m,&k);
	int ds=n;
	int a,b,c;
	int len=0;
	for(int i=0;i<n;i++){
		fa[i]=i;
	}
	while(k--){
		scanf("%d%d%d",&a,&b,&c);
		int p=ask(a),q=ask(b);
		if(c==0&&p!=q){
			ds--;
			fa[q]=p;
		}
		if(c==1){
			left[++len]=a;
			right[len]=b;
		}
	}
	for(int i=1;i<=len;i++){
		if(ask(left[i])==ask(right[i])){
			puts("No");
			return 0;
		}
	}
	if((m+ds-n>1ll*ds*(ds-1)/2)||(len&&(ds==2||m<n))){
		puts("No");
	}
	else{
		puts("Yes");
	}
	return 0;
}

