ll n,m,q;
ll a[N],b[N],c[N];
namespace uf{
    ll p[N],s[N];
    void init(){
        for(int i=0;i<N;i++){
            p[i]=i,s[i]=1;
        }
    }
    ll par(ll x){
        return p[x]=(p[x]==x?x:par(p[x]));
    }
    void unite(ll a,ll b){
        a=par(a),b=par(b);
        if(a==b)return;
        s[a]+=s[b];
        p[b]=a;
    }
    bool same(ll a,ll b){
        a=par(a),b=par(b);
        return a==b;
    }
};

int main(){
  cin>>n>>m>>q;
  uf::init();
  for(int i=0;i<q;i++){
      cin>>a[i]>>b[i]>>c[i];
