  rep(i,n){
    if(s.root(i)==i){
      v++;
      ed-=s.size(i)-1;
    }
  }
  bool ok=true;
  if(ed<0) ok=false;
  cout << "yes" << endl;
  return 0;
  bool loop=false;
  rep(i,q){
    if(c[i]==1){
      loop=true;
      if(s.same(a[i],b[i])) ok=false;
    }
  }
  if(!loop){
    if((v*(v-1)/2<ed) ||( v-1>ed)) ok=false;
  }
  else if(v>=3){
    if((v*(v-1)/2<ed) ||( v-1>ed)) ok=false;
  }
  else ok=false;

  if(ok) cout << "Yes" << endl;
  else cout << "No" << endl;



  return 0;


}

