  int64 N, M, Q;
  cin >> N >> M >> Q;
  UnionFind uf(N);
  vector< int > A(Q), B(Q), C(Q);
  for(int i = 0; i < Q; i++) {
    cin >> A[i] >> B[i] >> C[i];
  }

  int used = 0;
  for(int i = 0; i < Q; i++) {
    if(C[i] == 0) if(uf.unite(A[i], B[i])) ++used;
  }


