    exit(0);
  };
  auto No = []() {
    cout << "No" << endl;
    exit(0);
  };

  for(int i = 0; i < Q; i++) {
    if(C[i] == 1) {
      if(uf.find(A[i]) == uf.find(B[i])) No();
    }
  }

  vector< int > rot;
  for(int i = 0; i < N; i++) {
    if(uf.find(i) == i) rot.emplace_back(i);
  }


  if(rot.size() == 1) {
    if(used == M) Yes();
    else No();
  } else if(rot.size() == 2) {

    for(int i = 0; i < Q; i++) {
      if(C[i] == 1) No();
    }
    ++used;
    if(used == M) Yes();
    else No();
  } else {
    UnionFind uf2(N);
    int64 low = used, high = used;

    set< int > appear;
    for(int i = 0; i < Q; i++) {
      if(C[i] == 1) {
        appear.emplace(uf.find(A[i]));
        appear.emplace(uf.find(B[i]));
      }
    }
    int64 v = rot.size();
    high += v * (v - 1) / 2;
    low += appear.size();

    if(low <= M && M <= high) Yes();
    else No();
  }
}

