        x = find(x), y = find(y);
        if(x == y) return;
        if(size_[x] < size_[y]) swap(x,y);
        par[y] = x;
        size_[x] += size_[y];
        psz[x] +=psz[y];
    }
    int size(int x){
        x = find(x);
        return size_[x];
    }
    int psize(int x){
        x = find(x);
        return psz[x];
    }
    bool same(int x,int y){
        return find(x) == find(y);
    }
};


