template <const int MAXN, const bool ONE_INDEXED> struct UnionFind {
    int UF[MAXN], cnt;
    void init(int N) { cnt = N; fill(UF, UF + N + ONE_INDEXED, -1); }
    int find(int v) { return UF[v] < 0 ? v : UF[v] = find(UF[v]); }
    bool join(int v, int w) {
        if ((v = find(v)) == (w = find(w))) return false;
        if (UF[v] > UF[w]) swap(v, w);
        UF[v] += UF[w]; UF[w] = v; cnt--; return true;
    }
    bool connected(int v, int w) { return find(v) == find(w); }
    int getSize(int v) { return -UF[find(v)]; }
};

const int MAXN = 1e5 + 5, MAXQ = 1e5 + 5;

int N, Q, A[MAXQ], B[MAXQ], C[MAXQ];
ll M;
UnionFind<MAXN, 0> UF;

int main() {
    // setInput("in.txt");
    // setOutput("out.txt");
    // setError("err.txt");
    read(N, M, Q);
    UF.init(N);
    int extras = 0;
    FOR(i, Q) {
        read(A[i], B[i], C[i]);
        if (C[i] == 0) UF.join(A[i], B[i]);
        else extras++;
    }
    FOR(i, Q) if (C[i] == 1 && UF.connected(A[i], B[i])) {
        writeln("No");
        return 0;
    }
    ll cc = 0;
    FOR(i, N) cc += UF.find(i) == i;
    if (M == N - 1) writeln(extras == 0 ? "Yes" : "No");
    else writeln(M <= N - 1 + cc - 1 + cc * (cc - 1) / 2 ? "Yes" : "No");
    return 0;
}

