class disjoint_set {
public:
    int n;
    vector<int> p;
    vector<int> size;
    int n_comp;
    explicit disjoint_set(int n) :
        n(n),
        p(n),
        size(n, 1),
        n_comp(n) {
        iota(p.begin(), p.end(), 0);
    }
    int parent(int x) {
        if (p[x] != x) {
            p[x] = parent(p[x]);
        }
        return p[x];
    }
    void merge(int a, int b) {
        const int pa = parent(a);
        const int pb = parent(b);
        if (pa == pb)
            return;
        if (size[pa] > size[pb]) {
            merge(b, a);
            return;
        }
        size[pb] += size[pa];
        p[pa] = pb;
        --n_comp;
    }
};
int main() {
    int n, m, q;
    cin >> n >> m >> q;
    disjoint_set dj(n);
    vector<pair<int, int>> g;
    while (q--) {
        int a, b, c;
        cin >> a >> b >> c;
        if (c == 0) {
            dj.merge(a, b);
        } else {
            g.emplace_back(a, b);
        }
    }
    bool fail = false;
    for (auto p: g) {
        if (dj.parent(p.first) == dj.parent(p.second)) {
            fail = true;
            break;
        }
    }
    if (fail) {
        cout << "No\n";
        return 0;
    }
    if (!g.empty() && m == n - 1) {
        cout << "No\n";
        return 0;
    }
    long long n_comp = dj.n_comp;
    long long max_edges = n_comp * (n_comp - 1) / 2;
    for (int i = 0; i < n; ++i) {
        if (dj.size[i] > 1 && dj.p[i] == i)
            max_edges += dj.size[i] - 1;
    }
    if (max_edges >= m)
        cout << "Yes\n";
    else
        cout << "No\n";
    return 0;
}

