struct UnionFind {
    vector<int> A;
    UnionFind(int n) : A(n, -1) {}
    int find(int x) {
        if (A[x] < 0) return x;
        return A[x] = find(A[x]);
    }
    void unite(int x, int y) {
        x = find(x), y = find(y);
        if (x == y) return;
        if (A[x] > A[y]) swap(x, y);
        A[x] += A[y];
        A[y] = x;
    }
};
void okay() { cout << "Yes\n"; exit(0); }
void fail() { cout << "No\n"; exit(0); }
int main() {
    Int N, M, Q; cin >> N >> M >> Q;
    vector<int> A(Q), B(Q), C(Q);
    for (int i = 0; i < Q; i++) cin >> A[i] >> B[i] >> C[i];
    if (M == N - 1) {
        for (int i = 0; i < Q; i++) if (C[i] == 1) fail();
        okay();
    }
    UnionFind uf(N);
    for (int i = 0; i < Q; i++) if (C[i] == 0) {
        uf.unite(A[i], B[i]);
    }
    for (int i = 0; i < Q; i++) if (C[i] == 1) {
        if (uf.find(A[i]) == uf.find(B[i])) {
            fail();
        }
    }
    Int k = 0;
    for (int i = 0; i < N; i++) {
        if (uf.A[i] < 0) k++;
    }
    if (M <= N + k * (k - 3) / 2) {
        okay();
    } else {
        fail();
    }
    return 0;
}

