bool solve() {
    ll n, m, q;
    std::cin >> n >> m >> q;
    tree::UnionFind uf(n);
    vec<pll> q1, q2;
    while (q--) {
        ll a, b, c;
        std::cin >> a >> b >> c;
        (c == 0 ? q1 : q2).emplace_back(a, b);
    }

    ll cnt = 0;
    for (auto &&e : q1) {
        ll a, b;
        std::tie(a, b) = e;
        cnt += uf.unit(a, b);
    }

    vec<bool> used(n);
    for (auto &&e : q2) {
        ll a, b;
        std::tie(a, b) = e;
        if (uf.same(a, b)) return false;
        used[uf.find(a)] = true;
        used[uf.find(b)] = true;
    }

    auto get_pars = [&] {
        std::set<ll> pars;
        for (ll i = 0; i < n; i++) if (uf.find(i) == i) pars.insert(i);
        return pars;
    };

    vec<ll> cands;

    ll sz = get_pars().size();
    if (sz != 2) cands.push_back(cnt + sz * (sz - 1) / 2);

    ll node = -1;
    for (ll i = 0; i < n; i++) {
        ll p = uf.find(i);
        if (used[p]) continue;
        if (node == -1) node = i;
        else cnt += uf.unit(node, i);
    }

    sz = get_pars().size();
    if (sz != 2) cands.push_back(cnt + (sz == 1 ? 0 : sz));

    if (node != -1) {
        ll p = uf.find(node);
        for (ll i = 0; i < n; i++) if (uf.find(i) != p) {
            cnt += uf.unit(p, i);
            break;
        }
    }

    sz = get_pars().size();
    if (sz != 2) cands.push_back(cnt + (sz == 1 ? 0 : sz));

    sort(ALL(cands));
    return cands.size() && cands.front() <= m && m <= cands.back();
}

