int lca(int x,int y)
{
	if (dep[x]<dep[y]) swap(x,y);
	for (int j=17; j>=0; j--)
		if (dep[F[x][j]]>=dep[y]) x=F[x][j];
	if (x==y) return x;
	for (int j=17; j>=0; j--)
		if (F[x][j]!=F[y][j]) x=F[x][j],y=F[y][j];
	return F[x][0];
}

