class UnionFind {
private:
	long long Size;
	vector<long long> Parent, Rank;
public:
	UnionFind(long long N) : Size(N) {
		Parent.resize(N);
		Rank.resize(N);
		for (int i = 0; i < N; i++) {
			Parent[i] = i;
			Rank[i] = 0;
		}
	}
	long long Root(long long N) {
		if (N == Parent[N]) {
			Rank[N] = 0;
			return N;
		}
		Rank[N] = 1;
		return Parent[N] = Root(Parent[N]);
	}
	bool Same(long long A, long long B) {
		return Root(A) == Root(B);
	}
	void Merge(long long A, long long B) {
		long long RA = Root(A), RB = Root(B);
		if (Rank[RA] < Rank[RB]) {
			Parent[RA] = RB;
			Rank[RA]++;
		}
		else {
			Parent[RB] = Root(RA);
			Rank[RB]++;
		}
	}
};

int main() {
	long long N, M, Q;
	vector<long long> A, B, C;
	bool check = true;
	cin >> N >> M >> Q;
	A.resize(Q), B.resize(Q), C.resize(Q);
	UnionFind UF(N);
	for (int i = 0; i < Q; i++) {
		cin >> A[i] >> B[i] >> C[i];
		if (C[i] == 1) check = false;
	}
	if (check) {
		if (M == N - 1) cout << "Yes" << endl;
		else cout << "No" << endl;
		return 0;
	}
	if (M == N - 1) {
		cout << "No" << endl;
		return 0;
	}
	for (int i = 0; i < Q; i++) {
		if (C[i] == 0) UF.Merge(A[i], B[i]);
	}
	vector<long long> Roots;
	for (int i = 0; i < N; i++) {
		Roots.push_back(UF.Root(i));
	}
	sort(Roots.begin(), Roots.end());
	Roots.erase(unique(Roots.begin(), Roots.end()), Roots.end());
	long long P = Roots.size();
	if (P <= 2) cout << "No" << endl;
	else if (N - P + P * (P - 1) / 2 > M) cout << "No" << endl;
	else cout << "Yes" << endl;
}

