    ll r;
    if(par[x]==x)return x;
    r=root(par[x]);
    if(par[x]!=r){
      treesize[r]+=treesize[x];
      treesize[x]=0;
      par[x]=r;
    }
    return r;
  }
  void unite(ll x,ll y){
    ll px=root(x);
    ll py=root(y);
    if(px!=py){
      par[px]=py;
      treesize[py]+=treesize[px];
      treesize[px]=0;
    }
  }
  bool parcheck(ll x,ll y){
    ll px=root(x);
    ll py=root(y);
    return px==py;
  }
  ll size(ll x){
    ll px=root(x);
    return treesize[px];
  }
  void clear(){
    ll i;
    rep(i,(ll)par.size()){
      par[i]=i;
      treesize[i]=1;
    }
  }
};

int main(){
  ll i,N,M,Q,a,b,c,K;
  cin>>N>>M>>Q;
  unionfind tree(N);
  pvec v;
  rep(i,Q){
    cin>>a>>b>>c;
    if(c){
      v.push_back(datas(a,b));
    }else{
      tree.unite(a,b);
    }
  }
  set<ll> se;
  rep(i,N){
    se.insert(tree.root(i));
  }

  K=se.size();
  if(K<3){
    if(M==N-1&&K==0){
      cout<<"Yes"<<endl;
    }else{
      cout<<"No"<<endl;
    }
  }else{
    for(auto i:v){
      if(tree.parcheck(i.first,i.second)){
        cout<<"No"<<endl;
        return 0;
      }
    }
    if(M<=K*(K-1)/2+(N-K)){
      if(v.size()==0)M++;
      if(N<=M){
        cout<<"Yes"<<endl;
        return 0;
      }
    }
    cout<<"No"<<endl;
  }
  return 0;
}

