  }

  int ren=N;

  rep(i,Q){
    if(jo[i].c==0){
      if(uf.merge(jo[i].a, jo[i].b)) --ren;
    }
  }

  bool onearu=false;

  rep(i,Q){
    if(jo[i].c==1){
      onearu=true;
      if(uf.issame(jo[i].a, jo[i].b)){
        cout<< "No"<<"\n";
        return;
      }
    }
  }
  if((ren<=2 or M==N-1) and onearu){
    cout<< "No"<<"\n";
    return;
  }

  if(M>(ren*(ren-1))/2+ N-ren){
    cout<< "No"<<"\n";
    return;
  }

  cout<< "Yes"<<"\n";

}

