class UnionFind{
    public:
    //親の番号を格納する。親だった場合は-(その集合のサイズ)
    vector<ll> parent;

    UnionFind(ll N){
        parent = vector<ll>(N,-1);
    }

    ll root(ll A){
        if(parent[A] < 0) return A;
        return parent[A]=root(parent[A]);
    }

    ll size(ll A){
        return -parent[root(A)];
    }

    bool unite(ll A, ll B) {
        A = root(A), B = root(B);
        if(A == B) return false; 

        if(size(A) < size(B)) swap(A,B);
        parent[A] += parent[B];
        parent[B] = A;
        return true;
    }

    bool same(ll A, ll B){
        return root(A)==root(B);
    } 
};

