    cin >> a >> b >> c;
    if (c == 0) ds.merge(a, b);
    else diffQuery.eb(a, b);
  }
  for (auto &it : diffQuery) {
    if (ds.find(it.fi) == ds.find(it.se)) {
      cout << "No" << endl;
