struct DisjointSet {
  vector<int> pset, setSize;
  int setNum;

  DisjointSet() {}
  DisjointSet(int n) {
    initSet(n);
  }

  void initSet(int n) {
    pset.resize(n);
    setSize.assign(n, 1);
    setNum = n;
    for (int i = 0; i < n; i++) pset[i] = i;
  }

  int find(int n) { return pset[n] == n ? n : (pset[n] = find(pset[n])); }

  void merge(int i, int j) {
    i = find(i);
    j = find(j);
    if (i == j) return;
    if (rand() & 1) swap(i, j);
    pset[i] = j;
    setNum--;
  }
};

