        a[c].pb(mp(x,y));
    }
    if(m==n-1&&a[1].size()){
        puts("No");
        return 0;
    }
    UnionFind uf;
    uf.init(n+1);
    for (int i = 0; i < a[0].size(); i++) {
        uf.unite(a[0][i].fs,a[0][i].sc);
    }
    for (int i = 0; i < a[1].size(); i++) {
        if(uf.same(a[1][i].fs,a[1][i].sc)){
            puts("No");
            return 0;
        }
    }
    int k = 0,mm = 0;
    for (int i = 0; i < n; i++) {
        if(uf.find(i)==i){
            mm += uf.get_size(i) - 1;
            k++;
        }
    }
    if(m<=mm+k*(k-1)/2) puts("Yes");
    else puts("No");
    return 0;
}

