    int64_t c = 0;
    for(int i=0; i<N; i++) if(uf.find(i) == i) c++;
    int64_t mn = (c == 1 ? N-1 : N);
    int64_t mx = N-c+c*(c-1)/2;
    fin(mn <= M && M <= mx);
    return 0;
}

