int main() {
  cin.tie(nullptr); ios::sync_with_stdio(false);

  long N,M,Q; cin>>N>>M>>Q;

  vector<int> par(N);
  iota(par.begin(), par.end(), 0);
  auto root = [f=[&](auto g, int x) {
    if (par[x] == x)
      return x;
    return par[x] = g(g, par[x]);
  }](int x) {
    return f(f, x);
  };
  auto unite = [&](int x, int y) {
    return root(y) != (par[root(y)] = root(x));
  };

  vector<pair<int, int>> sconds, dconds;
  for (int q = 0; q < Q; q++) {
    int a, b, c; cin>>a>>b>>c;
    if (c == 0)
      sconds.emplace_back(a, b);
    else
      dconds.emplace_back(a, b);
  }
  long c_graph = N;
  for (auto cond : sconds) {
    if (unite(cond.first, cond.second))
      c_graph--;
  }
  for (auto cond : dconds) {
    if (root(cond.first) == root(cond.second)) {
      cout << "No" << endl;
      return 0;
    }
  }
  int c_min = dconds.empty() ? N-1 : N;
  bool ans = (M >= c_min) and (M <= N + c_graph*(c_graph-3)/2);
  cout << (ans ? "Yes" : "No") << endl;

  return 0;
}

