const ll MOD = 1000000007ll;

struct UF{
    vi dat;
    UF(int n){
        dat.assign(n,-1);
    }
    int root(int x){
        return dat[x]<0?x:dat[x]=root(dat[x]);
    }
    void unite(int a, int b){
        a=root(a);b=root(b);
        if(a==b)return;
        if(dat[a]>dat[b])swap(a,b);
        dat[a] += dat[b];
        dat[b] = a;
    }
    bool same(int a, int b){
        return root(a)==root(b);
    }
    int size(int a){
        return -dat[root(a)];
    }
};

int n;
ll m;
int q;

int main(){
    auto fail = [&](){puts("No");exit(0);};

    scanf("%d%lld%d",&n,&m,&q);
    UF suf(n), sduf(n), duf(n);
    while(q--){
        int a,b,c;
        scanf("%d%d%d",&a,&b,&c);
        if(c==0){
            // single
            if(sduf.same(a,b)){
                fail();
            }
            suf.unite(a,b);
            sduf.unite(a,b);
        }else{
            // double
            if(suf.same(a,b)){
                fail();
            }
            duf.unite(a,b);
            sduf.unite(a,b);
        }
    }
    ll low = 0, high = 0;
    int unu = 0;
    int mx = -1;
    REP(i,n){
        if(sduf.root(i)==i && sduf.size(i)==1){
            unu++;
            continue;
        }
        if(suf.root(i)==i){
            low += suf.size(i)-1;
            high += suf.size(i)-1;
        }
        if(duf.root(i)==i){
            CHMAX(mx, duf.size(i));
        }
    }
    REP(i,n){
        if(duf.root(i)==i && duf.size(i) > 1){
            ll sz = duf.size(i);
            if(sz == mx){
                sz += unu;
                unu = 0;
                mx = -1;
            }
            low += sz;
            high += sz * (sz-1) / 2;
        }
    }
    if(unu>0 && n>=2)unu++;
    high += 1ll * unu * (unu-1) / 2;
    if(m < low || high < m)fail();
    puts("Yes");
    return 0;
}

