class union_find_tree {
	std::vector<int> data;

	public:
	union_find_tree(const size_t && N)
		: data(N, -1) {}
	const bool unite(size_t x, size_t y) {
		x = find(x); y = find(y);
		if(x == y) return false;
		if(data[x] > data[y]) std::swap(x, y);

		data[x] += data[y];
		data[y] = x;
		return true;
	}
	const size_t find(size_t k) {
		if(data[k] < 0) return k;
		return data[k] = find(data[k]);
	}
	const size_t component_size(const size_t && k) {
		return -data[find(k)];
	}
	const bool same(const size_t && x, const size_t && y) {
		return find(x) == find(y);
	}

	void clear() { data.assign(size(), -1); }
	const size_t size() const { return data.size(); }
};

int main() {
	int n, m, q; scanf("%d%d%d", &n, &m, &q);
	std::vector<int> a(q), b(q), c(q);
	std::vector<int> A, B;
	for(int i = 0; i < q; i++) {
		scanf("%d%d%d", &a[i], &b[i], &c[i]);

		if(c[i] == 0) A.push_back(i);
		else B.push_back(i);
	}

	int tmp = 0;
	bool ans = true;
	i64 latte = A.size();
	union_find_tree uf(n);
	std::vector<bool> used(n, false);
	std::vector<std::pair<int, int>> edge;
	for(auto i: B) uf.unite(a[i], b[i]);
	for(auto i: B) {
		int c = uf.find(a[i]);
		if(used[c]) continue; used[c] = true;

		i64 cs = uf.component_size(a[i]);
		if(cs == 2) {
			edge.push_back({a[i], b[i]});
			latte++;
		} else latte += cs;
	}
	for(auto i: A) if(uf.same(a[i], b[i])) ans = false;

	i64 ma = 0;
	std::vector<bool> kiri(n, false);	
	for(auto i: A) {
		kiri[uf.find(a[i])] = kiri[uf.find(b[i])] = true;
		i64 X = uf.component_size(a[i]);
		i64 Y = uf.component_size(b[i]);
		ma = std::max({ma, X, Y});
	}

	i64 tan = 0;
	for(int i = 0; i < n; i++) if(!kiri[uf.find(i)]) tan++;

	i64 una = 0;
	std::vector<int> beet(n, 0);
	for(auto e: edge)beet[uf.find(e.first)]++;
	for(auto v: beet) {
		if(!v) continue;

		if(v == 1) {
			una++;
		} else {
			latte += v * 2;
			tan -= v;
		}
	}
	if(una == 1) {
		latte += 2;
		tan--;
	} else {
		latte += una;
	}
	if(tan < 0) ans = false;

	i64 malta = latte + tan * ma + tan * (tan - 1) / 2LL;
	if(!(latte <= m and m <= malta)) ans = false;

	for(auto i: A) {
		if(!uf.unite(a[i], b[i])) {
			ans = false;
		}
	}

	if(ans) printf("Yes\n");
	else printf("No\n");
	return 0;
}

