vector<edge>G;
int Find(int u) {
    if(u==fa[u])
        return u;
    return fa[u]=Find(fa[u]);
}
void Union(int u,int v) {
    int fu=Find(u),fv=Find(v);
    if(fu!=fv)
        fa[fu]=fv;
    return;
}
int main()
{
    //freopen("tour.in","r",stdin);
