        u++,v++;
        if(op==0)
            Union(u,v);
        else
            G.push_back(edge(u,v));
    }
    int cnt=0;
    for(int i=1;i<=n;i++)
        if(Find(i)==i)
            cnt++;
    LL mx=(LL)(cnt-1)*cnt/2+n-cnt;
    LL mi=(LL)(G.size()?n:n-1);
