signed main(){
  Int n,m,q;
  cin>>n>>m>>q;
  vector<Int> as(q),bs(q),cs(q);
  for(Int i=0;i<q;i++) cin>>as[i]>>bs[i]>>cs[i];

  // UF for BCC
  UnionFind bc(n),uf(n);
  for(Int i=0;i<q;i++){
    if(cs[i]!=1) continue;
    bc.unite(as[i],bs[i]);
    uf.unite(as[i],bs[i]);
  }

  Int num=0;
  for(Int i=0;i<q;i++){
    if(cs[i]!=0) continue;
    if(uf.same(as[i],bs[i])) drop("No");
    uf.unite(as[i],bs[i]);
    num++;
  }

  // assert(0);

  // isolated
  Int cnt=0;

  // # components that its size is 2
  Int v2=0;

  // lower_bound
  Int lb=num;
  for(Int i=0;i<n;i++){
    if(uf.size(i)==1){
      // isolated
      cnt++;
      continue;
    }
    if(bc.find(i)!=i) continue;
    Int sz=bc.size(i);
    if(sz==1) continue;
    if(sz==2) v2++;
    if(sz>=3) lb+=sz;
  }

  // check connected
  {
    Int sz=0;
    for(Int i=0;i<n;i++) chmax(sz,uf.size(i));
    // 1 component + isolated vertices
    assert(sz+cnt==n);
    assert(uf.count()==cnt+1);
  }

  // only connected !!?!?!!

  // number of isolated vertices is not enough
  //cout<<v2<<" "<<cnt<<endl;
  //if(v2>cnt+1) drop("No");
  //assert(0);

  //cnt-=v2;
  //lb+=v2*3;
  lb+=cnt;

  // upper_bound
  Int ub=num,mx=0;
  for(Int i=0;i<n;i++){
    if(uf.size(i)==1) continue;
    if(bc.find(i)!=i) continue;
    Int sz=bc.size(i);
    if(sz==1) continue;
    if(sz<=3) sz=3;
    ub+=sz*(sz-1)/2;
    chmax(mx,sz);
  }
  ub-=mx*(mx-1)/2;
  ub+=(mx+cnt)*(mx+cnt-1)/2;

  if(lb<=m&&m<=ub) drop("Yes");
  drop("No");
