struct DSU{
	int n;
	vector<int> par,siz;
	DSU(int n):n(n){
		par.resize(n);
		siz.resize(n,1);
		for(int i=0;i<n;i++){
			par[i]=i;
		}
	}	
	int find(int x){
		if(par[x]==x){
			return x;
		}
		return par[x]=find(par[x]);
	}
	void unite(int u,int v){
		u=find(u),v=find(v);
		if(u==v){
			return;
		}
		if(siz[u]<siz[v]){
			swap(u,v);
		}
		siz[u]+=siz[v];
		par[v]=u;
	}
};
