class UF{
  vector<int> par,rank,size_uf;
  int chunk_size;
public:
  UF(int size):chunk_size(size){
    for (int i = 0; i < size; i++) {
      par.push_back(i);
      rank.push_back(0);
      size_uf.push_back(1);
    }
  }
  int find(int x){
    if(par[x]==x)return x;
    return par[x]=find(par[x]);
  }
  void unite(int x,int y){
    x=find(x);
    y=find(y);
    if(x==y)return;
    --chunk_size;
    if(rank[x]<rank[y]){
      par[x]=y;
      size_uf[y]+=size_uf[x];
    }
    else{
      par[y]=x;
      size_uf[x]+=size_uf[y];
      if(rank[x]==rank[y])rank[x]++;
    }
  }
  bool same(int x,int y){
    return find(x)==find(y);
  }
  int operator [](int x){
    return this->find(x);
  }
  int size(int x){
    x=find(x);
    return size_uf[x];
  }
  int uf_size(){
    return this->chunk_size;
  }
};

const string YES = "Yes";
const string NO = "No";

void solve(long long N, long long M, long long Q, std::vector<long long> A, std::vector<long long> B, std::vector<long long> C){
  UF uf(N);
  tree<ll, null_type, less<ll>, rb_tree_tag, tree_order_statistics_node_update>  s;
  REP(Q){
    if(C[i]==0){
      uf.unite(A[i],B[i]);
    }
  }
  REP(N){
    s.insert(uf[i]);
  }
  UF ufuf(s.size());
  REP(Q){
    if(C[i]){
      ll tmpa=s.order_of_key(uf[A[i]]),tmpb=s.order_of_key(uf[B[i]]);
      if(uf.same(A[i],B[i])){
        cout<<NO<<endl;
        return;
      }
      ufuf.unite(tmpa,tmpb);
    }
  }
  if(uf.uf_size()==2&&ufuf.uf_size()==1){
    cout<<NO<<endl;
    return ;
  }
  ll tmp=uf.uf_size()-ufuf.uf_size();
  ll tmp2=(tmp==0?0:(tmp==1?3:tmp+1));
  ll min_edge=N-uf.uf_size()+tmp2;
  ll max_edge=N-uf.uf_size()+(uf.uf_size()*(uf.uf_size()-1))/2;
  if(min_edge<=M&&M<=max_edge){
    cout<<YES<<endl;
  }else{
    cout<<NO<<endl;
  }
}

