	int num = 0; ll ma = 0;
	rep(i, q) {
		int a, b, c; cin >> a >> b >> c;
		if (c == 0) {
			/*if (u.same(a, b)) {
				cout << "No" << endl; return;
			}*/
			if (!u.same(a, b)) {
				num++; ma++;
			}
			u.unite(a, b);
		}
		else {
			v.push_back({ a,b });
		}
	}
	rep(i, v.size()) {
		int l = v[i].first, r = v[i].second;
		l = u.find(l), r = u.find(r);
		if (l==r) {
			cout << "No" << endl; return;
		}
		G[l].push_back(r); G[r].push_back(l);
	}
	vector<bool> chked(n, false);

	ll dr = 0;
	vector<ll> z;
	int ad = 0;
	bool exi = false;
	rep(i, n) {
		int p = u.find(i);
		if (chked[p])continue;
		queue<int> q; q.push(p); chked[p] = true;
		vector<int> ids;
		while (!q.empty()) {
			int id = q.front(); q.pop();
			ids.push_back(id);
			rep(j, G[id].size()) {
				int to = G[id][j];
				if (chked[to])continue;
				chked[to] = true;
				q.push(to);
			}
		}
		int edges = 0;
		rep(j, ids.size()) {
			int id = ids[j];
			edges += G[id].size();
		}
		edges /= 2;
		if (ids.size() > 2) {
			exi = true;
			num += max(edges, (int)ids.size());
		}
		else if (ids.size() == 2) {
			ad++;
		}
		ll len = ids.size();
		dr += len;
		z.push_back(len);
	}
	if (z == vector<ll>{2}) {
		cout << "No" << endl; return;
	}
	if (exi) {
		num += 2 * ad+1;
	}
	else if(ad>0){
		num += 2 * ad + 1;
	}


	//cout << num << " " << ma << endl;
	ma += dr * (dr - 1) / 2;
	if (m < num || ma < m) {
		cout << "No" << endl; return;
	}
	cout << "Yes" << endl;
}

