int main()
{
	scanf("%d%d%d", &n, &m, &q);
	for (int i = 1; i <= n; i++) p[i] = i;
	g = n;
	vector<pair<int, int>> es;
	for (int i = 1; i <= q; i++)
	{
		int u, v, w;
		scanf("%d%d%d", &u, &v, &w);
		u++; v++;
		if (w == 0) { //u,v belong to the same tree
			int ur = root(u), vr = root(v);
			if (ur != vr)
			{
				p[root(u)] = root(v);
				g--; m--;
			}
		}
		else es.push_back(make_pair(u, v));
	}
	vector<pair<int, int>> es2;
	for (auto& e : es)
	{
		int ur = root(e.first), vr = root(e.second);
		if (ur == vr)
		{
			printf("No\n");
			return 0;
		}
		es2.push_back(make_pair(min(ur, vr), max(ur, vr)));
	}
	if (g == 1) // graph is a tree
	{
		printf("%s\n", m == 0 ? "Yes" : "No");
		return 0;
	}
	if (g == 2) // two supernodes
	{
		if (es2.size()) printf("No\n"); // can't make multiple paths
		else if (m != 1) printf("No\n"); // graph needs to be connected
		else printf("Yes\n");
		return 0;
	}
	// g>=3 supernodes left, any pair in es2 need multiple paths in between, using m edges
	ll ub = g * (g + 1) / 2; // max number of edges can be added
	ll lb = es2.empty() ? g - 1 : g; // min number of edges need to be added
	// graph is connect so we need at least g-1, but if we need multiple paths we need at least one more
	if (lb <= m && m <= ub) printf("Yes\n");
	else printf("No\n");
	return 0;
}

