        if(uf.sameParent(v[i].first,v[i].second)){
            cout<<"No"<<endl;
            return 0;
        }
    }
    //単純パス1本のもののみで木を作る
    //k:連結成分の個数
    int k=uf.c;
    /*
    木なら単に連結成分同士をつなげて一つの大きな木にすればいい。
    それ以外ならサイクルを作るなり全点対全点をつなげるなりすれば勝手にパス2個以上できる
    */
   if(m<=n-k+k*(k-1)/2){
       cout<<"Yes"<<endl;
   }
   else{
       cout<<"No"<<endl;
   }

    return 0;
}

