        if (clues[i].c == 0) {
            merge(clues[i].a, clues[i].b);
        }
    }

    set<pii> edges;

    for (int i = 0; i < q; i++) {
        if (clues[i].c == 0) continue;
        int u = clues[i].a;
        int v = clues[i].b;
        u = find(u);
        v = find(v);
        if (u == v) {
            cout << "No\n";
            return 0;
        }
        if (u > v) swap(u, v);
        if (edges.count({u, v})) {
            cout << "No\n";
            return 0;
        }
        edges.insert({u, v});
    }

    int k = 0;

    for (int i = 1; i <= n; i++) {
        if (i == find(i)) {
            k++;
        }
    }

    if (n + 1ll * k * (k - 3) / 2 < m) {
        cout << "No\n";
    } else {
        cout << "Yes\n";
    }

    return 0;
}

