class UnionFind {
private:
	long long Size;
	vector<long long> Parent, Rank;
public:
	UnionFind(long long N) : Size(N) {
		Parent.resize(N);
		Rank.resize(N);
		for (int i = 0; i < N; i++) {
			Parent[i] = i;
			Rank[i] = 0;
		}
	}
	long long Root(long long N) {
		if (N == Parent[N]) {
			Rank[N] = 0;
			return N;
		}
		Rank[N] = 1;
		return Parent[N] = Root(Parent[N]);
	}
	bool Same(long long A, long long B) {
		return Root(A) == Root(B);
	}
	void Merge(long long A, long long B) {
		long long RA = Root(A), RB = Root(B);
		if (Rank[RA] < Rank[RB]) {
			Parent[RA] = RB;
			Rank[RA]++;
		}
		else {
			Parent[RB] = Root(RA);
			Rank[RB]++;
		}
	}
};

int main() {
