#include <bits/stdc++.h>
using namespace std;
using lint = long long;
template<class T = int> using V = vector<T>;
template<class T = int> using VV = V< V<T> >;

struct UnionFind {
  const int n;
  V<> t; // root ? -sz : par
  UnionFind(int n) : n(n), t(n, -1) {}
  int find(int v) { return t[v] < 0 ? v : t[v] = find(t[v]); }
  void unite(int u, int v) {
    if ((u = find(u)) == (v = find(v))) return;
    if (-t[u] < -t[v]) swap(u, v);
    t[u] += t[v];
    t[v] = u;
  }
  bool same(int u, int v) { return find(u) == find(v); }
  int size(int v) { return -t[find(v)]; }
};

int main() {
  cin.tie(nullptr); ios::sync_with_stdio(false);
  lint n, m, q; cin >> n >> m >> q;
  V<> a(q), b(q), c(q); 
  set<int> se;
  for (int i = 0; i < q; ++i) {
    cin >> a[i] >> b[i] >> c[i];
    se.insert(a[i]);
    se.insert(b[i]);
  }
  int r = n - se.size();

  UnionFind uf(n);
  for (int i = 0; i < q; ++i) if (!c[i]) {
    uf.unite(a[i], b[i]);
  }

  lint ub = n * (n - 1) / 2;
  set<int>().swap(se);
  for (int v = 0; v < n; ++v) {
    se.insert(uf.find(v));
  }
  for (int e : se) {
    lint sz = uf.size(e);
    ub -= sz * (sz - 1) / 2;
    ub += sz - 1;
  }
  if (m > ub) {
    return cout << "No" << '\n', 0;
  }

  for (int e : se) {
    m -= uf.size(e);
  }

  for (int i = 0; i < q; ++i) if (c[i]) {
    if (uf.same(a[i], b[i])) {
      return cout << "No" << '\n', 0;
    }
  }
  // m -= n - 1;
  for (int i = 0; i < q; ++i) if (c[i]) {
    if (uf.same(a[i], b[i])) continue;
    uf.unite(a[i], b[i]);
    if (!m or !r) {
      return cout << "No" << '\n', 0;
    }
    --m;
  }

  // assert(false);
  cout << "Yes" << '\n';
}

