	return parent[x] = find(parent[x]);
}
bool unite (ull a, ull b) {
	a = find(a);
	b = find(b);

	if (a == b) return false;

	if (size[a] < size[b]) {
		ull t = a;
		a = b;
		b = t;
	}
	size[a] += size[b];
	parent[b] = a;
	return true;
}

