struct union_find{
    VI par;

    void init(int n){
        par.resize(n);
        REP(i,n) par[i] = i;
    }

    int find(int x){
        if (par[x] == x) return x;
        else return par[x] = find(par[x]);
    }

    bool same(int x, int y){
        return find(x) == find(y);
    }

    void merge(int x, int y){
        x = find(x);
        y = find(y);
        if (x == y) return;
        par[x] = y;
    }
};

bool solve(){
    ll n, m, q;
    cin >> n >> m >> q;
    VI u1, v1, u2, v2;
    REP(i,q){
        int u = in(), v = in(), c = in();
        if (c == 0){
            u1.push_back(u);
            v1.push_back(v);
        }else{
            u2.push_back(u);
            v2.push_back(v);
        }
    }
    union_find uf;
    uf.init(n);
    REP(i,u1.size()){
        if (uf.same(u1[i], v1[i])){
            return false;
        }
        uf.merge(u1[i], v1[i]);
    }
    REP(i,u2.size()){
        if (uf.same(u2[i], v2[i])){
            return false;
        }
    }
    ll c = 0;
    REP(i,n) if (uf.find(i) == i) c++;
    m -= n - c;
    if (u2.empty()){
        return m >= c - 1 && m <= c * (c - 1) / 2;
    }else{
        return m >= c && m <= c * (c - 1) / 2;
    }
}

