class unionFind{
    vi node;
public:
    unionFind(int n){
        node = vi(n);
        iota(all(node), 0);
    }

    int root(int x){
        if(node[x] == x) return x;
        return node[x] = root(node[x]);
    }

    void uni(int x, int y){
        x = root(x);
        y = root(y);
        if(x != y) node[x] = y;
    }
};

