class UnionFind {
private:
	std::vector<int> par;
	std::vector<int> siz;

public:
	UnionFind(int sz_) : par(sz_), siz(sz_, 1) {
		for (int i = 0; i < sz_; ++i) par[i] = i;
	}
	void init(int sz_) {
		par.resize(sz_);
		siz.resize(sz_, 1);
		for (int i = 0; i < sz_; ++i) par[i] = i;
	}
	int find(int x) {
		while (par[x] != x) x = par[x] = par[par[x]];
		return x;
	}
	void unite(int x, int y) {
		x = find(x);
		y = find(y);
		if (x == y) return;
		if (siz[x] < siz[y]) std::swap(x, y);
		siz[x] += siz[y];
		par[y] = x;
	}
	bool same(int x, int y) {
		return find(x) == find(y);
	}
	int size(int x) {
		return siz[find(x)];
	}
};

std::map<PAIR, int> map;

bool check() {
	VAR(int, n, m, q);
	VEC_ROW(int, q, a, b, c);
	UnionFind uf(n);

	int sz = n;
	int sum = 0;
	REP(i, q) {
		if (a[i] > b[i]) std::swap(a[i], b[i]);
		if (map.count({ a[i], b[i] })) {
			if (map[{a[i], b[i]}] != c[i]) return false;
			continue;
		}
		map[{a[i], b[i]}] = c[i];

		if (c[i] == 0) {
			if (uf.same(a[i], b[i])) continue;
			uf.unite(a[i], b[i]);
			++sum;
			--sz;
		}
	}
	REP(i, q) {
		if (c[i] == 1) {
			if (uf.same(a[i], b[i])) return false;
		}
	}
	return IN(sum + sz, m, sum + sz * (sz - 1) / 2 + 1);
}

signed main() {
	INIT;

	OUT(check() ? "Yes" : "No")BR;

