struct UnionFind {
    int N;
    vector<int> node;

    UnionFind(){}
    UnionFind(int N) : N(N), node(N,-1) {}

    void init(int x) {
        node.assign(x,-1);
        N = x;
    }

    bool merge(int x, int y) {
        x = root(x); y = root(y);
        if (x == y) return false;
        if (node[x] > node[y]) swap(x,y);
        node[x] += node[y];
        node[y] = x;
        N--;
        return true; 
    }

    bool same(int x, int y) {return root(x) == root(y);}

    int root(int x) {
        if (node[x] < 0) return x;
        return node[x] = root(node[x]);
    }

    int size(int x) {return -node[root(x)];}

    int count() const {return N;}
};

void No() {
    cout << "No" << ln;
    exit(0);
}

int main() {
    ll N,M,Q; cin >> N >> M >> Q;
    vector<int> A(Q),B(Q),C(Q);
    rep(i,Q) cin >> A[i] >> B[i] >> C[i];

    UnionFind uf(N);
    rep(i,Q) {
        if (!C[i]) uf.merge(A[i],B[i]);
    }

    rep(i,Q) {
        if (C[i] and uf.same(A[i],B[i])) No();
    }

    ll MAX = 0;
    set<int> dic;
    ll cnt = 0;
    rep(i,N) if (uf.size(i) >= 2) {
        dic.emplace(uf.root(i));
        cnt++;
    }
    ll S = SZ(dic);
    MAX = cnt - S;
    ll a = N - cnt + S;
    MAX += a*(a-1)/2;
    if (MAX < M) No();

    ll MIN = accumulate(all(C),0)==0 ? N-1 : N;
    if (M < MIN) No();

    cout << "Yes" << ln;
}

