	return t[x] = par(t[x]);
}

bool u(int x, int y) {
	x = par(x);
	y = par(y);
	if (x == y)return false;
	if (t[x] < t[y]) {
		t[x] += t[y];
		t[y] = x;
	}
	else {
		t[y] += t[x];
		t[x] = y;
	}
	return true;
}


