vector<int> parent(100010);
vector<int> ran(100010);

void init(int n) {
	for (int i = 0; i < n; i++) {
		parent[i] = i;
		ran[i] = 0;
	}
}

int find(int x) {
	if (parent[x] == x) return x;
	else return parent[x] = find(parent[x]);
}

void unite(int x, int y) {
	x = find(x);
	y = find(y);
	if (x == y) return;
	if (ran[x] < ran[y]) parent[x] = y;
	else {
		parent[y] = x;
		if (ran[x] == ran[y]) ran[x]++;
	}
}

