    // M = N - 1 の時は木構造のグラフとなる．
    if ( multi_pair_list.size() > 0 ) {
      // その場合複数経路はありえない．
      no();
    }
    else {
      yes();
    }
  }

#if 0
  if ( !has_single ) {
    yes();
  }
#endif

  int K = 0;
  for ( int i = 0; i < N; ++ i ) {
    if ( mfset.find(i) == i ) {
      ++ K;
    }
  }

  if ( K == 2 ) {
    K = 1;
  }

  int M_max = N + (K * (K - 3)) / 2;
  if ( M > M_max ) {
    if ( !has_single ) {
      abort();
    }
    no();
  }

  for ( auto p: multi_pair_list ) {
    int a = p.first;
    int b = p.second;
    if ( mfset.find(a) == mfset.find(b) ) {
      no();
    }
  }

  yes();

  return 0;
}

