int ask(int x) {return fa[x]==x?x:fa[x]=ask(fa[x]);}

void addedge(int x,int y,int v)
{
	e[++cnt]=(node){y,hd[x],v,0},hd[x]=cnt;
	e[++cnt]=(node){x,hd[y],v,0},hd[y]=cnt;
}

void dfs(int x)
{
	bo[x]=1;
	for (int i=hd[x]; i; i=e[i].next)
		if (e[i].to!=fa[x]&&e[i].bo)
		{
			dep[e[i].to]=dep[x]+1;
			if (!e[i].val) f[e[i].to]=dep[e[i].to],g[e[i].to]=g[x]; else f[e[i].to]=f[x],g[e[i].to]=dep[e[i].to];
			fa[e[i].to]=x,dfs(e[i].to);
		}
}

int lca(int x,int y)
{
	if (dep[x]<dep[y]) swap(x,y);
	for (int j=17; j>=0; j--)
		if (dep[F[x][j]]>=dep[y]) x=F[x][j];
	if (x==y) return x;
	for (int j=17; j>=0; j--)
		if (F[x][j]!=F[y][j]) x=F[x][j],y=F[y][j];
	return F[x][0];
}

