struct UnionFind {
    int cnt;                   // 集合の数
    vector<int> number;        // 0以上のとき親のindex, 負のときは集合サイズ
    vector<int> data1, data2;  // 連結成分ごとのデータ
    UnionFind(int n) : cnt(n), number(n, -1) {}
    UnionFind(const vector<int>& data1, const vector<int>& data2)
        : cnt(data1.size()), number(data1.size(), -1), data1(data1), data2(data2) {}
    int root(int x) { return number[x] < 0 ? x : number[x] = root(number[x]); }
    void unite(int x, int y) {
        x = root(x);
        y = root(y);
        if (x == y) return;
        if (number[y] < number[x]) swap(x, y);
        // yをxにマージ
        number[x] += number[y];
        number[y] = x;
        // // dataのマージ方法に合わせて変える
        // data1[x] += data1[y];
        // data2[x] += data2[y];
        cnt--;
    }
    bool is_same(int x, int y) { return root(x) == root(y); }
    int size(int x) { return -number[root(x)]; }
    int& ref1(int x) { return data1[root(x)]; }
    int& ref2(int x) { return data2[root(x)]; }
};

signed main() {
    int n, m, Q; cin >> n >> m >> Q;
    vector<ii> ps;
    UnionFind uf(n);
    REP (i, Q) {
        int u, v, c; cin >> u >> v >> c;
        if (c == 0) {
            uf.unite(u, v);
        } else {
            ps.push_back({u, v});
        }
    }
    bool ng = false;
    for (auto& p : ps) {
        if (uf.is_same(p.fi, p.se)) ng = true;
        uf.unite(p.fi, p.se);
    }
    int cnt = 0;
    REP (i, n) {
        if (uf.size(i) == 1) cnt++;
    }
    if (cnt == 0 && ps.size() != 0) ng = true;

    int e = uf.cnt - 1;
    REP (i, n) {
        if (uf.root(i) == i) e += uf.size(i) - 1;
    }
    int mi = e;
    if (ps.size()) mi++;
    if (m < mi) ng = true;

    int ma = e;
    ma += uf.cnt * (uf.cnt - 1) / 2 - (uf.cnt - 1);
    if (m > ma) ng = true;

    cout << (ng ? "No" : "Yes") << endl;
}

