	}
	int used = 0;
	for (auto i : sz) {
		used += max(0,i - 1);
	}
	long long int node = one.size();
	for (auto i : sz) {
		node += i >= 2;
	}
	//cout << used << " " << node << endl;
	if (P.empty()) {
