	mll operator / (const mll &b) const { return mll(*this) /= b; }
	mll operator + (ll b) const { return *this + mll(b); }
	mll operator - (ll b) const { return *this - mll(b); }
	mll operator * (ll b) const { return *this * mll(b); }
	friend mll operator + (ll a, const mll &b) { return b + a; }
	friend mll operator - (ll a, const mll &b) { return -b + a; }
	friend mll operator * (ll a, const mll &b) { return b * a; }
	mll &operator += (const mll &b) { val=(val+b.val)%MOD; return *this; }
	mll &operator -= (const mll &b) { val=(val+MOD-b.val)%MOD; return *this; }
	mll &operator *= (const mll &b) { val=(val*b.val)%MOD; return *this; }
	mll &operator /= (const mll &b) {
		ll c=b.val, d=MOD, u=1, v=0;
		while (d){
			ll t = c / d;
			c -= t * d; swap(c, d);
			u -= t * v; swap(u, v);
		}
		val = val * u % MOD;
		if (val < 0) val += MOD;
		return *this;
	}
	mll &operator += (ll b) { return *this += mll(b); }
	mll &operator -= (ll b) { return *this -= mll(b); }
	mll &operator *= (ll b) { return *this *= mll(b); }
	mll &operator /= (ll b) { return *this /= mll(b); }
	bool operator == (const mll &b) { return val == b.val; }
	bool operator != (const mll &b) { return val != b.val; }
	bool operator == (ll b) { return *this == mll(b); }
	bool operator != (ll b) { return *this != mll(b); }
	friend bool operator == (ll a, const mll &b) { return mll(a) == b.val; }
	friend bool operator != (ll a, const mll &b) { return mll(a) != b.val; }
	friend ostream &operator << (ostream &os, const mll &a) { return os << a.val; }
	friend istream &operator >> (istream &is, mll &a) { return is >> a.val; }
	static mll Combination(ll a, ll b){
		chmin(b, a-b);
		if (b<0) return mll(0);
		mll c = 1;
		REP(i, b) c *= a-i;
		REP(i, b) c /= i+1;
		return c;
	}
};
ll mll::MOD = 998244353LL;//(ll)(1e9 + 7);


class UnionFindTree{
private:
	vll par;
	vll rank;
public:
	UnionFindTree(ll num): par(num), rank(num) { REP(i, num) par[i] = i; }
	bool same(ll x, ll y) { return root(x) == root(y); }
	ll root(ll x) { return (par[x] == x) ? x : par[x]=root(par[x]); }
	void unite(ll x, ll y){
		x = root(x);
		y = root(y);
		if (x == y) return;
		if (rank[x] < rank[y]) par[x] = y;
		else                   par[y] = x;
		if (rank[x] == rank[y]) rank[x]++;
	}
};


void solve()
{
	ll N, M, Q;
	cin >> N >> M >> Q;
	auto ABC = cinv3(Q);
	vector<pair<ll, ll>> AB0;
	vector<pair<ll, ll>> AB1;
	EACH(e, ABC){
		ll A = get<0>(e);
		ll B = get<1>(e);
		ll C = get<2>(e);
		if (C == 0) AB0.emplace_back(A, B);
		else        AB1.emplace_back(A, B);
	}

	UnionFindTree uft(N);
	EACH(e, AB0){
		ll A = e.first;
		ll B = e.second;
		uft.unite(A, B);
	}

	set<ll> buf;
	REP(i, N){
		buf.insert(uft.root(i));
	}
	ll groupNum = buf.size();

	if (groupNum <= 2){
		if (AB1.empty()) cout << "Yes" << '\n';
		else             cout << "No" << '\n';
		return;
	}

	bool isOK = true;
	EACH(e, AB1){
		ll A = e.first;
		ll B = e.second;
		if (uft.same(A, B)){
			isOK = false;
			break;
		}
	}

	if (isOK) cout << "Yes" << '\n';
	else      cout << "No" << '\n';
}

int main(){
	solve();
	return 0;
}

