using namespace std;
typedef long long ll;
class UnionFind{//UnionFind木
 private:
    vector<int> Parent,es;
    vector<ll> diff_weight;
 public:
    UnionFind(int N){
        es.resize(N,0);
        Parent.resize(N,-1);
        diff_weight.resize(N,0LL);
    }

    int root(int A){
        if(Parent[A]<0) return A;
        else{ 
            int r = root(Parent[A]);
            diff_weight[A] += diff_weight[Parent[A]]; // 累積和をとる
            return Parent[A]=r;
        }
    }
    bool issame(int A,int B){
        return root(A)==root(B);
    }
    ll weight(int x) {
        root(x); // 経路圧縮
        return diff_weight[x];
    }
    ll diff(int x, int y) {
        return weight(y) - weight(x);
    }
    int size(int A){
        return -Parent[root(A)];
    }
    int eize(int A){
        return es[root(A)];
    }
    bool connect(int A,int B){
        A=root(A); B=root(B);
        if(A==B) return false;
        if(size(A)<size(B)) swap(A,B);
        Parent[A]+=Parent[B];
        es[A]+=es[B]+1;
        Parent[B]=A;
        return true;
    }
    void unite(int A,int B){
        A=root(A); B=root(B);
        if(A==B){ 
            es[A]++;
            return;
        }
        if(size(A)<size(B)) swap(A,B);
        Parent[A]+=Parent[B];
        es[A]+=es[B]+1;
        Parent[B]=A;
        return;
    }
    bool merge(int A, int B, ll w) {
        // x と y それぞれについて、 root との重み差分を補正
        w += weight(A); w -= weight(B); 
        A=root(A); B=root(B);
        if(A==B) return false;
        if(size(A)<size(B)) swap(A,B),w=-w;
        Parent[A]+=Parent[B];
        Parent[B]=A;
        // x が y の親になるので、x と y の差分を diff_weight[y] に記録
        diff_weight[B] = w; 
        return true;
    }
};
int main(){
    ll N,M,Q;
    cin>>N>>M>>Q;
    UnionFind uni(N);
    vector<tuple<int,int,int>> q(Q);
    REP(i,Q){
        int a,b,c;cin>>a>>b>>c;
        q[i]=tie(c,a,b);

    }
    sort(All(q));
    if(M==N-1){
        if(get<0>(q.back())==1) cout<<"No"<<endl;
        else cout<<"Yes"<<endl;
        return 0;
    }
    REP(i,Q){
        int a,b,c;
        tie(c,a,b)=q[i];
        if(c==0) uni.connect(a,b);
        if(c==1&&uni.issame(a,b)){
            cout<<"No"<<endl;
            return 0;
        }
    }
    ll num=0;
    vector<bool> used(N,false);
    REP(i,N) if(!used[uni.root(i)]){
        used[uni.root(i)]=true;
        num++;
    }
    if(M<=N-num+num*(num-1)/2) cout<<"Yes"<<endl;
    else cout<<"No"<<endl;

}

