LL read() {
    using namespace _buff;
    LL ret = 0;
    bool pos = true;
    char c = getc();
    for (; (c < '0' || c > '9') && c != '-'; c = getc()) {
        assert(~c);
    }
    if (c == '-') {
        pos = false;
        c = getc();
    }
    for (; c >= '0' && c <= '9'; c = getc()) {
        ret = (ret << 3) + (ret << 1) + (c ^ 48);
    }
    return pos ? ret : -ret;
}

int main() {
    int n = read();
    LL  m = read();
    int q = read();

    vector<int> par(n + 1), siz(n + 1);
    iota(par.begin(), par.end(), 0);
    fill(siz.begin(), siz.end(), 1);
    function<int(int)> find = [&](int x) {
        return par[x] == x ? x : (par[x] = find(par[x]));
    };
    function<bool(int, int)> merge = [&](int x, int y) {
        x = find(x); y = find(y);
        if (x == y) return false;
        if (siz[x] < siz[y]) swap(x, y);
        par[y] = x; siz[x] += siz[y];
        return true;
    };

    vector<pair<int, int> > c1;
    LL cur = m;
    while (q--) {
        int a = read(), b = read();
        if (read() == 0) {
            cur -= merge(a, b);
        } else {
            c1.emplace_back(a, b);
        }
    }

    int comp = 0;
    for (int i = 1; i <= n; ++i) {
        if (find(i) == i) {
            ++comp;
        }
    }
    for (auto &pr : c1) {
        int x = pr.first;
        int y = pr.second;
        if (find(x) == find(y)) {
            return puts("No"), 0;
        }
    }
    LL lb = c1.empty() ? comp - 1 : max(3, comp);
    LL rb = (LL) comp * (comp - 1) / 2;
    puts(lb <= cur && cur <= rb ? "Yes" : "No");
    return 0;
}

