    s[c].emplace_back(a, b);
  }
  dsu ss(n);
  int comp = n;
  for(auto u : s[0]) {
    comp -= ss.unite(u.first, u.second);
  }
  if(comp == 2) {
    cout << "No";
    return 0;
  }
  for(auto u : s[1]) {
    if(ss.get(u.first) == ss.get(u.second)) {
      cout << "No";
