    }
  }
  long long L = n - (s[1].empty());
  vector<int> scc(n);
  range(i, 0, n) scc[ss.get(i)]++;
  sort(scc.begin(), scc.end(), greater<int>());
  while(scc.back() == 0) scc.pop_back();
  long long R = n - comp;
  while(!scc.empty()) {
    int sz = scc.size();
    if(sz != 2) R += 1LL * sz * (sz - 1) / 2;
