		int &i = p.first, &j = p.second;
		if(!of_tree.mrg(i, j)){
			// DEBUG("E1: %d-%d already connected\n", i, j);
		 	// no();
		}
		of_big_tree.mrg(i, j);
		used.emplace(i); used.emplace(j);
	}
	for(pii &p : query[1]){
		int &i = p.first, &j = p.second;
		if(!of_big_tree.mrg(i, j)){
			if(of_tree.mrg(i, j)){
				DEBUG("%d-%d: same small tree\n", i, j);
			 	no();
			}
			if(of_loop.mrg(i, j)){
				DEBUG("%d-%d loop from different place on tree\n", i, j);
				no();
			}
		}
		of_loop.mrg(i, j);
		used.emplace(i); used.emplace(j);
	}
	int more_v = 0;
	REP(ii, n){ // for each loop group
		int i = of_loop.grp(ii),
				j = of_big_tree.grp(ii);
		if(i != ii) continue;
		if(of_loop.sz(i) == 1) continue;
		if(of_loop.sz(i)==2){
			more_v++;
		}
		lpcnt[j]++;
	}
	m -= n-1; // tree
	int mrg = -1;
	REP(i, n){
		if(lpcnt[i]) {
			DEBUG("lpcnt[%d]=%d\n", i, lpcnt[i]);
			m -= lpcnt[i];
			mrg++;
		}
	}
	if(mrg >= 0){
		m += mrg;
	}
	if(m < 0){
		DEBUG("Not enough vertices\n");
	 	no();
	}
	DEBUG("more_v = %d\n", more_v);
	if(more_v == 1 && (int)used.size() == n) no();
	yes();
}

