bool has_good_loop(const Graph& g) {
	vll visited(g.size());
	vll visited2(g.size());
	auto dfs2 = [&](auto dfs2, ll node, ll state) -> bool {
		visited2[node] = 1;
		for (auto& e : g.out(node)) {
			if (visited[e->to] != 1)
				continue;
			if (state != e->cost)
				return false;
			if (visited2[e->to] == 1)
				return state == e->cost;
			else if (visited2[e->to] == 0 && !dfs2(dfs2, e->to, state))
				return false;
		}
		visited2[node] = 2;
		return true;
	};
	auto dfs = [&](auto dfs, ll node) -> bool {
		visited[node] = 1;
		for (auto& e : g.out(node)) {
			if (visited[e->to] == 1)
			{
				return dfs2(dfs2, e->to, e->cost);
			}
			else if (visited[e->to] == 0 && !dfs(dfs, e->to))
				return false;
		}
		visited[node] = 2;
		return true;
	};
	rep(i, 0, g.size()) {
		if (!dfs(dfs, i))
			return false;
	}
	return true;
}

