struct SizeAwareUnionFind
{
    vector<int> par, cou;
    SizeAwareUnionFind(int N) : par(N), cou(N) { REP(i, N) par[i] = i, cou[i] = 1; }
    int find(int x) { return (par[x] == x) ? x : (par[x] = find(par[x])); }
    void unite(int x, int y) {
        x = find(x), y = find(y); if (x == y) return;
        if (cou[x] < cou[y]) swap(x, y); 
        par[y] = x, cou[x] += cou[y];
    }
    int count(int x) { return cou[find(x)]; }
    bool same(int x, int y) { return find(x) == find(y); }
};

int main()
{
    int N, M, Q;
    cin >> N >> M >> Q;
    SizeAwareUnionFind uf(N);
    vector<pint> E;
    REP(q, Q)
    {
        int a, b, c;
        cin >> a >> b >> c;
        if (c == 0)
        {
            uf.unite(a, b);
        }
        else
        {
            E.emplace_back(a, b);
        }
    }
    if (M == N - 1) {
        if (E.size()) No();
        else Yes();
    }

    for (auto p : E) if (uf.same(p.first, p.second)) No();

    map<int, int> g2s;
    REP(i, N) g2s[uf.find(i)] = uf.count(i);

    lint tree_edge = 0;

    for (auto p : g2s) tree_edge += p.second - 1;

    lint hi = 0;
    lint nb_grp = 0;
    for (auto p : g2s)
    {
        nb_grp++;
        hi += p.second - 1;
    }
    hi += nb_grp * (nb_grp - 1) / 2;

    if (M > hi) No();
    else Yes();
}

