class unionfind
{
public:
    unionfind(const usize sz) : sz{sz}, rt(sz), comp_sz(sz, 1) { std::iota(rt.begin(), rt.end(), 0); }
    usize root(const usize a) { return assert(a < sz), rt[a] == a ? a : rt[a] = root(rt[a]); }
    bool same(const usize a, const usize b) { return assert(a < sz), assert(b < sz), root(a) == root(b); }
    bool unite(usize a, usize b)
    {
        assert(a < sz), assert(b < sz), a = root(a), b = root(b);
        if (a == b) { return false; }
        if (comp_sz[a] < comp_sz[b]) { std::swap(a, b); }
        return comp_sz[a] += comp_sz[b], rt[b] = a, true;
    }
    usize size() const { return sz; }
    usize size_of(const usize a) { return assert(a < sz), comp_sz[root(a)]; }
    friend std::ostream& operator<<(std::ostream& os, const unionfind& uf)
    {
        os << "[";
        for (usize i = 0; i < uf.sz; i++) { os << uf.rt[i] << (i + 1 == uf.sz ? "" : ","); }
        return (os << "]\n");
    }

private:
    const usize sz;
    std::vector<usize> rt, comp_sz;
};
int main()
{
    const auto n = read<usize>();
    const auto m = read<ll>();
    const auto q = read<usize>();
    unionfind uf(n);
    std::vector<usize> a(q), b(q), c(q);
    ll cn = n;
    for (usize i = 0; i < q; i++) {
        std::cin >> a[i] >> b[i] >> c[i];
        if (c[i] == 0) {
            if (uf.unite(a[i], b[i])) { cn--; }
        }
    }
    for (usize i = 0; i < q; i++) {
        if (c[i] == 1 and uf.same(a[i], b[i])) { return std::cout << "No" << std::endl, 0; }
    }
    const ll min = std::min(m, (ll)n), max = (ll)n - cn + (cn - 1) * cn / 2;
    std::cout << (min <= m and m <= max ? "Yes" : "No") << std::endl;
    return 0;
}

