// Union-Find
struct UnionFind {
    vector<int> par;
    vector<int> scale1;
    vector<int> rank;
    int size;
    // par[i]はiの親の番号
    // rank[i]はiが親の時にのみ意味を持ち, その木のrank(union操作に使う)
    // sizeは木の数

    //最初は全てが根であるとして初期化
    UnionFind(int N) : par(N), scale1(N,1), rank(N,0){
        for(int i = 0; i < N; i++) par[i] = i;
        size = N;
    }

    // データxが属する木の根を再帰で得る
    int root(int x){
        if (par[x] == x) return x;
        par[x] = root(par[x]); // 親を根にする付け替えによって次回以降の参照を高速化
        return par[x];
    }

    // xとyの木を併合(rankの大きい方の根を小さい方の根の親にする)
    void unite(int x, int y){
        int rx = root(x);
        int ry = root(y);
        if (rx == ry) return;
        if(rank[rx] > rank[ry]){
            par[ry] = rx;
            scale1[rx] += scale1[ry];
        }else if(rank[rx] < rank[ry]){
            par[rx] = ry;
            scale1[ry] += scale1[rx];
        }else{
            // 同じならxを根に
            par[ry] = rx;
            scale1[rx] += scale1[ry];
            rank[rx]++;
        }
        size--;
    }

    // 2つのデータx, yが属する木が同じならtrueを返す関数
    bool same(int x, int y){
        return root(x) == root(y);
    }

    // xの属する木の要素の数を返す関数
    int scale(int x){
        return scale1[root(x)];
    }
};

int main() {
    ll N, M, Q;
    cin >> N >> M >> Q;
    vector<int>A(Q);
    vector<int>B(Q);
    vector<int>C(Q);
    for (int i = 0; i < Q; ++i) {
        cin >> A[i] >> B[i] >> C[i];
    }

    // パスが1個であることと木構造を持つことは同値

    UnionFind tree(N);
    for (int i = 0; i < Q; ++i) {
        if(C[i] == 1) continue;
        tree.unite(A[i], B[i]);
    }

    // グラフが木の時
    if(M == N-1){
        if(tree.size == 1){
            cout << "Yes" << "\n";
        } else{
            cout << "No" << "\n";
        }
        return 0;
    }

    // グラフの辺の数の最大値
    ll temp = tree.size;
    temp = temp * (temp - 1) / 2;
    temp += (N - tree.size);
    if(temp < M) {
        cout << "No" << "\n";
        return 0;
    }

    for (int i = 0; i < Q; ++i) {
        if(C[0] == 0) continue;
        if(tree.same(A[i], B[i])){
            cout << "No" << "\n";
            return 0;
        }
    }
    cout << "Yes" << "\n";
    return 0;
}

