} e[200005];
int fa[200005];
int find(int x) {
    if (fa[x] == x) return x;
    return fa[x] = find(fa[x]);
}

int vis[200005];
bool cmp(Edge a, Edge b) { return a.w < b.w; }
int main() {
    n = read(), scanf("%lld\n", &m), q = read();
    for (int i = 1; i <= n; ++i) fa[i] = i;
    for (int i = 1; i <= q; ++i)
        e[i].u = read() + 1, e[i].v = read() + 1, e[i].w = read();
    sort(e + 1, e + 1 + q, cmp);
    for (int i = 1; i <= q; ++i) {
        if (e[i].w == 0)
            fa[find(e[i].u)] = find(e[i].v);
        else if (find(e[i].u) == find(e[i].v))
            return puts("No"), 0;
        else
            vis[find(e[i].u)] = vis[find(e[i].v)] = 1;
    }

    long long res = 0, res1 = 0;
    for (int i = 1; i <= n; ++i)
        if (find(i) == i) {
            res++, res1 += vis[i];
        }
    if (res1 == 2) {
        if (res > 2)
            res1++;
        else
            return puts("No"), 0;
    }
    if (n - res + res1 > m || m > res * (res - 1) / 2 + (long long)(n - res))
        return puts("No"), 0;
    puts("Yes");
    return 0;
}

