typedef long long ll;
const int max_n=100005;
typedef pair<int,int> P;
struct DSU{
    int par[max_n];
    int sz;
    void init(int n){
        for(int i=1;i<=n;i++)par[i]=i;
        sz=n;
    }
    int findpar(int x){
        return x==par[x]?x:par[x]=findpar(par[x]);
    }
    void unite(int x,int y){
        x=findpar(x),y=findpar(y);
        if(x!=y)par[x]=y,sz--;
    }
    bool same(int x,int y){
        return findpar(x)==findpar(y);
    }
}D;
int n;
ll m;
int q;
vector<P> check;
int main(){
    scanf("%d%lld%d",&n,&m,&q);
    D.init(n);
    while(q--){
        int u,v,w;scanf("%d%d%d",&u,&v,&w);
        if(w==0)D.unite(u,v);
        else check.push_back(P(u,v));
    }
    if(m==n-1){
        if(check.size()==0)printf("Yes\n");
        else printf("No\n");
        return 0;
    }
    for(auto p:check){
        int u=p.first,v=p.second;
        if(D.same(u,v)){
            printf("No\n");
            return 0;
        }
    }
    int k=D.sz;
    ll mx=n-k+1ll*k*(k-1)/2;
    if(m<=mx)printf("Yes\n");
    else printf("No\n");
    return 0;
}

