        if (c == 0) sing.insert(mp(a, b));
        else dob.insert(mp(a, b));
    }

    if (M == N - 1) {
        cout << (dob.empty() ? "Yes" : "No" ) << endl;
        return 0;
    }

    UnionFind uf(N);

    bool can = true;
    for (auto funi : sing) {
        a = funi.F, b = funi.S;
        if (uf.same(a, b)) {
            can = false;
