namespace DSU {
    vector<int> p;
    vector<int> rank;

    int get(int v) {
        if (p[v] != v) {
            p[v] = get(p[v]);
        }
        return p[v];
    }

    void merge(int a, int b) {
        a = get(a);
        b = get(b);
        if (a != b) {
            if (rank[a] < rank[b]) {
                swap(a, b);
            }
            p[b] = a;
            if (rank[a] == rank[b]) {
                rank[a]++;
            }
        }
    }

    void init(int n) {
        p.resize(n);
        iota(p.begin(), p.end(), 0);
        rank.resize(n);
    }
}

