    }
    int left = n;
    vector<int> hv;
    for (int i = 0; i < n; i++) {
        if (sz[i] > 0) {
            hv.push_back(sz[i]);
            left -= sz[i];
        }
    }
    for (auto &t : hv) {
        if (t == 2) {
            t++;
            left--;
        }
