            size[y]+=size[x];
        }
        else{
            par[y]=x;
            size[x]+=size[y];
            if(rank[x]==rank[y]) rank[x]++;
        }
    }

    bool same(int x,int y){
        return find(x)==find(y);
    }

    int get_size(int x){
        return size[find(x)];
    }
};

