struct UF {
	UL N; vector<UL> V;
	UL Z;
	void init(UL n) {
		N = n;
		V.resize(N);
		Z = N;
		rep(i, N) V[i] = i;
	}
	UL root(UL a) {
		if (V[a] == a) return a;
		return root(V[a]);
	}
	void unite(UL a, UL b) {
		a = root(a), b = root(b);
		if (a != b) Z--;
		V[a] = b;
	}
};

struct Problem {
public:

	LL N, M, Q;
	UF F;
	vector<pair<UL, UL>> Q1;
	vector<pair<UL, UL>> Q2;

	void Solve() {
		scanf("%lld%lld%lld", &N, &M, &Q);
		F.init(N);
		rep(i, Q) {
			UL a, b, c; scanf("%u%u%u", &a, &b, &c);
			if (c == 0) Q1.push_back({ a, b });
			else Q2.push_back({ a, b });
		}
		for (auto& p : Q1) F.unite(p.first, p.second);
		for (auto& e : Q2) if (F.root(e.first) == F.root(e.second)) { printf("No"); return; }
		LL X = F.Z;
		if (M > (N - 1) + (X - 2) * (X - 1) / 2) { printf("No"); return; }
