struct UnionFind {
  vector<int> data;

  UnionFind(int sz) {
    data.assign(sz, -1);
  }

  bool unite(int x, int y) {
    x = find(x), y = find(y);
    if (x == y) return false;
    if (data[x] > data[y]) swap(x, y);
    data[x] += data[y];
    data[y] = x;
    return true;
  }

  int find(int k) {
    if (data[k] < 0) return k;
    return (data[k] = find(data[k]));
  }

  int size(int k) {
    return -data[find(k)];
  }
};

void solve() {
  ll n, m, q; cin >> n >> m >> q;
  vector<pii> edge;
  UnionFind uf(n);
  rep(i,q) {
    int a, b, c; cin >> a >> b >> c;
    if (c) edge.emplace_back(a, b);
    else uf.unite(a, b);
  }

  if (m == n-1) {
    CoutYN(edge.empty());
    return;
  }

  for (auto &p : edge) {
    if (uf.find(p.first) == uf.find(p.second)) {
      CoutYN(false);
      return;
    }
  }

  ll sum = 0, cnt = 0;

  rep(i,n) {
    if (uf.find(i) == i) {
      sum += uf.size(i) - 1;
      ++cnt;
    }
  }

  sum += cnt * (cnt - 1) / 2;
  CoutYN(sum >= m);
}


