int main()
{
  ios_base::sync_with_stdio(0);
  cin.tie(0);

  int n, q;
  long long m;
  cin >> n >> m >> q;
  for (int i = 0; i < n; i++)
    ds[i] = i;
  vector<pair<int, int>> queries;
  set<pair<int, int>> cache[2];
  while (q--)
  {
    int x, y, c;
    cin >> x >> y >> c;
    if (x > y)
      swap(x, y);
    if (cache[c].count({x, y}))
      continue;
    cache[c].insert({x, y});
    if (c) queries.push_back({x, y});
    else
    {
      int dx = get(x), dy = get(y);
      if (dx != dy)
      {
        ds[dx] = dy;
        m--;
      }
    }
  }

  int dsCnt = 0;
  for (int i = 0; i < n; i++)
    if (get(i) == i)
      dsCnt++;

  set<pair<int, int>> refinedQueries;
  for (auto u : queries)
  {
    int x = get(u.first), y = get(u.second);
    if (x > y)
      swap(x, y);
    refinedQueries.insert({x, y});
  }

  for (auto u : refinedQueries)
  {
    int dx = get(u.first), dy = get(u.second);
    if (dx == dy || m < 3 || dsCnt < 3)
      noAnswer();
    m -= 3;
  }
  cout << "Yes" << endl;
}

