struct UF{
	int n;
	vector<int>parent,rank;
	UF(int n_=0):n(n_),parent(n_),rank(n_,1)
	{
		for(int i=0;i<n_;i++)parent[i]=i;
	}
	int find(int a)
	{
		return parent[a]!=a?parent[a]=find(parent[a]):a;
	}
	bool same(int a,int b)
	{
		return find(a)==find(b);
	}
	bool unite(int a,int b)
	{
		a=find(a),b=find(b);
		if(a==b)return false;
		if(rank[a]<rank[b])
		{
			parent[a]=b;
			rank[b]+=rank[a];
		}
		else
		{
			parent[b]=a;
			rank[a]+=rank[b];
		}
		return true;
	}
};
int N,Q;
long M;
vector<pair<int,int> >G;
main()
{
	cin>>N>>M>>Q;
	UF uf(N);
	for(int i=0;i<Q;i++)
	{
		int a,b,c;cin>>a>>b>>c;
		if(c==0)uf.unite(a,b);
		else
		{
			G.push_back(make_pair(a,b));
		}
	}
	for(pair<int,int>&p:G)
	{
		if(uf.same(p.first,p.second))
		{
			cout<<"No"<<endl;
			return 0;
		}
		p.first=uf.find(p.first);
		p.second=uf.find(p.second);
	}
	long cnt=0;
	for(int i=0;i<N;i++)
	{
		cnt+=i==uf.find(i);
		if(i==uf.find(i))
		{
			M-=uf.rank[i]-1;
		}
	}
	long lower=0,upper=cnt*(cnt-1)/2;
	if(G.size()>0)
	{
		if(cnt<3)
		{
			cout<<"No"<<endl;
			return 0;
		}
		bool ap[1<<17]={};
		long Gcnt=0;
		for(pair<int,int>p:G)
		{
			if(!ap[p.first])
			{
				ap[p.first]=true;
				Gcnt++;
			}
			if(!ap[p.second])
			{
				ap[p.second]=true;
				Gcnt++;
			}
