//ここから編集する
class UnionFind {
    vector<int> p;//p[i]はiの属する組織
public:
    UnionFind(int n) {
        p = vector<int>(n);
        for (int i = 0; i < n; i++) {
            p[i] = i;
        }
        return;
    }

/* xの属する集合を返す */
    int find(int x) {
        if (p[x] == x) return x;
        return p[x] = find(p[x]);
    }

/* yにxを統合する */
    void unite(int x, int y) {
        p[find(x)] = p[find(y)];
    }

/* xとyが属する集合が同じかを判定する */
    bool same(int x, int y) {
        return find(x) == find(y);
    }

};

class Solve {
public:
    Int N, M, Q;
    vector<pair<Int, Int>> e0;
    vector<pair<Int, Int>> e1;

    vector<vector<Int>> G;

    void solve() {
        cin >> N >> M >> Q;
        for (int i = 0; i < Q; ++i) {
            Int A, B, C;
            cin >> A >> B >> C;
//            A--, B--;
            if (C == 0) {
                e0.emplace_back(A, B);
            } else {
                e1.emplace_back(A, B);
            }
        }

        UnionFind uf(N);
//        vector<Int> gr(N);
//        for (int i = 0; i < N; ++i) gr[i] = i;

        for (auto e : e0) {
            int a = e.first;
            int b = e.second;
            if (uf.same(a, b)) {
                cout << "No" << endl;
                return;
            } else {
//                gr[uf.find(a)] = uf.find(b);
                uf.unite(a, b);
            }
        }

        set<Int> gr;
        for (int i = 0; i < N; ++i) {
            gr.insert(uf.find(i));
        }
        Int T = gr.size(); // tree size
        if (T * (T - 1) / 2 + e0.size() < M) {
            cout << "No" << endl;
            return;
        }

        set<Int> D;
        G.resize(N);
        set<pair<Int, Int>> edges;

        for (auto e : e1) {
            int a = e.first;
            int b = e.second;
            D.insert(uf.find(a));
            D.insert(uf.find(b));
            if (uf.same(a, b)) {
                cout << "No" << endl;
                return;
            }

            pair<Int, Int> edge(uf.find(a), uf.find(b));
            if (edge.first > edge.second) {
                swap(edge.first, edge.second);
            }
            if (edges.count(edge)) {
                cout << "No" << endl;
                return;
            }

            edges.insert(edge);
        }

        vector<Int> appear(N);
        for (auto e : edges) {
            int a = e.first;
            int b = e.second;
            appear[a]++;
            appear[b]++;
        }
        Int rootcnt = 0;
        for (auto e : appear) {
            if (e == 1) rootcnt++;
        }
        Int add = rootcnt / 2 + rootcnt % 2;
        if (e0.size() + e1.size() + add > M) {
            cout << "No" << endl;
            return;
        }

//        if (D.size() > e1.size() + M) {
//            cout << "No" << endl;
//            return;
//        }

        if (e1.size() > 0 && T < 3) {
            cout << "No" << endl;
        } else {
            cout << "Yes" << endl;
        }


    }
};


