class disjoint_set {
public:
  using size_type = size_t;

private:
  mutable std::vector<intmax_t> M_c;

public:
  disjoint_set() = default;
  disjoint_set(disjoint_set const&) = default;
  disjoint_set(disjoint_set&&) = default;

  disjoint_set(size_t n): M_c(n, -1) {}

  disjoint_set& operator =(disjoint_set const&) = default;
  disjoint_set& operator =(disjoint_set&&) = default;

  void reset() { M_c.assign(M_c.size(), -1); }

  size_type representative(size_type v) const {
    if (M_c[v] < 0) return v;
    return (M_c[v] = representative(M_c[v]));
  }

  bool unite(size_t u, size_t v) {
    u = representative(u);
    v = representative(v);
    if (u == v) return false;
    if (-M_c[u] > -M_c[v]) std::swap(u, v);
    M_c[v] += M_c[u];
    M_c[u] = v;
    return true;
  }

  bool equivalent(size_t u, size_t v) const {
    return (representative(u) == representative(v));
  }

  size_type size() const noexcept { return M_c.size(); }
  size_type size(size_type v) const {
    return -M_c[representative(v)];
  }
};

int main() {
  size_t n, m, q;
  scanf("%zu %zu %zu", &n, &m, &q);

  std::set<size_t> appears;

  std::vector<std::pair<size_t, size_t>> zeros, ones;
  for (size_t i = 0; i < q; ++i) {
    size_t a, b, c;
    scanf("%zu %zu %zu", &a, &b, &c);
    ((c == 0)? zeros: ones).emplace_back(a, b);
    appears.insert(a);
    appears.insert(b);
  }

  std::set<size_t> unappears;
  for (size_t i = 0; i < n; ++i)
    if (appears.count(i) == 0) unappears.insert(i);

  disjoint_set ds(n);
  for (auto const& p: zeros) {
    size_t u, v;
    std::tie(u, v) = p;
    ds.unite(u, v);
  }

  std::set<std::pair<size_t, size_t>> er;
  for (auto const& p: ones) {
    size_t u, v;
    std::tie(u, v) = p;
    if (ds.equivalent(u, v)) return puts("No"), 0;
    er.insert(std::minmax(ds.representative(u), ds.representative(v)));
  }

  std::set<size_t> reps;
  for (auto x: appears) reps.insert(ds.representative(x));

  size_t m_lb = n-1;
  size_t m_ub = n*(n-1) / 2;
  if (reps.size() == 1) {
    assert(ones.empty());
    m_lb = n-1;
    m_ub = ds.size(*reps.begin())-1;
    if (!unappears.empty()) {
      ++m_ub;
      m_ub += unappears.size() * (unappears.size()-1) / 2;
    }
  } else if (reps.size() == 2) {
    size_t s0 = ds.size(*reps.begin());
    size_t s1 = ds.size(*++reps.begin());
    if (!ones.empty()) {
      m_lb = s0 + s1 + 1;
      if (m_lb > n) return puts("No"), 0;
    }
    m_ub = s0 + s1 - 1;
    size_t nr = n - (s0+s1);
    m_ub += nr*(nr-1) / 2 + 2*nr;
  } else {
    size_t nr = n;
    for (auto x: reps) nr -= ds.size(x);
    if (!ones.empty()) {
      m_lb = reps.size();
      for (auto x: reps) m_lb += ds.size(x) - 1;
    }
    m_ub = 0;
    for (auto x: reps) m_ub += ds.size(x) - 1;
    nr += reps.size();
    m_ub += nr*(nr-1) / 2;
  }

  if (!(m_lb <= m && m <= m_ub)) return puts("No"), 0;
  puts("Yes");
}

