#include <bits/stdc++.h>
using namespace std;

struct UnionFind {
    vector<int> par;
    vector<int> sz;

    UnionFind(int n=0){
        if(n>0) initialize(n);
    }

    void initialize(int n){
        par.resize(n);
        sz.resize(n);
        for(int i=0; i<n; i++){
            par[i] = i;
            sz[i] = 1;
        }
    }

    int find(int x){
        if(par[x] == x){
            return x;
        }else{
            return par[x] = find(par[x]);
        }
    }

    bool unite(int x, int y){
        x = find(x);
        y = find(y);
        if(x == y) return false;
        if(sz[x] > sz[y]) swap(x, y);
        par[x] = y;
        sz[y] += sz[x];
        return true;
    }

    bool same(int x, int y){
        return find(x) == find(y);
    }

    int size(int x){
        return sz[find(x)];
    }
};

void fin(bool ok){
    cout << (ok ? "Yes" : "No") << endl;
    exit(0);
}

int main(){
    int64_t N, M, Q;
    cin >> N >> M >> Q;
    UnionFind uf(N);
    vector<pair<int, int>> differ;
    for(int i=0; i<Q; i++){
        int a, b, c;
        cin >> a >> b >> c;
        if(c){
            differ.emplace_back(a, b);
        }else{
            uf.unite(a, b);
        }
    }
    for(auto& p : differ) if(M == N-1 || uf.same(p.first, p.second)) fin(false);
    int64_t C = 0;
    for(int i=0; i<N; i++) if(uf.find(i) == i) C++;
    fin(2*M <= 2*N + C*(C-3));
    return 0;
}

