class union_find
{
private:
	std::vector<int>parent;
	std::vector<int>rank;
	std::vector<int>size;
public:
	union_find(int n)
	{
		parent.resize(n);
		rank.resize(n);
		size.resize(n);
		for (int i = 0; i < n; ++i)
		{
