			std::swap(xr, yr);
		}
		if (rank[xr] == rank[yr]) {
			++rank[yr];
		}
		size[yr] += size[xr];
		parent[xr] = yr;
	}
	int find(int x)
	{
		if (parent[x] == x)
		{
			return x;
		}
		else
		{
			return parent[x] = find(parent[x]);
		}
	}
	bool check(int x, int y)
	{
		return find(x) == find(y);
	}
	int getsize(int x) {
		return size[find(x)];
	}
};


