struct unionfind {
       ll max_un;
       vector<ll> parent;
       vector<ll> components;
       unionfind(ll n) {
               max_un = n;
               parent = vector<ll>(n + 1);
               components = vector<ll>(n + 1);
               for (int i = 0; i <= n; i++) {
                       parent[i] = i;
                       components[i] = 1;
               }

       }
       ll find(ll x) {
               if (parent[x] == x) {
                       return x;
               }
               else {
                       parent[x] = find(parent[x]);
                       return parent[x];
               }
       }
       bool same(ll x, ll y) {
               return find(x) == find(y);
       }
       ll comp(ll x) {
               return components[find(x)];
       }
       void unite(ll x, ll y) {
               if (!same(x, y)) {
                       x = parent[x];
                       y = parent[y];
                       if (components[x] <= components[y]) {
                               parent[x] = y;
                               components[y] += components[x];
                       }
                       else {
                               parent[y] = x;
                               components[x] += components[y];
                       }
               }
       }
};

