  for (int i = 0; i < q; ++i) if (!c[i]) {
    uf.unite(a[i], b[i]);
  }

  lint ub = n * (n - 1) / 2;
  set<int>().swap(se);
  for (int v = 0; v < n; ++v) {
    se.insert(uf.find(v));
  }
  for (int e : se) {
    lint sz = uf.size(e);
    ub -= sz * (sz - 1) / 2;
    ub += sz - 1;
  }
  if (m > ub) {
    return cout << "No" << '\n', 0;
  }

  for (int i = 0; i < q; ++i) if (c[i]) {
    if (uf.same(a[i], b[i])) {
