  for (int i = 0; i < q; ++i) if (c[i]) {
    if (uf.same(a[i], b[i])) continue;
    uf.unite(a[i], b[i]);
    if (!m or !r) {
      return cout << "No" << '\n', 0;
    }
    --m;
    uf.unite(a[i], b[i]);
  }

  assert(false);
  cout << "Yes" << '\n';
}

