typedef long long LL;

const int N=100000;

int n,cq,qx[N+9],qy[N+9],qv[N+9];
LL m;

void into(){
  scanf("%d%lld%d",&n,&m,&cq);
  for (int i=1;i<=cq;++i){
	scanf("%d%d%d",&qx[i],&qy[i],&qv[i]);
	++qx[i];++qy[i];
  }
}

int uni[N+9],vis[N+9];

int Query_uni(int k){return k==uni[k]?k:uni[k]=Query_uni(uni[k]);}

int ans;

void Get_ans(){
  if (m<n-1) return;
  for (int i=1;i<=n;++i) uni[i]=i;
  for (int i=1;i<=cq;++i){
	if (qv[i]) continue;
	int fx=Query_uni(qx[i]),fy=Query_uni(qy[i]);
	if (fx==fy) continue;
	uni[fx]=fy;
  }
  int flag=0;
  for (int i=1;i<=cq;++i){
	if (!qv[i]) continue;
	flag=1;
	if (Query_uni(qx[i])==Query_uni(qy[i])) return;
  }
  int cnt=0;
  for (int i=1;i<=n;++i){
	int fx=Query_uni(i);
	if (!vis[fx]) ++cnt,vis[fx]=1;
  }
  if (cnt==1||cnt==2) {ans=m==n-1&&!flag;return;}
  if (m<n) return;
  LL t=n-cnt+((LL)cnt*(cnt-1)>>1);
  ans=m<=t;
}

void work(){
  Get_ans();
}

void outo(){
  puts(ans?"Yes":"No");
}

int main(){
  into();
  work();
  outo();
  return 0;
}

