int kek, lol;
void merge(int a, int b) {
    a = pr[a]; b = pr[b];
    if (a == b)
        return;
    kek--;
    if (g[a].size() < g[b].size())
        swap(a, b);
    for (auto p : g[b]) {
        pr[p] = a;
        g[a].push_back(p);
    }
    g[b].clear();
}

void merge2(int a, int b) {
    a = pr2[a]; b = pr2[b];
    if (a == b)
        return;
    lol--;
    if (g2[a].size() < g2[b].size())
        swap(a, b);
    for (auto p : g2[b]) {
        pr2[p] = a;
        g2[a].push_back(p);
    }
    g2[b].clear();
}

void smain() {

    int n, m, q;
    cin >> n >> m >> q;
    kek = n;
    for (int i = 0; i < n; i++) {
        pr[i] = i;
        g[i].push_back(i);
    }
    vi a(q), b(q);
    vpi d(q);
    for (int i = 0; i < q; i++) {
        cin >> a[i] >> b[i] >> d[i].first;
        d[i].second = i;
    }
    sort(ALL(d));

    for (int i = 0; i < q; i++) {
        if (d[i].first == 0) {
            merge(a[d[i].second], b[d[i].second]);
        } else
