const int maxn = 1e5 + 10;

int root[maxn];

int get_root(int x){
	return root[x] = root[x] == x ? x : get_root(root[x]);
}

int N , Q;
ll M;
int l[maxn] , r[maxn] , cnt = 0;
int v[maxn];

void output(int x){
	cout << (x ? "Yes" : "No") << endl;
	exit(0);
}

int main(){
	cin >> N >> M >> Q;
	for(int i = 0 ; i < N ; ++ i)
		root[i] = i;
	for(int i = 1 ; i <= Q ; ++ i){
		int a , b , c;
		cin >> a >> b >> c;
		if(c == 0){
			int a1 = get_root(a) , b1 = get_root(b);
			if(a1 != b1)
				root[a1] = b1;
		}
		else{
			++ cnt;
			l[cnt] = a , r[cnt] = b;
		}
	}
	int sum = 0;
	for(int i = 0 ; i < N ; ++ i)
		if(root[i] == i)
			sum ++;
	if(sum == 1){
		if(cnt > 0)
			output(0);
		else if(M != N - 1)
			output(0);
		output(1);
	}
	else if(sum == 2){
		if(cnt > 0)
			output(0);
		else if(M != N - 2)
			output(0);
		output(1);
	}
	else{
		for(int i = 1 ; i <= cnt ; ++ i){
			int a1 = get_root(l[i]) , b1 = get_root(r[i]);
			if(a1 == b1)
				output(0);
			v[a1] = v[b1] = 1;
		}
		int s1 = 0;
		for(int i = 0 ; i < N ; ++ i)
			if(v[i] > 0)
				s1 ++;
		ll MINN = N - sum + (s1 == 2 ? 3 : s1) , MAXN = N - sum + 1ll * sum * (sum - 1) / 2;
		if(M >= MINN && M <= MAXN)
			output(1);
		output(0); 
	}
	return 0;
}

