void solve() {
	cin >> N >> M >> Q;
	rep(i, 0, Q) {
		cin >> A[i] >> B[i] >> C[i];
		if(C[i] == 0) {
			G[A[i]].pb(B[i]);
			G[B[i]].pb(A[i]);
		}
	}
	memset(used, -1, sizeof(used));
	ll k = 0;
	rep(i, 0, N) {
		if(used[i] == -1) loop(i, k++);
	}
	bool noloop = true;
	rep(i, 0, Q) {
		if(C[i] == 1) {
			if(used[A[i]] == used[B[i]]) {
