    for(int i=0;i<Q;i++) if(C[i]==1) ok=false;
    if(ok) cout<<"Yes"<<endl;
    else cout<<"No"<<endl;
    return 0;
  }

  DisjointSet us(N);
  for(int i=0;i<Q;i++){
    if(C[i]==0){
      if(!us.same(A[i],B[i])) us.unite(A[i],B[i]);
    }
  }
  for(int i=0;i<Q;i++){
    if(C[i]==1){
      if(us.same(A[i],B[i])){
        cout<<"No"<<endl;
        return 0;
      }
    }
  }

  int size=0;
