using namespace std;

const int MAXN = 100005;
int n, q;
long long m;
vector<pair<int, int> > con[2];
int p[2][MAXN];
bool used[MAXN];
int find(int a, int i) {
	if (p[a][i] == -1 || p[a][i] == i) return i;
	return p[a][i] = find(a, p[a][i]);
}
bool un(int a, int u, int v) {
	u = find(a, u);
	v = find(a, v);
	if (u == v) return false;
	p[a][u] = v;
	return true;
}

bool unTree(int u, int v) {
	used[find(1, u)] = true;
	used[find(1, v)] = true;
	if (un(0, u, v)) {
		return un(1, u, v);
	}
	return true;
}
int comp[MAXN];
int main() {
	memset(p, -1, sizeof(p));
	scanf("%d %lld %d", &n, &m, &q);
	for (int i = 0; i < q; i++) {
		int a, b, c;
		scanf("%d %d %d", &a, &b, &c);
		con[c].push_back({a, b});
	}
	for (int i = 0; i < con[1].size(); i++) {
		un(1, con[1][i].first, con[1][i].second);
	}
	for (int i = 0; i < n; i++) {
		comp[find(1, i)]++;
	}
	for (int i = 0; i < con[0].size(); i++) {
		if (!unTree(con[0][i].first, con[0][i].second)) {
			printf("No\n");
			return 0;
		}
	}
	priority_queue<pair<int, int> > freeNodes;
	for (int i = 0; i < n; i++) {
		if (!used[i] && comp[i] > 0)
			freeNodes.push({-comp[i], i});
	}
	for (int i = 0; i < n; i++) {
		if (comp[i] == 2 && used[i]) {
			if (freeNodes.empty()) {
				printf("No\n");
				return 0;
			}
			int c = freeNodes.top().second;
			freeNodes.pop();
			comp[i]+=comp[c];
			comp[c] = 0;
		}
	}

	int mxUsedComp = 0;
	int mxComp = 0;
	for (int i = 0; i < n; i++) {
		if (comp[i] == 0) continue;
		mxComp = max(mxComp, comp[i]);
		if (used[i]) mxUsedComp = max(mxUsedComp, comp[i]);
	}

	for (int i = 0; i < n; i++) {
		if ((comp[i] == mxUsedComp && used[i]) || (mxUsedComp == 0 && mxComp == comp[i])) {
			while (!freeNodes.empty()) {
				int c = freeNodes.top().second;
				freeNodes.pop();
				if (c == i) continue;
				comp[i] += comp[c];
				comp[c] = 0;
			}
		}
	}
	long long minM = n-1;
	long long maxM = n-1;
	for (int i = 0; i < n; i++) {
		if (comp[i] == 0)
			continue;
		if (comp[i] > 1) minM++;
		maxM += (comp[i] * 1ll * (comp[i] - 1)) / 2;
	}
	if (minM <= m && m <= maxM) {
		printf("Yes\n");
	} else printf("No\n");
}

