    }
  }

  int K = 0;
  for ( int i = 0; i < N; ++ i ) {
    if ( mfset.find(i) == i ) {
      ++ K;
    }
  }

  if ( K == 2 ) {
    K = 1;
  }

  bool ng = false;

  int M_max = N + (K * (K - 3)) / 2;
  if ( M > M_max ) {
    ng = true;
  }
