  while (q--)
  {
    int x, y, c;
    cin >> x >> y >> c;
    if (x > y)
      swap(x, y);
    if (cache[c].count({x, y}))
      continue;
    cache[c].insert({x, y});
    if (c) queries.push_back({x, y});
    else
    {
      int dx = get(x, ds), dy = get(y, ds);
      if (dx != dy)
      {
        ds[dx] = dy;
        m--;
      }
    }
  }

  int dsCnt = 0;
  memset(ds2, -1, sizeof ds2);
  vector<int> b;
