#include <iostream>
#include <vector>

struct DJSet {
  int n;
  std::vector<int> upper;

  DJSet(int n) : upper(n) {
    for (int i=0;i<n;++i) upper[i]=-1;
  }

  int root(int x) {
    return upper[x]<0?x:(upper[x]=root(upper[x]));
  }

  bool equiv(int x, int y) {
    return root(x)==root(y);
  }

  void setUnion(int x, int y) {
    x=root(x);
    y=root(y);
    if (x==y) return;
    if (upper[x]>upper[y]) {
      x^=y;
      y^=x;
      x^=y;
    }
    upper[x]+=upper[y];
    upper[y]=x;
  }
};

int main() {
  int N, M, Q;
  std::cin >> N >> M >> Q;
  DJSet ds(N);
  std::vector<int> A(Q);
  std::vector<int> B(Q);
  std::vector<int> C(Q);
  for (int i=0;i<Q;++i) {
    std::cin >> A[i] >> B[i] >> C[i];
    if (C[i]==0) {
      ds.setUnion(A[i], B[i]);
    }
  }
  bool flag = false;
  for (int i=0;i<Q;++i) {
    if (C[i]==1) {
      flag = true;
      if (ds.equiv(A[i], B[i])) {
	std::cout << "No" << std::endl;
	return 0;
      }
    }
  }
  int num=0;
  for (int i=0;i<N;++i) {
    if (ds.upper[i]<0) ++num;
  }
  if (num==1) {
    std::cout << (M==N-1?"Yes":"No") << std::endl;
    return 0;
  } else if (num==2) {
    if (flag) 
      std::cout << "No" << std::endl;
    else {
      if (M==N-1) {
	std::cout << "Yes" << std::endl;
      } else {
	std::cout << "No" << std::endl;
      }
    }
    return 0;
  } else {
    if (N-(flag?0:1)<=M && M<=N+(num-3)*num/2) {
      std::cout << "Yes" << std::endl;
    } else {
      std::cout << "No" << std::endl;
    }
    return 0;
  }
}

