void unite(ll x,ll y){
    x = find(x);
    y = find(y);
    if(x==y)return;
    if(ran[x]<ran[y]){
        p[x]=y;
    }else{
        p[y]=x;
        if(ran[x]==ran[y])ran[x]++;
    }
}

bool same(ll x,ll y){
