struct UnionFind{
    vector<ll> par;
    vector<ll> siz;

    void init(ll n){
        for(ll i=0;i<n;i++){
            par.push_back(i);
            siz.push_back(1);
        }
    }

    UnionFind(ll n){
        init(n);
    }

    ll root(ll x){
        //根を返す
        if(par[x]==x){
            return x;
        }
        else{
            return (par[x]=root(par[x]));
        }
    }
    bool sameParent(ll x,ll y){
        return(root(x)==root(y));
    }
    void unite(ll x, ll y){
        x=root(x);y=root(y);
        if(x==y)    return;
        //データ構造->小を大にくっつける
        if(siz[x]<siz[y]) swap(x,y);
        siz[x] += siz[y];
        par[y]=x;
    }

    ll size(ll x){
        return siz[root(x)];
    }
};

int main(){
    int n,m,q;
    cin>>n>>m>>q;

    UnionFind uf(n);

    vector<pair<int,pair<int,int>>> v;
    bool flag=true;
    rep(i,q){
        int a,b,c;
        cin>>a>>b>>c;
        if(c==1) flag=false;
        v.push_back(make_pair(c,make_pair(a,b)));
    }
    sort(ALL(v));

     if(m==n-1){
       if(flag){
           cout<<"Yes"<<endl;
       }
       else{
           cout<<"No"<<endl;
       }
       return 0;
   }

    //単純パス1本のもののみで木を作る

    for(int i=0;i<q;i++){
        auto x=v[i].second;
        int c=v[i].first;

        if(c==0){
            //単純パスが1本
            if(uf.sameParent(x.first,x.second)) continue;
            m--;
            uf.unite(x.first,x.second);
        }
        else if(c==1){
            if(uf.sameParent(x.first,x.second)){
                cout<<"No"<<endl;
                return 0;
            }
        }
    }
    //k:連結成分の個数
    int k=0;
    rep(i,n){
        if(i==uf.par[i]) k++;
    }

    /*
    木なら単に連結成分同士をつなげて一つの大きな木にすればいい。
    それ以外ならサイクルを作るなり全点対全点をつなげるなりすれば勝手にパス2個以上できる
    */
   //k<残り変数<k*(k-1)/2であればよい
   if(m<=k*(k-1)/2){
       cout<<"Yes"<<endl;
   }
   else{
       cout<<"No"<<endl;
   }

    return 0;
}

