    for(i=0; i<n; i++) {
        scanf("%d", &a[i]);
    }

    map<int, pair<ll,ll> > z;
    //preparePrime( 1000 );
    for(i=0; i<n; i++) {
        int j;
        int tmp=(int)(sqrt((double)a[i])+0.1);
        for(j=1; j<=tmp; j++) {
            if(a[i]%j==0) {
                z[j].first+=a[i];
                z[j].first%=MOD;
                z[j].second+=(ll)a[i]*a[i];
                z[j].second%=MOD;
                int tmp0=a[i]/j;
                if(tmp0>j) {
                    z[tmp0].first+=a[i];
                    z[tmp0].first%=MOD;
                    z[tmp0].second+=(ll)a[i]*a[i];
                    z[tmp0].second%=MOD;
                }
            }
        }
    }

    ll ans=0;
    auto it=z.begin();
    for(; it!=z.end(); ++it) {
        int val0=it->first;
        ll tmp0=it->second.first;
        ll tmp1=it->second.second;
        ll ans0=(tmp0*tmp0%MOD - tmp1 + MOD)%MOD;
        ans0 = ans0 * minv(2*it->first) %MOD;
        //printf("%d %lld\n", it->first, ans0);
        ans=(ans + ans0)%MOD;

        auto it2=z.begin();
        for(; it2!=it; ++it2) {
            int val1=it2->first;
            if(val0 % val1==0) {
                ans = (ans - ((ans0 * val0/val1)%MOD) +MOD)%MOD;
            }
        }
    }
    printf("%lld\n", ans);

    return 0;
}

