  iota(par.begin(), par.end(), 0);
  auto root = [f=[&](auto g, int x) {
    if (par[x] == x)
      return x;
    return par[x] = g(g, par[x]);
  }] (int x) {
    return f(f, x);
  };
  auto unite = [&](int x, int y) -> bool {
    return par[root(y)] != (par[root(y)] = root(x));
  };
  struct Cond{
    bool single;
    int f, t;
  };
  Cond conds[Q];
