struct UnionFind {
	std::vector<int> data;
	int n;
	UnionFind(int n) : n(n), data(n, -1) {}
	void unite(int a, int b) {
		a = root(a);
		b = root(b);
		if (a != b) {
			if (data[a] > data[b]) std::swap(a, b);
			data[a] += data[b];
			data[b] = a;
		}
