		else cnt2.insert(a[i]), cnt2.insert(b[i]);
	}
	for (int i = 0; i < q; i++) if (c[i] && uni.same(a[i], b[i])) return false;
	int m_real = 0;
	for (int i = 0; i < n; i++) if (uni.root(i) == i) m_real += uni.size(i) - 1;
	int m_none = 0;
	if (cnt2.size()) m_none += cnt2.size();
	if (m_real + m_none > m) return false;
	std::cerr << m_real << " " << m_none << std::endl;
	int sz = 0;
	for (int i = 0; i < n; i++) if (uni.root(i) == i) sz++;
	if (sz == 2 && cnt2.size()) return false;
	int64_t max_hen = m_real + (int64_t) (sz - 1) * sz / 2;
	if (m > max_hen) return false;
	return true;
}

int main() {
	std::cout << (solve() ? "Yes" : "No") << std::endl;
	return 0;
}

