	}
	if (active == 1 && cnt2 == 1) {
		mn += 2;
	} else {
		mn += active;
	}

	mn = min(mn, (ll)n);
	if (m < mn || m > mx) {
		finish_no();
	}

	//cout << mn << " " << m << " " << mx << endl;
	printf("Yes\n");
}   

