typedef int64_t ll;


vector<int> si;
int root(int i){
  if(si[i]==i) return i;
  return si[i]=root(si[i]);
}

bool solve() {
  int n,m,q;
  cin>>n>>m>>q;
  vector<int> a(q),b(q),c(q);
  int doubles=0;
  rep(i,q){
    cin>>a[i]>>b[i]>>c[i];
    doubles+=c[i];
  }

  rep(i,n){
    si.push_back(i);
  }

  int islands=n;
  rep(i,q){
    if(c[i]!=0) continue;
    int ra=root(a[i]);
    int rb=root(b[i]);
    if(ra!=rb) {
      si[ra]=rb;
      islands--;
    }
  }
  rep(i,q){
    if(c[i]!=1) continue;
    int ra=root(a[i]);
    int rb=root(b[i]);
    if(ra==rb) return false;
  }

  if(m==n-1) return false;
  if(m>(n-1)+(islands*(islands-1)/2-(islands-1))) return false;
  return true;
}

int main() {
  cout << (solve()?"Yes":"No") << endl;
}

