using namespace std;

template <class T>
class UnionFind
{
public:
	struct Elem {
		int i;
		int num; // root 以外は無効
		T   val;
	};

	UnionFind(int min, int max)
		: elems_(max - min + 1)
		, min_(min)
		, rank_(max - min + 1)
	{
		for (int i = min; i <= max; i++) {
			Elem& elem = this->elems_[i - min];
			elem.i = i;
			elem.num = 1;
		}
	}

	Elem& find(int i) {
		int idx = i - this->min_;
		if (this->elems_[idx].i == i) return this->elems_[idx];

		Elem& root = this->find(this->elems_[idx].i);
		this->elems_[idx].i = root.i; // 簡略化
		return root;
	}

	int size(int i) {
		Elem& root = this->find(i);
		int idx = root.i - this->min_;
		return this->elems_[idx].num;
	}

	int rank() {
		return rank_;
	}

	void merge(int i, int j) {
		Elem& i_root = this->find(i);
		Elem& j_root = this->find(j);
		if (i_root.i == j_root.i) return;

		int i_idx = i_root.i - this->min_;
		int j_idx = j_root.i - this->min_;

		int i_size = this->elems_[i_idx].num;
		int j_size = this->elems_[j_idx].num;

		if (i_size < j_size) {
			this->elems_[i_idx].i = j_root.i;
			this->elems_[j_idx].num += this->elems_[i_idx].num;
		}
		else {
			this->elems_[j_idx].i = i_root.i;
			this->elems_[i_idx].num += this->elems_[j_idx].num;
		}
		this->rank_--;
	}

private:
	vector<Elem> elems_;
	int          min_;
	int          rank_;
};


int main()
{
	ios_base::sync_with_stdio(false);
	cin.tie(NULL);

	uint32_t n, m, q; cin >> n >> m >> q;

	UnionFind<int> uf1 = UnionFind<int>(0, n - 1);
	vector<pair<int, int>> us;

	FOR_LT(i, 0, q) {
		int a, b, c; cin >> a >> b >> c;
		if (c == 0) uf1.merge(a, b);
		else        us.push_back({ a,b });
	}

	if (m == n - 1) {
		if (us.size() != 0) {
			cout << "No" << endl;
		}
		else {
			cout << "Yes" << endl;
		}
		return 0;
	}

	{
		for (const auto& s : us) {
			/*if (uf1.find(s.first).i == uf1.find(s.second).i) {
				cout << "No" << endl;
				return 0;
			}*/
		}
	}

	int64_t k   =  uf1.rank();
	int64_t mmax = (n - k) + k * (k - 1) / 2;
	if (m <= mmax) {
		cout << "Yes" << endl;
	}
	else {
		cout << "No" << endl;
	}

	return 0;
}

