using namespace std;

#define MAX_N 100000007

long long par[MAX_N];
long long ranka[MAX_N];


void init(long long n)
{
	for(long long i=0;i<n;i++)
	{
		par[i]=i;
		ranka[i]=0;
	}
}

int find(long long x) {
	if(par[x]==x)
	{
		return x;
	}
	else
	{
		return par[x] = find(par[x]);
	}
}

void unite(long long x,long long y)
{
	x=find(x);
	y=find(y);
	if(x==y)return;

	if(ranka[x]<ranka[y])
		par[x]=y;
	else
	{
		par[y]=x;
		if(ranka[x]==ranka[y])ranka[x]++;
	}
}

bool same(long long x,long long y)
{
	return find(x)==find(y);
}


int main()
{
	long long n,m,q;
	cin >> n >> m >> q;

	vector<pair<long long,long long> > c0;
	vector<pair<long long,long long> > c1;

	for(long long i=0;i<q;i++)
	{
