struct UnionFind {
  vector<long> data;
  UnionFind(long size) : data(size, -1) { }
  bool unionSet(long x, long y) {
    x = root(x); y = root(y);
    if (x != y) {
      if (data[y] < data[x]) swap(x, y);
      data[x] += data[y]; data[y] = x;
    }
    return x != y;
  }
  bool findSet(long x, long y) {
    return root(x) == root(y);
  }
  long root(long x) {
    return data[x] < 0 ? x : data[x] = root(data[x]);
  }
  long size(long x) {
    return -data[root(x)];
  }
};

vector<long> A, B;
bool used[100000];
bool r_used[100000];

int main(){
    long N, M, Q;
    cin >> N >> M >> Q;
    UnionFind uf(N);
    for(long i = 0; i < Q; i++){
        long a, b, c;
