        if(c == 0){
            uf.unionSet(a, b);
        }else{
            A.push_back(a);
            B.push_back(b);
        }
    }
    long cnt = 0;
    vector<long> vr;
    for(long i = 0; i < N; i++){
        long root = uf.root(i);
        if(!used[root]){
            cnt++;
            used[root] = true;
            vr.push_back(root);
        }
