  bool f=false;
  REP(Q){
    if(C[i]){
      if(uf.same(A[i],B[i])){
        cout<<NO<<endl;
        return;
      }
      f=true;
    }
  }
  if(f&&(uf.uf_size()==2||M==N-1)){
    cout<<NO<<endl;
    return ;
  }
  ll min_edge=(f?N:N-1);
  ll max_edge=N-uf.uf_size()+(uf.uf_size()*(uf.uf_size()-1))/2;

  if(min_edge<=M&&M<=max_edge){
    cout<<YES<<endl;
  }else{
    cout<<NO<<endl;
  }
}

