  i64 cnt;
  UnionFind(i64 size)
  {
    data.resize(size, -1);
    cnt = size;
  }
  bool unite(i64 x, i64 y)
  {
    x = root(x);
    y = root(y);
    if (x != y)
    {
      if (data[y] < data[x])
        swap(x, y);
      data[x] += data[y];
      data[y] = x;
      cnt--;
    }
    return x != y;
  }
  bool same(i64 x, i64 y)
  {
    return root(x) == root(y);
  }
  i64 root(i64 x)
  {
    return (data[x] < 0 ? x : data[x] = root(data[x]));
  }
  i64 size(i64 x)
  {
    return -data[root(x)];
  }
};

