namespace adaptor = boost::adaptors;
using index_t = std::size_t;		

class union_find
{
	std::vector<boost::optional<index_t>> parent;
	std::vector<index_t> rank;
	std::set<index_t> tops;
	std::size_t sz;
public:
	union_find(std::size_t N) :parent(N), rank(N), tops(), sz(N)
	{
		for (auto i : boost::irange<index_t>(0, N))
		{
			tops.emplace(i);
		}
	}
	index_t find(index_t a)
	{
		if (!parent[a])
		{
			return a;
		}
		else
		{
			return *(parent[a] = find(*parent[a]));
		}
	}
	void merge(index_t a, index_t b)
	{
		auto x = find(a);
		auto y = find(b);
		if (x != y)
		{
			--sz;
			if (rank[x] < rank[y])
			{
				tops.erase(x);
				parent[x] = y;
			}
			else if (rank[y] < rank[x])
			{
				tops.erase(y);
				parent[y] = x;
			}
			else
			{
				tops.erase(y);
				parent[y] = x;
				++rank[x];
			}
		}
	}
	std::size_t size()const
	{
		return sz;
	}
	auto begin()const
	{
		return tops.begin();
	}
	auto end()const
	{
		return tops.end();
	}
};

bool run(std::size_t N, std::size_t M, std::vector<std::tuple<index_t, index_t, bool>>const& data)
{
	union_find disjoint(N);
	bool flag = false;
	for (auto&& t : data)
	{
		index_t a, b;
		bool c;
		std::tie(a, b, c) = t;
		if (c)
		{
			disjoint.merge(a, b);
		}
		else
		{
			flag = true;
		}
	}
	if (flag && disjoint.size() < 3)
	{
		return false;
	}
	auto min = N - 1 + flag;
	auto g = disjoint.size();
	auto max = N - 1 + g * (g - 1) / 2;
	return min <= M && M <= max;
}

void Main()
{
	std::size_t N, M, Q;
	std::cin >> N >> M >> Q;
	std::vector<std::tuple<index_t, index_t, bool>> data;
	for (auto i : boost::irange<std::size_t>(0, Q))
	{
		index_t a, b, c;
		std::cin >> a >> b >> c;
		data.emplace_back(a, b, c == 0);
	}
	if (run(N, M, data))
	{
		std::cout << "Yes" << std::endl;
	}
	else
	{
		std::cout << "No" << std::endl;
	}
}

