    int sz;
    vector<int> par, size_,psz;
    vector<bool> flag;
    UnionFind(){}
    UnionFind(int node_size) : sz(node_size), par(sz), size_(sz, 1),psz(sz,1),flag(sz,0){
        iota(par.begin(), par.end(), 0);
    }
    int find(int x){
        if(par[x] == x) return x;
        else return par[x] = find(par[x]);
    }
    void unite(int x,int y){
        x = find(x), y = find(y);
        if(x == y) return;
        if(size_[x] < size_[y]) swap(x,y);
        par[y] = x;
        size_[x] += size_[y];
    }
    void unite2(int x,int y){
        x = find(x), y = find(y);
        if(x == y) return;
        if(size_[x] < size_[y]) swap(x,y);
        par[y] = x;
        size_[x] += size_[y];
        psz[x] +=psz[y];
    }
    void unite3(int x,int y){
        x = find(x), y = find(y);
        par[y] = x;
        size_[x] += size_[y];
        psz[x] +=psz[y];    
    }
    int size(int x){
        x = find(x);
        return size_[x];
    }
    int psize(int x){
        x = find(x);
        return psz[x];
    }
    bool same(int x,int y){
        return find(x) == find(y);
    }
};


