class UF {
  vector<int> v;
public:
  UF(int n) : v(n) {
    for (int i = 0; i < n; ++i) {
      v[i] = i;
    }
  }

  int root(int i) {
    if (v[i] == i) return i;
    return v[i] = root(v[i]);
  }

  bool same(int i, int j) {
    return root(i) == root(j);
  }

  void unite(int i, int j) {
    int ri = root(i);
    int rj = root(j);
    if (ri == rj) return;
    v[ri] = rj;
  }
};

int n, q;
long m;
int a[100000], b[100000], c[100000];

bool sub() {
  bool has_mult = false;
  for (int k = 0; k < q; ++k) {
    if (c[k] == 1) {
      has_mult = true;
    }
  }

  UF uniq(n);
  UF mult(n);
  for (int k = 0; k < q; ++k) {
    if (c[k] == 0) {
      uniq.unite(a[k], b[k]);
    } else {
      mult.unite(a[k], b[k]);
    }
  }

  for (int k = 0; k < q; ++k) {
    if (c[k] == 0) {
      if (mult.same(a[k], b[k])) return false;
    } else {
      if (uniq.same(a[k], b[k])) return false;
    }
  }


  set<int> rs;
  for (int i = 0; i < n; ++i) {
    rs.insert(uniq.root(i));
  }

  if (has_mult && rs.size() < 3) return false;

  set<int> qs;
  for (int k = 0; k < q; ++k) {
    if (c[k] == 1) {
      qs.insert(uniq.root(a[k]));
      qs.insert(uniq.root(b[k]));
    }
  }

  long mn = has_mult ? n : n - 1;
  long mx = n - rs.size() + (long)rs.size() * (rs.size() - 1) / 2;
  return m >= mn && m <= mx;
}

