		} else {
			if(m == n-1)valid = 0;
			int pa = find_par(edge[i].second.first,par);
			int pb = find_par(edge[i].second.second,par);
			if(pa == pb){
				valid = 0;
				break;
			}

		}
	}

	if(!valid){
		printf("No\n");
		return 0;
	}

	ll cnM = gabung * (gabung-3) / 2;
	if(m <= n+cnM) printf("Yes\n");
	else printf("No\n");
	return 0;
}

