		n = _n;
		u = vector<Int>(n, -1);
	}
	Int r(Int x){
	    if(u[x] < 0)return x;
	    return u[x] = r(u[x]);
	}
	void unite(Int x, Int y){
	    x = r(x);
	    y = r(y);
	    if(x != y){
            u[y] += u[x];
            u[x] = y;
        }
	}
    Int size(Int x){
        x = r(x);
        return -u[x];
    }
};

