class UnionFind {
	vector<int> par;
	vector<int> rank;
	vector<int> _size;
public:
	UnionFind(int max_n) :par(max_n), rank(max_n), _size(max_n) {}
	void init(int n) {
		for (int i = 0; i < n; i++) {
			par[i] = i;
			rank[i] = 0;
			_size[i] = 1;
		}
	}
	int find(int x) {
		if (par[x] == x)return x;
		return par[x] = find(par[x]);
	}
	void unite(int x, int y) {
		x = find(x);
		y = find(y);
		if (x == y)return;

		if (rank[x] < rank[y]) {
			par[x] = y;
			_size[y] += _size[x];
		}
		else {
			par[y] = x;
			_size[x] += _size[y];
			if (rank[x] == rank[y])rank[x]++;
		}
	}
	bool same(int x, int y) {
		return find(x) == find(y);
	}
	int size(int x) {
		return _size[find(x)];
	}
};




void solve() {
	int n, m, q;
	cin >> n >> m >> q;

	vector<tuple<int, int>> edge;
	UnionFind uf0(n);
	uf0.init(n);

	int zero = 0;
	rep(i, q) {
		int a, b, c;
