		if (c == 0) {
			if (uf0.same(a, b)) {
				cout << "No" << endl;
				return;
			}
			uf0.unite(a, b);
			zero++;
		}
		else {
			edge.emplace_back(a, b);
		}
	}
	bool amari = false;
	rep(i, n)if (uf0.size(i) == 1)amari = true;


	UnionFind uf1(n);
	uf1.init(n);
	for (auto t : edge) {
		int a, b;
		tie(a, b) = t;
		if (uf0.same(a,b)) {
			cout << "No" << endl;
			return;
		}
		uf1.unite(uf0.find(a), uf0.find(b));
	}

	int cnt = 0;
	set<int> s;
	rep(i,n) {
