int par[N],n,m,q;
void init() {
    for(int i=0;i<n;i++) par[i]=i;
}
int fd(int x) {
    return par[x]==x?x:par[x]=fd(par[x]);
}
void unite(int x,int y) {
    x=fd(x);y=fd(y);
    par[x]=y;
}
int main() {
    scanf("%d%d%d",&n,&m,&q);
    init();
    std::vector<P> g;
