  for (auto i = 0; i < Q; i++)
  {
    cin >> A[i] >> B[i] >> C[i];
  }
  if (M == N - 1)
  {
    for (auto i = 0; i < Q; i++)
    {
      if (C[i] == 1)
      {
        No();
      }
    }
    Yes();
  }
  for (auto i = 0; i < Q; i++)
  {
    if (A[i] > B[i])
    {
      swap(A[i], B[i]);
    }
    edge e{A[i], B[i]};
    if (S[1 - C[i]].find(e) != S[1 - C[i]].end())
    {
      No();
    }
    S[C[i]].insert(e);
  }
  UnionFind uf(N);
  for (auto const &e : S[0])
  {
    uf.merge(get<0>(e), get<1>(e));
  }
  for (auto const &e : S[1])
