    for(int i=0;i<100100;i++){
      par[i] = i;
    }
  }
  int find(int x){
    if(par[x]==x)return x;
    else return par[x] = find(par[x]);
  }
  void unite(int x,int y){
    x = find(x);
    y = find(y);
    if(x==y)return;
    par[x] = y;
    return;
  }
  bool same(int x,int y){
    return find(x)==find(y);
  }
