class UnionFindTree{
private:
	vll par;
	vll rank;
public:
	UnionFindTree(ll num): par(num), rank(num) { REP(i, num) par[i] = i; }
	bool same(ll x, ll y) { return root(x) == root(y); }
	ll root(ll x) { return (par[x] == x) ? x : par[x]=root(par[x]); }
	void unite(ll x, ll y){
		x = root(x);
		y = root(y);
		if (x == y) return;
		if (rank[x] < rank[y]) par[x] = y;
		else                   par[y] = x;
		if (rank[x] == rank[y]) rank[x]++;
	}
};


void solve()
{
	ll N, M, Q;
	cin >> N >> M >> Q;
	auto ABC = cinv3(Q);
	vector<pair<ll, ll>> AB0;
	vector<pair<ll, ll>> AB1;
	EACH(e, ABC){
		ll A = get<0>(e);
		ll B = get<1>(e);
		ll C = get<2>(e);
		if (C == 0) AB0.emplace_back(A, B);
		else        AB1.emplace_back(A, B);
	}

	UnionFindTree uft(N);
	EACH(e, AB0){
		ll A = e.first;
		ll B = e.second;
		uft.unite(A, B);
	}

	set<ll> buf;
	REP(i, N){
		buf.insert(uft.root(i));
	}
	ll g = buf.size();

	if (g <= 2){
		if (AB1.empty()){
			if (M == N-1) cout << "Yes" << '\n';
			else          cout << "No" << '\n';
