		ll B = e.second;
		if (uft.same(A, B)){
			cout << "No" << '\n';
			return;
		}
	}

	if (N <= M && M <= N-g + g*(g-1)/2) cout << "Yes" << '\n';
	else                                cout << "No" << '\n';
}

