	Edge(int u = 0, int v = 0, int t = 0) : u(u), v(v), t(t) {}
} E[N];

int root[N];

int find_root(int u) {
	if (u == root[u]) return root[u];
	return root[u] = find_root(root[u]);
}

int main() {
	ios::sync_with_stdio(0);
	cin.tie(0), cout.tie(0);
	int n, q;
	long long m; cin >> n >> m >> q;
	for (int i = 0; i < q; i++) cin >> E[i].u >> E[i].v >> E[i].t, E[i].u++, E[i].v++;
	for (int i = 1; i <= n; i++) root[i] = i;
	for (int i = 0; i < q; i++) if (E[i].t == 0) {
		int a = find_root(E[i].u), b = find_root(E[i].v);
		if (a == b) continue;
