    // M = N - 1 の時は木構造のグラフとなる．
    if ( multi_pair_list.size() > 0 ) {
      // その場合複数経路はありえない．
      cout << "No" << endl;
      return 0;
    }
    else {
      cout << "Yes" << endl;
      return 0;
    }
  }

  vector<vector<int>> adj_list(N);
