int par[N+5];
int global_par[N+5];
vector<ipii> edge;

int n,q;
ll m;
int cnt[N+5];
int maksi[N+5];
bool pake[N+5];

int main(){
	memset(pake,0,sizeof(pake));
	scanf("%d%lld%d",&n,&m,&q);
	int unused = n;
	for(int i=1;i<=q;i++){
		int a,b,c;
		scanf("%d%d%d",&a,&b,&c);
		a++;
		b++;
		if(!pake[a]){
			unused--;
			pake[a]=1;
		}
		if(!pake[b]){
			unused--;
			pake[b]=1;
		}
		edge.push_back(make_pair(c,make_pair(a,b)));
	}
	unique(edge.begin(),edge.end());
	sort(edge.begin(),edge.end());
	for(int i=1;i<=n;i++) par[i] = i,cnt[i]=1, global_par[i] = i;
	int valid = 1;
	int cnt2 = 0;
	int gabung = n-1;
	ll cnm = 0;
	ll cnM = 0;
	for(int i=q-1;i>=0;i--){
		if(edge[i].first == 1){
			int pa = find_par(edge[i].second.first,par);
			int pb = find_par(edge[i].second.second,par);
			if(pa != pb){
				par[pa] = pb;
				if(cnt[pa] == 2) cnt2--;
				if(cnt[pb] == 2) cnt2--;
				cnt[pb]+=cnt[pa];
				if(cnt[pb] == 2) cnt2++;
				maksi[pb] = cnt[pb];
				global_par[pa] = pb;
				gabung--;
			}
		} else {
			int pa = find_par(edge[i].second.first,par);
			int pb = find_par(edge[i].second.second,par);
			if(pa == pb){
				valid = 0;
				break;
			}
			pa = find_par(edge[i].second.first,global_par);
			pb = find_par(edge[i].second.second,global_par);
			if(pa == pb){
				valid = 0;
				break;
			} else {
				global_par[pa] = pb;
				maksi[pb] = max(maksi[pb],maksi[pa]);
				gabung--;
				cnm++;
				cnM++;
			}
		}
	}

	if(!valid || (cnt2>0 && gabung == 0)){
		printf("No\n");
		return 0;
	}
//	cout << " >> " << cnm << " " << cnM << endl;
//	cout << "HOORAY\n";
	for(int i=1;i<=n;i++){
		if(find_par(i,par) == i && pake[i]){

			if(cnt[i] == 2){
				if(unused>0){
					unused--;
					cnt[i]++;
					int lol = find_par(i,global_par);
					maksi[lol] = max(maksi[lol],cnt[i]);
				}
			}
//			cout << i << " " << cnt[i] << endl;
			if(cnt[i] > 1){
				cnm+=cnt[i];
				cnM+=((ll)(cnt[i]) * (ll)(cnt[i]-1)) / 2ll;
			}
//			cout << cnm << " " << cnM << " << \n";
		}
	}
	ll lala = 0ll;
	for(int i=1;i<=n;i++){
		if(find_par(i,global_par) == i && pake[i]){
			if(maksi[i] == 1) continue;
			ll tmp = ((ll)(maksi[i]) * (ll)(maksi[i]-1)) / 2ll;
			cnM-=tmp;
			lala+=maksi[i];
		}
	}
//	cout << lala << endl;
	lala+=unused;
	cnM += (lala)*(lala-1) / 2ll;
	cnm+=unused;

//	cout << cnm << " AND " << cnM << endl;
	if(m >= cnm && m <= cnM) printf("Yes\n");
	else printf("No\n");
	return 0;
}

