class U {
public:
  int n;
  vector<int> p, s;

  U(int _) {
    n = _;
    p.resize(n);
    s.resize(n);
    for (int i = 0; i < n; i++) {
      p[i] = i;
      s[i] = 1;
    }
  }

  bool connect(int a, int b) {
    int ap, bp;
    for (ap = p[a]; ap != p[ap]; ap = p[ap]);
    for (bp = p[b]; bp != p[bp]; bp = p[bp]);
    if (ap == bp)
      return true;
    int mi = min(ap, bp), ma = max(ap, bp);
    p[ma] = mi;
    s[mi] += s[ma];
    s[ma] = 0;
    for (int pp = a; pp != mi;) {
      int next = p[pp];
      p[pp] = mi;
      pp = next;
    }
    for (int pp = b; pp != mi;) {
      int next = p[pp];
      p[pp] = mi;
      pp = next;
    }
    return false;
  }

  int q(int a) {
    int ap;
    for (ap = a; ap != p[ap]; ap = p[ap]);
    return s[ap];
  }

  int parent(int a) {
    int ap;
    for (ap = a; ap != p[ap]; ap = p[ap]);
    return p[ap];
  }

  bool query(int a, int b) { return parent(a) == parent(b); }
};

struct Q {
  int a, b, c;
};

bool operator<(const Q &l, const Q &r) {
  return l.c < r.c;
}

int main() {
  cin.tie(nullptr);
  ios::sync_with_stdio(false);
  ll n, m, q;
  cin >> n >> m >> q;
  U u(n);
  vector<Q> qs(q);
  for (int i = 0; i < q; i++) cin >> qs[i].a >> qs[i].b >> qs[i].c;
  sort(qs.begin(), qs.end());
  int qc = q;
  for (int i = 0; i < q; i++) {
    if (qs[i].c) {
      qc = i;
      break;
    }
    u.connect(qs[i].a, qs[i].b);
  }
  ll nn = 0;
  for (int i = 0; i < n; i++) {
    if (u.parent(i) == i) {
      nn++;
    }
  }
  for (int i = qc; i < q; i++) {
    int ap = u.parent(qs[i].a);
    int bp = u.parent(qs[i].b);
    if (ap == bp) {
      cout << "No" << endl;
      return 0;
    }
  }
  if (qc < q && (nn == 2 || m == n - 1)) {
    cout << "No" << endl;
    return 0;
  }
  ll emax = n - nn + nn * (nn - 1) / 2;
  if (m <= emax) {
    cout << "Yes" << endl;
  } else {
    cout << "No" << endl;
  }
  return 0;
}

