using namespace std;

using ll = long long;
const ll MOD = 1e9 + 7;

const int MAX_N = 100010;
int par[MAX_N];
int rnk[MAX_N];

void init(int n) {
    rep(i,n) {
        par[i] = i;
        rnk[i] = 0;
    }
}

int find(int x) {
    if (par[x] == x) {
        return x;
    } else {
        return par[x] = find(par[x]);
    }
}

void unite(int x, int y) {
    x = find(x);
    y = find(y);
    if (x == y) return;
    if (rnk[x] < rnk[y]) {
        par[x] = y;
    } else {
        par[y] = x;
        if (rnk[x] == rnk[y]) rnk[x]++;
    }
}

bool same(int x, int y) {
    return find(x) == find(y);
}

int main() {
    int N, M, Q, c0 = 0, c1 = 0;
    cin >> N >> M >> Q;
    init(N);
    vector<int> A(Q), B(Q), C(Q);
    rep(i, Q) {
        cin >> A[i] >> B[i] >> C[i];
        if (C[i] == 0) {
            c0++;
            if (same(A[i], B[i])) {
                cout << "No" << endl;
                return 0;
            }
            unite(A[i], B[i]);
        } else {
            c1++;
        }
    }
    rep(i, Q) {
        if (C[i] == 0) continue;
        if (same(A[i], B[i])) {
            cout << "No" << endl;
            return 0;
        }
        if (N - c0 == 2) {
            cout << "No" << endl;
            return 0;
        }
    }
    cout << "Yes" << endl;
}

