    }
    //k:連結成分の個数
    int k=0;
    rep(i,n){
        if(i==uf.par[i]) k++;
    }

    /*
    木なら単に連結成分同士をつなげて一つの大きな木にすればいい。
    それ以外ならサイクルを作るなり全点対全点をつなげるなりすれば勝手にパス2個以上できる
    */
   if(m==n-1){
