int N, Q;
ll M;
int A[MAX_N], B[MAX_N], C[MAX_N];
vi G[MAX_N];
int used[MAX_N];

void loop(int v, int k) {
	used[v] = k;
	rep(i, 0, sz(G[v])) {
		int n = G[v][i];
		if(used[n] == -1) loop(n, k);
	}
}

void solve() {
	cin >> N >> M >> Q;
	rep(i, 0, Q) {
		cin >> A[i] >> B[i] >> C[i];
		if(C[i] == 0) {
			G[A[i]].pb(B[i]);
			G[B[i]].pb(A[i]);
		}
	}
	memset(used, -1, sizeof(used));
	ll k = 0;
	rep(i, 0, N) {
		if(used[i] == -1) loop(i, k++);
	}
	bool noloop = true;
	rep(i, 0, N) {
		if(C[i] == 1) {
			if(used[A[i]] == used[B[i]]) {
				cout << "No\n";
				return;
			}
			noloop = false;
		}
	}
	if(k <= 2) {
		if(M == N - 1 && noloop) cout << "Yes\n";
		else cout << "No\n";
	}
	else if(N - noloop <= M && M <= N + k * (k - 3) / 2) {
		cout << "Yes\n";
	}
	else cout << "No\n";
}

