int GetUFS(int x)
{
    int i, t;

    for(i = x; f[i] > -1; i = f[i])
        ;
    while(x != i)
    {
        t = f[x];
        f[x] = i;
        x = t;
    }

    return i;
}

void MergeUFS(int u, int v)
{
    u = GetUFS(u);
    v = GetUFS(v);
    if(u != v)
    {
        if(f[u] > f[v])
            swap(u, v);
        f[u] += f[v];
        f[v] = u;
    }

    return;
}

int main(void)
{
    int n, q, u, v, w;
    long long m;
    int i, c, d;

    scanf("%d %lld %d", &n, &m, &q);
