    {
        scanf("%d %d %d", &u, &v, &w);
        if(!w)
            MergeUFS(u, v);
        else
            k.push_back(make_pair(u, v));
    }

    for(i = c = 0; i < n; i ++)
        if(f[i] < 0)
        {
            c ++;
            m -= -f[i] - 1;
        }
    if(m < 0)
    {
        printf("No\n");

        return 0;
    }

    for(i = d = 0; i < (signed)k.size(); i ++)
        if(GetUFS(k.at(i).first) == GetUFS(k.at(i).second))
        {
