void make_abs(V<t2> &ab_trees, V<t2> &ab_loops, const V<t3> &abclist)
{
    for (auto abc : abclist) {
        ll a = get<0>(abc);
        ll b = get<1>(abc);
        ll c = get<2>(abc);

        ll x = min(a, b);
        ll y = max(a, b);

        if (c == 0LL) ab_trees.pb(t2(x, y));
        if (c == 1LL) ab_loops.pb(t2(x, y));
    }
}

int _main()
{
    ll n; llin(n);
    ll m; llin(m);
    ll q; llin(q);
    V<t3> abclist; llinl3(abclist, q);

    V<t2> ab_trees;
    V<t2> ab_loops;
    make_abs(ab_trees, ab_loops, abclist);

    UnionFind uf(n);
    set<ll> intrees;
    for (auto ab : ab_trees) {
        ll a = get<0>(ab);
        ll b = get<1>(ab);
        uf.unite(a, b);
        intrees.insert(a);
        intrees.insert(b);
    }

    for (auto ab : ab_loops) {
        ll a = get<0>(ab);
        ll b = get<1>(ab);
        if (uf.root(a) == uf.root(b)) {
            cout << "No" << endl;
            return 0;
        }
    }

    set<ll> roots;
    rep (v, n) roots.insert(uf.root(v));

    ll intreecount = intrees.size() - roots.size();
    ll ingraphcount = n - intreecount;
    ll min_links = (ab_loops.empty() ? (n-1LL) : (n) );
    ll max_links = ingraphcount * (ingraphcount - 1LL) / 2LL;
    max_links += intreecount;

    if (m < min_links) {
        cout << "No" << endl;
        return 0;
    }
    if (m > max_links) {
        cout << "No" << endl;
        return 0;
    }

    cout << "Yes" << endl;
    return 0;
}

