bool solve() {
  int n,m,q;
  cin>>n>>m>>q;
  vector<int> a(q),b(q),c(q);
  rep(i,q){
    cin>>a[i]>>b[i]>>c[i];
  }

  rep(i,n){
    si.push_back(i);
  }

  int islands=n;
  rep(i,q){
    if(c[i]!=0) continue;
    int ra=root(a[i]);
    int rb=root(b[i]);
    if(ra!=rb) {
      si[ra]=rb;
      islands--;
    }
  }

  int doubles=0;
  rep(i,q){
    if(c[i]!=1) continue;
    doubles++;
    int ra=root(a[i]);
    int rb=root(b[i]);
    if(ra==rb) return false;
  }

  if(doubles>0&&m==n-1) return false; // 輪を作るのにエッジが足りない
  if(doubles>0&&islands<3) return false; // 輪を作るのにノードが足りない
  if(m>(n-1)+(islands*(islands-1)/2-(islands-1))) return false;
  return true;
}

