#define int long long
class UnionFind {
private:
public:
    int sz;
    vector<int> par, size_,psz;
    vector<bool> flag;
    UnionFind(){}
    UnionFind(int node_size) : sz(node_size), par(sz), size_(sz, 1),psz(sz,1),flag(sz,0){
        iota(par.begin(), par.end(), 0);
    }
    int find(int x){
        if(par[x] == x) return x;
        else return par[x] = find(par[x]);
    }
    void unite(int x,int y){
        x = find(x), y = find(y);
        if(x == y) return;
        if(size_[x] < size_[y]) swap(x,y);
        par[y] = x;
        size_[x] += size_[y];
    }
    void unite2(int x,int y){
        x = find(x), y = find(y);
        if(x == y) return;
        if(size_[x] < size_[y]) swap(x,y);
        par[y] = x;
        size_[x] += size_[y];
        psz[x] +=psz[y];
    }
    void unite3(int x,int y){
        x = find(x), y = find(y);
        par[y] = x;
        size_[x] += size_[y];
        psz[x] +=psz[y];    
    }
    int size(int x){
        x = find(x);
        return size_[x];
    }
    int psize(int x){
        x = find(x);
        return psz[x];
    }
    bool same(int x,int y){
        return find(x) == find(y);
    }
};


signed main(){
    long long n,m,q;
    cin >> n >> m >> q;
    ll K = 0;
    UnionFind uf(n);
    vector<pair<int,int> > p;
    rep(i,q){
        int a,b,c;
        cin >> a >> b >> c;
        if(c==1){
            p.push_back(MP(a,b));
        }else{
            if(uf.same(a,b)){
            }else{
                uf.unite(a,b);
                K++;
            }
        }
    }
    bool flag[100001]={};
    int c = 0;
    rep(i,n){
        if(!flag[uf.find(i)]){
            c++;
            flag[uf.find(i)]=1;
        }
    }
    if(c<=2&&p.size()!=0){
        //assert(0);
        cout << "No" << endl;
        return 0;
    }
    vector<ll> pp(n);
    UnionFind uf2(n);
    vector<int> pppppp(n);
    rep(i,n){
        pppppp[i] = uf.find(i);
    }
    rep(i,p.size()){
        int a = p[i].first;
        int b = p[i].second;
        if(pppppp[a]==pppppp[b]){
            assert(0);
            cout << "No" << endl;
            return 0;
        }else{
            // if(c<=2){
            //     cout <<"No" << endl;
            //     return 0;
            // }
            uf.unite(a,b);
            uf2.unite2(a,b);
            uf2.flag[uf2.find(a)] = true;
            c--;
        }
    }
    vector<ll> sp(n);
    rep(i,n){
        if(uf2.flag[uf2.find(i)])sp[uf2.find(i)] = max(uf2.psize(i),sp[uf2.find(i)]);
        if(uf.size(i)==1){ 
            sp[i] = 1;
        }
    }
    priority_queue<pair<ll,ll>,vector<pair<ll,ll>>,greater<pair<ll,ll>> >qqq;
    multiset<int> st;
    rep(i,n){
        //cerr << i << " " << sp[i] << endl;

        if(sp[i]!=0){
            if(sp[i]!=2)qqq.push(MP(sp[i],uf.find(i)));
            else st.insert(uf.find(i));
        }
    }
    vector<pair<ll,ll> >s;
    while(!qqq.empty()){
        auto x = qqq.top();
        qqq.pop();
        if(st.size()==0){
            s.push_back(MP(x.first,x.second));
            continue;    
        }
        int p = *st.begin();
        if(p!=uf.find(x.second)){
            uf.unite3(p,uf.find(x.second));
            qqq.push(MP(x.first+2,p));
            st.erase(st.find(p));
        }else{
            auto q = st.upper_bound(uf.find(x.second));
            if(q==st.end()){
                s.push_back(MP(x.first,x.second));
            }else{
                uf.unite3(*q,uf.find(x.second));
                qqq.push(MP(x.first+2,*q));
                st.erase(q);
            }
        }
    }
    if(st.size()!=0){
        //assert(0);
        cout << "No" << endl;
        return 0;
    }
    ll sss = 0;
    ll ppp = 0;
    vector<ll> sd(n);
    rep(i,s.size()){
        sss += s[i].first;
        sd[uf.find(s[i].second)] = max(s[i].first,sd[uf.find(s[i].second)]);
    }
    rep(i,n){
        ppp += sd[i];
    }
    //cerr << sss << " " << K << " " << m << endl;
    //assert(0);

    if(K+sss-ppp+ppp*(ppp-1)/2 >=m && K+sss <=m){

        cout << "Yes" << endl;
    }else{
        cout << "No" << endl;
    }
    return 0;
}

