    void unite3(int x,int y){
        x = find(x), y = find(y);
        par[y] = x;
        size_[x] += size_[y];
        psz[x] +=psz[y];    
    }
    int size(int x){
        x = find(x);
        return size_[x];
    }
    int psize(int x){
        x = find(x);
        return psz[x];
    }
    bool same(int x,int y){
        return find(x) == find(y);
    }
};


signed main(){
    long long n,m,q;
    cin >> n >> m >> q;
    ll K = 0;
    UnionFind uf(n);
    vector<pair<int,int> > p;
    rep(i,q){
        int a,b,c;
        cin >> a >> b >> c;
        if(c==1){
            p.push_back(MP(a,b));
        }else{
            if(uf.same(a,b)){
                assert(0);
                cout << "No" << endl;
                return 0;
            }else{
                uf.unite(a,b);
                K++;
            }
        }
    }
    bool flag[100001]={};
    int c = 0;
    rep(i,n){
        if(!flag[uf.find(i)]){
            c++;
            flag[uf.find(i)]=1;
        }
    }
    if(c<=2&&p.size()!=0){
        assert(0);
        cout << "No" << endl;
        return 0;
    }
    vector<ll> pp(n);
    UnionFind uf2(n);
    rep(i,p.size()){
