struct UnionFindTree {
    int n;
    std::vector<int> par, size;
    UnionFindTree(int n) : n(n), par(n), size(n) {
        for (int i = 0; i < n; i++) {
            par[i] = i;
            size[i] = 1;
        }
    }
    int getRoot(int i) {
        if (par[i] == i) { return i; }
        else { return par[i] = getRoot(par[i]); }
    }
    void unite(int i, int j) {
        if ((i = getRoot(i)) == (j = getRoot(j))) { return; }
        if (size[i] < size[j]) { std::swap(i, j); }
        par[j] = i;
        size[i] += size[j];
    }
    bool areSame(int i, int j) { return getRoot(i) == getRoot(j); }
    int getSize(int i) { return size[getRoot(i)]; }
};
