struct UF{
  std::vector<int> par, dep, sz;
  UF(int n){
    par.resize(n+1), dep.resize(n+1), sz.resize(n+1);
    init(n);
  }
  void init(int nu) {
    for(int iu=0;iu<=nu;iu++){
      par[iu] = iu;
      dep[iu] = 0;
      sz[iu] = 1;
    }
  }
  int find(int xu){
    if(par[xu] == xu) return xu;
    return par[xu] = find(par[xu]);
  }
  void unite(int xu, int yu){
    xu=find(xu);
    yu=find(yu);
    if(xu == yu) return;
    if(dep[xu] < dep[yu]){
      sz[yu] += sz[xu];
      par[xu] = yu;
    }else{
      par[yu] = xu;
      sz[xu] += sz[yu];
      if(dep[xu] == dep[yu]) dep[xu]++;
    }
  }
  bool same(int xu, int yu){ return find(xu) == find(yu);}
  int get_size(int x){return sz[find(x)];}
};

void err(){
  std::cout << "No" << '\n';
  exit(0);
}
int main(int argc, char const *argv[]) {
  ll n, m, q;std::cin >> n >> m >> q;
  vvl dat = VV(q, 3, 0, ll);
  for(int i=0;i<q;i++) scanf("%lld %lld %lld", &dat[i][1], &dat[i][2], &dat[i][0]);
  sort(all(dat));

  //c = 0
  UF uf(n+1);
  vll use(n+1, 0);
  for(int i=0;i<q;i++){
    if(dat[i][0]==0){
      uf.unite(dat[i][1], dat[i][2]);
    }else{
      if(uf.same(dat[i][1], dat[i][2])) err();
    }
  }
  //全ての0のグループに対し、1グループのみ隣接してはダメ
  ll g = 0, z = 0;
  //各グループはsize - 1 本の辺を消費
  for(int i=0;i<n;i++){
    if(use[uf.find(i)]) continue;
    g++;
    z += uf.sz[uf.find(i)] - 1;
    use[uf.find(i)] = 1;
  }

  //1グループの時、本数は一定(n-1)
  if(g==1){
    std::cout << (m==n-1?"Yes":"No") << '\n';
    return 0;
  }
  //2グループの時1があるとダメ、ない場合、本数は一定(n-1)
  if(g==2){
    std::cout << (dat[q-1][0]?"No":(m==n-1?"Yes":"No")) << '\n';
    return 0;
  }
  //連結成分同士のマージはグループ数x>=3に対し、最小x本、最大xC2本(完全グラフ)で達成できる
  //1がない場合、最小はn-1本
  ll min_edge = z + g;
  if(dat[q-1][0]==0) min_edge = n-1;
  ll max_edge = z + (g*(g-1))/2;
  //std::cout << g << " " << z << " " << m << '\n';
  if(min_edge<=m&&m<=max_edge) std::cout << "Yes" << '\n';
  else std::cout << "No" << '\n';
  return 0;
}

