// Union-Find木
// 初期化 UF(N); Nは要素数
// 結合 unite(x,y); 同じ集合か判定 same(x,y);
// 集合の数 count
struct UF{
  vector<int> par,sizes;
  int cnt;
  UF(int N) : par(N),sizes(N, 1),cnt(N){ for(int i=0; i<N; i++) par[i]=i; }

  int find(int x){ return par[x]==x ? x : par[x] = find(par[x]); }

  bool same(int x,int y){ return find(x) == find(y); }

  int size(int x){ return sizes[find(x)]; }

  void unite(int x, int y){
    x = find(x); y = find(y);
    if(x == y) return;
    if(sizes[x] < sizes[y]) swap(x,y);
    par[y] = x;
    sizes[x] += sizes[y];
    cnt--;
  }

  int count() const{return cnt;}
};

// トポロジカルソート 任意のグラフに使用可能(たぶん) O(E+V)
// DAGであるときはtrueを、閉路が存在するときfalseを返す
template<typename T>
bool TopologicalSort(vector<int> &v , T &g){
  int N = g.size();
  vector<int> marked(N , 0) , temp(N , 0);
  v.clear(); v.reserve(N);
  // 訪問して帰りがけ順にvに追加
  auto visit = [&](auto f, int i) -> bool{
    if(temp[i] == 1) return false;
    if(marked[i] == 0){
      temp[i] = 1;
      for(auto &e : g[i]){
        if(f(f , e) == false) return false;
      }
      marked[i] = 1;
      v.push_back(i);
      temp[i] = 0;
    }
    return true;
  };

  for(int i = 0 ; i < N ; i++){
    if(marked[i] == 0) {
      if(visit(visit , i) == false) return false;
    }
  }
  reverse( v.begin() , v.end() );
  return true;
}

