			X[A[i]].push_back(B[i]);
			X[B[i]].push_back(A[i]);
		}
		if (C[i] == 1) flag = true;
	}
	for (int i = 0; i < N; i++) {
		if (col[i] >= 1) continue;
		cnt++; dfs(i);
	}

