#include <iostream>
#include <vector>

using namespace std;

void
dfs(int i,
    int gid,
    vector<int>& group_id,
    const vector<vector<int>>& adj_list)
{
  if ( group_id[i] != -1 ) {
    return;
  }
  group_id[i] = gid;
  for ( int j: adj_list[i] ) {
    dfs(j, gid, group_id, adj_list);
  }
}

int
main(int argc,
     char** argv)
{
  int N;
  int M;
  int Q;
  cin >> N >> M >> Q;

  vector<vector<int>> adj_list(N);
  vector<pair<int, int>> multi_pair_list;

  for ( int i = 0; i < Q; ++ i ) {
    int a, b, c;
    cin >> a >> b >> c;
    if ( c == 0 ) {
      adj_list[a].push_back(b);
      adj_list[b].push_back(a);
    }
    else {
      multi_pair_list.push_back(make_pair(a, b));
    }
  }

  if ( M == N - 1 && multi_pair_list.size() > 0 ) {
    cout << "No" << endl;
    return 0;
  }

  vector<int> group_id(N, -1);
  int gid = 0;
  for ( int i = 0; i < N; ++ i ) {
    if ( group_id[i] != -1 ) {
      continue;
    }
    dfs(i, gid, group_id, adj_list);
    ++ gid;
  }

  for ( auto p: multi_pair_list ) {
    int a = p.first;
    int b = p.second;
    if ( group_id[a] == group_id[b] ) {
      cout << "No" << endl;
      return 0;
    }
  }

  int K = gid;
  if ( K == 2 ) {
    K = 1;
  }

  if ( M <= N + K * (K - 3) / 2 ) {
    cout << "Yes" << endl;
  }
  else {
    cout << "No" << endl;
  }

  return 0;
}

#include <bits/stdc++.h>
using namespace std;

typedef long long ll;

const int MAXN = 1e5 + 5;

ll M;
int N, Q;
vector <pair <int, int>> v;
int dad[MAXN], rnk[MAXN];

int find(int x) {
	return dad[x] == x ? x : dad[x] = find(dad[x]);
}

void join(int x, int y) {
	x = find(x);
	y = find(y);
	if (x == y)
		return;
	if (rnk[x] > rnk[y])
		swap(x, y);
	dad[x] = y;
	rnk[y] += rnk[x] == rnk[y];
}

void load() {
	scanf("%d%lld%d", &N, &M, &Q);
	for (int i = 0; i < N; i++) 
		dad[i] = i;
	while (Q--) {
		int a, b, c;
		scanf("%d%d%d", &a, &b, &c);
		if (c)
			v.push_back({a, b});
		else
			join(a, b);
	}
}

bool solve() {
	if (M == N - 1)
		return v.empty();

	for (auto it : v)
		if (find(it.first) == find(it.second))
			return false;

	int comps = 0;
	for (int i = 0; i < N; i++)
		comps += find(i) == i;

	return comps >= 3 && M <= N + (ll)comps * (comps - 3) / 2;
}

int main() {
	load();
	puts(solve() ? "Yes" : "No");
	return 0;
}

