struct UnionFind {
  vector<int> data;
  UnionFind(int size) : data(size, -1) { }
  //木の根なら-(size of tree) それ以外は木の根のindexが入っている。       
  bool unite(int x, int y) {
    x = root(x); y = root(y);
    if (x != y) {
      if (data[y] < data[x]) swap(x, y);
      data[x] += data[y]; data[y] = x;
    }
    return x != y;
  }
  bool same(int x, int y) {
    return root(x) == root(y);
  }
  int root(int x) {
    return data[x] < 0 ? x : data[x] = root(data[x]);
  }
  int size(int x) {
    return -data[root(x)];
  }
};

int main(){
  ios::sync_with_stdio(false);
  cin.tie(0);

  int n,m,q;
  cin >> n >> m >> q;
  int a[n],b[n],c[n];
  UnionFind s(n);
  rep(i,q){
    cin >> a[i] >> b[i] >> c[i];
    if(c[i]==0) s.unite(a[i],b[i]);
  }
  int ed=m;
  int tree=0;
  int v_rest=n;
  rep(i,n){
    if(s.root(i)==i){
      if(s.size(i)>1){
	tree++;
	v_rest-=s.size(i);
      }
      ed-=s.size(i)-1;
    }
  }
  bool ok=true;
  if(ed<0) ok=false;

  bool loop=false;
  rep(i,q){
    if(c[i]==1){
      loop=true;
      if(s.same(a[i],b[i])) ok=false;
    }
  }
  int v=tree+v_rest;
  if(!loop){
    if(v*(v-1)/2<ed) ok=false;
  }
  else if(tree+v_rest>=3){
    if(v*(v-1)/2<ed) ok=false;
  }
  else ok=false;

  if(ok) cout << "Yes" << endl;
  else cout << "No" << endl;



  return 0;


}

