using namespace std;
using ll = long long;

class DSU {
	private:
		vector<int> comp, siz;
	public:
		DSU(int n) : comp(n), siz(n, 1) {
			for (int i = 0; i < n; ++i) comp[i] = i;
		}
		int getc(int i) {
			if (comp[i] != i) comp[i] = getc(comp[i]);
			return comp[i];
		}
		bool join(int a, int b) {
			a = getc(a);
			b = getc(b);
			if (a == b) return false;

			if (siz[a] < siz[b]) swap(a, b);
			siz[a] += siz[b];
			comp[b] = a;
			return true;
		}
		int compSize(int i) { return siz[getc(i)]; }
};

bool solve() {
	int n, m, q;
	cin >> n >> m >> q;

	int cc = n; // component count
	DSU dsu(n);
	vector<pair<int, int>> bans;
	for (int i = 0; i < q; ++i) {
		int a, b, c;
		cin >> a >> b >> c;
		if (c == 0) cc -= dsu.join(a, b);
		else bans.emplace_back(a, b);
	}
	if (cc == 2) return false;
	for (auto pr : bans) {
		if (dsu.getc(pr.first) == dsu.getc(pr.second)) return false;
	}
	if (cc == 1) return (m == n-1);
	else return (n <= m && m <= n-cc + (ll)cc*(cc-1)/2);
}

int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(0);

	bool res = solve();
	cout << (res ? "Yes" : "No") << '\n';
}

