        }
    }
    rep(i, Q) {
        if (C[i] == 0) continue;
        if (same(A[i], B[i])) {
            cout << "No" << endl;
            return 0;
        }
        if (N - c0 < 3) {
            cout << "No" << endl;
            return 0;
        }
    }
    if (M - c0 > (N - c0) * (N - c0 - 1) / 2) {
        cout << "No" << endl;
        return 0;
    }
    if (M - c0 < c1) {
        cout << "No" << endl;
        return 0;
    }
    cout << "Yes" << endl;
}

