const int nn = 1e5+5;
int par[nn];

int find(int u){
    if(par[u]==u) return u;
    par[u] = find(par[u]);
    return par[u];
}

void unify(int u,int v){
    u = find(u);
    v = find(v);
    if(u!=v) par[u]=v;
}

void solve()
{
    int n,m,q;cin>>n>>m>>q;
    int a[q],b[q],c[q];
    for(int i=0;i<n;i++){
        par[i]=i;
    }
    for(int i=0;i<q;i++){
        cin>>a[i]>>b[i]>>c[i];
        if(c[i]==0) unify(a[i], b[i]);
    }
    int cnt=0, tot=0;
    for(int i=0;i<q;i++){
        if(c[i]==0) continue;
        int u=find(a[i]), v=find(b[i]);
        if(u==v){
            // cout<<"No\n";
            // return;
        }
        else cnt=1;
    }
    for(int i=0;i<n;i++){
        int u=i;
        if(par[u]!=u) m--;
        else tot++;
    }
    if(cnt) cnt=tot;
    else cnt=tot-1;
    // dbg3(cnt,m,tot);
    if(cnt<=m && m<= 1ll*tot*(tot-1)/2) cout<<"Yes\n";
    else cout<<"No\n";
}


