                cout<<"No"<<endl;
                return 0;
            }
        }
    }
    //k:連結成分の個数
    int k=0;
    rep(i,n){
        if(i==uf.par[i]) k++;
    }

    /*
    木なら単に連結成分同士をつなげて一つの大きな木にすればいい。
