  cin>>n>>m>>q;
  vector<Int> as(q),bs(q),cs(q);
  for(Int i=0;i<q;i++) cin>>as[i]>>bs[i]>>cs[i];

  // UF for BCC
  UnionFind bc(n),uf(n);
  for(Int i=0;i<q;i++){
    if(cs[i]!=1) continue;
    bc.unite(as[i],bs[i]);
    uf.unite(as[i],bs[i]);
  }

  Int num=0;
  for(Int i=0;i<q;i++){
    if(cs[i]!=0) continue;
    if(uf.same(as[i],bs[i])) drop("No");
    uf.unite(as[i],bs[i]);
    num++;
  }

  Int cnt=0;

  // # components its size is 1, 2
  Int v1=0,v2=0;

  // lower_bound
  Int lb=num;
  for(Int i=0;i<n;i++){
    if(uf.size(i)==1){
      // isolated
      cnt++;
      continue;
    }
    if(bc.find(i)!=i) continue;
    Int sz=bc.size(i);
    if(sz==1) continue;
    if(sz==1) v1++;
    if(sz==2) v2++;
    if(sz>=3) lb+=sz;
  }

  // check connected
  {
    Int sz=0;
    for(Int i=0;i<n;i++) chmax(sz,uf.size(i));
    // 1 component + isolated vertices
    assert(sz+cnt==n);
  }

  // number of isolated vertices is not enough
  //cout<<v1<<" "<<v2<<" "<<cnt<<endl;
  if(v1*2+v2*1>cnt) drop("No");

  cnt-=v1*2+v2*1;
  lb+=(v1+v2)*3;

  // upper_bound
  Int ub=num,mx=0;
  for(Int i=0;i<n;i++){
    if(uf.size(i)==1) continue;
    if(bc.find(i)!=i) continue;
    Int sz=bc.size(i);
    if(sz==1) continue;
    if(sz<=3) sz=3;
    ub+=sz*(sz-1)/2;
    chmax(mx,sz);
  }
  ub-=mx*(mx-1)/2;
  ub+=(mx+cnt)*(mx+cnt-1)/2;

  //cout<<cnt<<" "<<mx<<":"<<lb<<" "<<ub<<endl;
  if(lb<=m&&m<=ub) drop("Yes");
  //assert(0);

  drop("No");
  return 0;
}

