const ll MAXN = 1e5 + 10;
ll rankk[MAXN];
ll parent[MAXN];

ll pare(ll x){
    while(parent[x] != x){
        parent[x] = parent[parent[x]];
        x = parent[x];
    }
    return parent[x];
}

void unionn(ll x,ll y){
    x = pare(x),y = pare(y);

    if(x == y) return;

    if(rankk[x] > rankk[y]){
        rankk[x] += rankk[y];
        parent[y] = x;
    }else {
        rankk[y] += rankk[x];
        parent[x] = y;
    }
}

bool visit[MAXN];

vector<pair<ll,ll>> doub;
void solve(){
    ll n,m,q; cin>>n>>m>>q;

    FOR(i,1,n) parent[i] = i,rankk[i] = 1;

    FOR(i,1,q){
        ll a,b,c; cin>>a>>b>>c; a++,b++;

        if(c == 0) unionn(a,b);
        else doub.push_back({a,b});
    }

    if(m == n-1){
        if(doub.size()) cout<<"No\n";
        else cout<<"Yes\n";
        return;
    }

    for(auto x:doub){
        if(pare(x.first) == pare(x.second)){
            cout<<"No\n";
            return;
        }
    }   

    ll k = 0;

    FOR(i,1,n){
        if(!visit[pare(i)]){
            visit[pare(i)] = 1;
            k++;
        }
    }

    if(m <= n - k + (k*(k-1))/2){
        cout<<"Yes\n";
    }else cout<<"No\n";
}   

