			if(c == 0)c0.push_back(make_pair(a, b));
			else c1.push_back(make_pair(a, b));
			f[a] = f[b] = false;
		}
		int sf = accumulate(f.begin(), f.end(), 0);
		for(auto t: c0)uf0.unionSet(t.first, t.second);
		for(auto t: c1){
			if(uf0.findSet(t.first, t.second)){
