int U[100009], V[100009], T[100009], P[100009], C[100009];

int root(int v) {
    if(P[v] == v) return v;
    return P[v] = root(P[v]);
}

void merg(int u, int v) {
    u = root(u); v = root(v);
    if(u != v) P[u] = v;
}

void fail() {
    puts("No");
    exit(0);
}

int main() {
    int N, M, Q; scanf("%d%d%d",&N,&M,&Q);
    for(int i=0; i<N; i++) P[i] = i;
    for(int i=0; i<Q; i++) {
        scanf("%d%d%d", &U[i], &V[i], &T[i]);
        if(T[i] == 0) {
            if(root(U[i]) == root(V[i])) fail();
            merg(U[i], V[i]);
            C[U[i]] = 1; C[V[i]] = 1;
