  rep(i,q){
    cin >> a[i] >> b[i] >> c[i];
    if(c[i]==0) s.unite(a[i],b[i]);
  }
  ll ed=m;
  int cc=0;
  ll v=0;
  rep(i,n){
    if(s.root(i)==i){
      v++;
      cc++;
      ed-=s.size(i)-1;
    }
  }
  bool ok=true;
  if(ed<0) ok=false;

  bool loop=false;

  rep(i,q){
    if(c[i]==1){
      loop=true;
      if(s.same(a[i],b[i])) ok=false;
    }
  }
  if(!loop){
    if(n-1!=m) ok=false;
  }
  else{
    if(m>n+cc*(cc-3)/2) ok=false;
      //    if((v*(v-1)/2<ed)) ok=false;
  }

  if(ok) cout << "Yes" << endl;
  else cout << "No" << endl;



  return 0;


}

