class UnionFind {
	vector<int> data;
	public:
	int independentSet;
	UnionFind(int size) : data(size, -1), independentSet(size) { }
	bool unionSet(int x, int y) {
		x = root(x); y = root(y);
		if (x != y) {
			if (data[y] < data[x]) swap(x, y);
			data[x] += data[y]; data[y] = x;
			independentSet--;
		}
		return x != y;
	}
	bool findSet(int x, int y) {
		return root(x) == root(y);
	}
	int root(int x) {
		return data[x] < 0 ? x : data[x] = root(data[x]);
	}
	int size(int x) {
		return -data[root(x)];
	}
};

class Solution {
public:
	void solve() {
		int n, m, q;
		cin >> n >> m >> q;
		UnionFind uf0(n);
		vector<pair<int, int>> c1;
		for(int Q=0; Q < q; Q++){
			int a, b, c;
			cin >> a >> b >> c;
			if(c == 0)uf0.unionSet(a, b);
			else c1.push_back(make_pair(a, b));
		}
		if(m == n-1){
			if(c1.size() != 0)cout << "No" << endl;
			else cout << "Yes" << "\n";
			return;
		}
		for(auto t: c1){
			if(uf0.findSet(t.first, t.second)){
				cout << "No" << endl;
				return;
			}
		}
		long long k = uf0.independentSet;
		if(m <= n + (k*(k-3))/2 && m >= n)cout << "Yes" << "\n";
		else cout << "No" << "\n";
		return;
	};
};

int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(nullptr);
	Solution solution;
	solution.solve();
	return 0;
}

