#define MAX_N 200000

int par[MAX_N];
int rnk[MAX_N];
long long int sz[MAX_N];

// 初期化
void init(int n){
	for(int i = 0; i < n; i++){
		par[i] = i;
		rnk[i] = 0;
	}
}

// x の親を返す
int find(int x){
	if(par[x] == x){
		return x;
	}
	return par[x] = find(par[x]);
}

// x と y を併合する
int unite(int x, int y){
	int x_par = find(x);
	int y_par = find(y);
	if(x_par == y_par){
		return 0;
	}

	if(rnk[x_par] < rnk[y_par]){
		sz[y_par] = sz[x_par] + sz[y_par];
		par[x_par] = y_par;
	}else{
		sz[x_par] = sz[x_par] + sz[y_par];
		par[y_par] = x_par;
		if(rnk[x_par] == rnk[y_par]){
			rnk[x_par]++;
		}
	}
  return 1;
}

// x, y が同じグループか判定
bool same(int x, int y){
	return (find(x) == find(y));
}

int main(){
  long long int N, M, Q;
  cin >> N >> M >> Q;
  init(N);
  vector<P> v;
  long long int cnt = N;
  for(int i = 0; i < Q; i++){
    int a, b, tp;
    cin >> a >> b >> tp;
    if(tp == 0){
      cnt -= unite(a, b);
    }else{
      v.push_back(P(a, b));
    }
  }
  for(P p : v){
    if(same(p.first, p.second)){
      cout << "No" << endl;
      return 0;
    }
  }
  if(cnt == 2 && v.size() > 0){
    cout << "No" << endl;
    return 0;
  }
  long long int lim1 = N;
  if(v.size() == 0){
    lim1 = N - 1;
  }
  long long int lim2 = cnt * (cnt - 1) / 2 + (N - cnt);
  if(lim1 <= M && M <= lim2){
    cout << "Yes" << endl;
  }else{
    cout << "No" << endl;
  }
  return 0;
}

