	if (c == 0) {
	    U.link(a, b);
	} else {
	    bi = true;
	    P.emplace_back(a, b);
	}
    }

    bool yes;
    if (M == N-1 && bi) {
	yes = false;
    } else {
	yes = true;
	EACH (e, P) {
	    int a = e->first, b = e->second;
	    if (U.same(a, b)) yes = false;
	}

	LL c = 0;
	REP (i, N) if (U.root(i) == i) {
	    c++;
	}
	if (M - N > c*(c-1)/2 - c) yes = false;
    }
    puts(yes? "Yes": "No");
}

