int main() {
  cin.tie(nullptr); ios::sync_with_stdio(false);

  int N,M,Q; cin>>N>>M>>Q;

  vector<int> par(N);
  iota(par.begin(), par.end(), 0);
  auto root = [f=[&](auto g, int x) {
    if (par[x] == x)
      return x;
    return par[x] = g(g, par[x]);
  }] (int x) {
    return f(f, x);
  };
  auto unite = [&](int x, int y) {
    return par[root(y)] != (par[root(y)] = root(x));
  };
  struct Cond{
    bool single;
    int f, t;
  };
  Cond conds[Q];
  for (int q = 0; q < Q; q++) {
    int a, b, c; cin>>a>>b>>c;
    conds[q] = {c == 0, a, b};
  }
  int c_graph = N;
  for (auto cond : conds) {
    if (not cond.single)
      continue;
    if (unite(cond.f, cond.t))
      c_graph--;
  }
  bool is_tree = true;
  for (auto cond : conds) {
    if (cond.single)
      continue;
    is_tree = false;
    if (root(cond.f) == root(cond.t)) {
      cout << "No" << endl;
      return 0;
    }
  }
  int c_min = is_tree ? N-1 : N;
  bool ans = M >= c_min and M <= N-c_graph + c_graph*(c_graph-1)/2;
  cout << (ans ? "Yes" : "No") << endl;

  return 0;
}

