const int64_t MAX = 100005;

int64_t N[MAX];
int64_t L[MAX];
struct Query
{
    int64_t a,b,c;
    bool operator<(const Query& q) const
    {
        return c > q.c;
    }
} Q[MAX];
int64_t n,m,q;

int64_t Find(int64_t a)
{
    if (N[a] == a) return a;
    else return N[a] = Find(N[a]);
}

void Union(int64_t l, int64_t r)
{
    if (L[l] < L[r]) Union(r, l);
    else {
        ++L[l];
        N[r] = l;
    }
}

int64_t main()
{
    std::ios_base::sync_with_stdio(0);
    std::cin >> n >> m >> q;
    std::set<int64_t> U;
    for (int64_t i=0;i<n;++i) N[i] = i;
    for (int64_t i=0;i<q;++i) std::cin >> Q[i].a >> Q[i].b >> Q[i].c;
    std::sort(Q, Q+q);
    bool result = true;
    for (int64_t i=0;i<q;++i)
    {
        if (Q[i].c) Union(Find(Q[i].a), Find(Q[i].b));
        else
        {
            result &= Find(Q[i].a) != Find(Q[i].b);
        }
        U.insert(Q[i].a);
        U.insert(Q[i].b);
    }
    int64_t nn = n - U.size();
    int64_t ml = n-1;
    int64_t mr = n-1;
    std::map<int64_t, int64_t> C;
    for (int64_t i=0;i<n;++i) C[Find(i)]++;
    int64_t maxm = 0;
    for (auto it : C)
    {
        if (it.second > 2)
        {
            maxm = std::max(maxm, it.second);
            ++ml;
            mr += it.second*(it.second-1)/2 - it.second+1;
        }
        else if (it.second == 2)
        {
            if (nn <= 0) result = false;
            --nn;

            maxm = std::max(maxm, 3);
            ++ml;
            mr += 1;
        }
    }
    mr -= maxm*(maxm-1)/2 - maxm+1;
    maxm += nn;
    mr += maxm*(maxm-1)/2 - maxm+1;
    result &= ml <= m && m <= mr;
    if (ml == n-1 && m > n-1) result = false;
    std::cout << (result ? "Yes" : "No") << std::endl;

    return 0;
}

