struct unionfind {
  vector<int> dat;

  unionfind(int n) : dat(n, -1) {}

  int find(int x) {
    if (dat[x] < 0) return x;
    return dat[x] = find(dat[x]);
  }

  void unite(int x, int y) {
    x = find(x);
    y = find(y);
    if (x == y) return;
    if (dat[x] > dat[y]) swap(x, y);
    dat[x] += dat[y];
    dat[y] = x;
  }

  int size(int x) {
    return -dat[find(x)];
  }

  bool same(int x, int y) {
    return find(x) == find(y);
  }
};

pair<bool, int> check() {
  int N, M, Q; cin >> N >> M >> Q;
  vector<int> A(Q), B(Q), C(Q);
  rep(i, Q) cin >> A[i] >> B[i] >> C[i];

  unionfind I(N);
  rep(i, Q) if (C[i] == 0) I.unite(A[i], B[i]);
  rep(i, Q) if (C[i] == 1 && I.size(A[i]) >= 2 && I.size(B[i]) >= 2 && I.same(A[i], B[i])) return {false, 1};
  bool any = false;
  vector<set<int>> st(N);
  rep(i, Q) if (C[i] == 1) {
    st[I.find(A[i])].insert(A[i]);
    st[I.find(B[i])].insert(B[i]);
  }
  rep(i, N) if (st[I.find(i)].size() >= 2) return {false, 10};
  int cnt = 0;
  rep(i, N) cnt += I.find(i) == i;
  if (cnt >= 3) return {true, 100};
  return {false, 404};
}

