struct UnionFind {
    vector<int> par, rank;
    int count_comp;

    UnionFind(int n) : par(n , -1), rank(n, 0),count_comp(n) { }

    int root(int x) {
        if (par[x] == -1) return x;
        else return par[x] = root(par[x]);
    }

    bool same(int x, int y) {
        return root(x) == root(y);
    }

    bool unite(int x, int y) {
        x = root(x); y = root(y);
        if (x == y) return false;
        if (rank[x] < rank[y]) swap(x, y);
        if (rank[x] == rank[y]) ++rank[x];
        par[y] = x;
        count_comp--;
        return true;
    }
};

