const int MAXN= 1e5 + 10;

int f[MAXN],n;
long long m;
int q;

int find(int x)
{
    int t = x;
    while (f[x] != x) x = f[x];
    while (f[t] != t)
    {
        int tmp = f[t];
        f[t] = x;
        t = tmp;
    }
    return x;
}

void insert(int x,int y)
{

    int fx = find(x),fy = find(y);
    if (fx != fy)
    {
        f[fx] = fy;
    }
}

struct node{
    int u,v;
}opt[MAXN];

int num[MAXN];

int main()
{
    scanf("%d%lld%d",&n,&m,&q);
    for (int i = 0;i<n;i++) f[i] = i;
    int len = 0;
    for (int i = 1,u,v,c;i<=q;i++)
    {
        scanf("%d%d%d",&u,&v,&c);
        num[u] = num[v] = 1;
        if (c == 0) insert(u,v);
        else
        {
            opt[++len].u = u;
            opt[len].v = v;
        }
    }
    int b = 0;
    for (int i = 0;i<n;i++)
    {
        if (num[i] == 0) b++;
    }
    for (int i = 1;i<=len;i++)
    {
        if (find(opt[i].u) == find(opt[i].v))
        {
            cout<<"No";
            return 0;
        }
    }
    int cnt = 0;
    for (int i = 0;i<n;i++) if (f[i] == i) cnt++;
    cnt -= b;
    int minn = n - b;
    if (cnt == 2)
    {
        if (b == 0)
        {
            cout<<"No";
            return 0;
        }
        minn++;
        b--;
        cnt++;
    }
    long long maxn = minn - cnt + (long long)(cnt + b) * (cnt + b - 1) / 2;
    //cout<<cnt<<' '<<minn<<' '<<maxn<<'\n';
    if (minn <= m && m <= maxn) printf("Yes");
    else cout<<"No";
    return 0;
}

