typedef std::pair<int,int> P;
const int N=1e5+5;
int par[N],n,m,q,cnt;
void init() {
    for(int i=0;i<n;i++) par[i]=i;
    cnt=n;
}
int fd(int x) {
    return par[x]==x?x:par[x]=fd(par[x]);
}
void unite(int x,int y) {
    x=fd(x);y=fd(y);
    if(x==y) return;
    --cnt;
    par[x]=y;
}
int main() {
    scanf("%d%d%d",&n,&m,&q);
    init();
    std::vector<P> g;
    for(int u,v,c;q--;) {
        scanf("%d%d%d",&u,&v,&c);
        if(c==0) unite(u,v);
        else g.push_back(P(u,v));
    }
    if(m==n-1) return !printf("%s",g.size()>0?"No":"Yes");
    for(P c:g) if(fd(c.first)==fd(c.second)) return !printf("No");
    printf("%s",m<=n-cnt+1LL*cnt*(cnt-1)/2?"Yes":"No");
    return 0;
}

