int get_root(int u);
bool merge(int u, int v);

int main() {
	fast_cin();
	int n, q; ll m;
	cin >> n >> m >> q;
	for (int i = 0; i < n; ++i) {
		par[i] = i;
	}
	bool any_cycle = false;
	ll components = n;
	for (int i = 1; i <= q; ++i) {
		cin >> a[i] >> b[i] >> c[i];
		if (c[i] == 0) {
			components -= merge(a[i], b[i]);
		} else {
			any_cycle = true;
		}
	}
	bool ok = true;
	for (int i = 1; i <= q; ++i) {
		if (c[i] == 1) {
			if (get_root(a[i]) == get_root(b[i])) {
				ok = false;
				break;
			}
		}
	}
	ll min_edges = (any_cycle ? n : n - 1);
	ll max_edges = (n - components) + (components * (components - 1)) / 2;
	ok &= (min_edges <= m and m <= max_edges);
	if (ok) {
		cout << "Yes\n";
	} else {
		cout << "No\n";
	}
}

int get_root(int u) {
	if (u != par[u]) {
		par[u] = get_root(par[u]);
	}
	return par[u];
}

bool merge(int u, int v) {
	u = get_root(u);
	v = get_root(v);
	if (u == v) {
		return false;
	}
	par[u] = v;
	return true;
}

