			if (uf.ren[i] == 1)uf.r2[i] = 0;
			else uf.r2[i] = 1;
			uf.ren[i] = 1;
		}
	}
	for (int i = 0; i < pat.size(); i++)
	{
		int a = pat[i].first, b = pat[i].second;
		uf.unite(a, b);
	}
	int c = 0;
	int usren = 0;
	vector<ll>v;
	for (int i = 0; i < num; i++)
	{
