int main() {
	int n, m, q;
	scanf("%d%d%d", &n, &m, &q);
	vector<int> par(n);
	iota(par.begin(), par.end(), 0);
	function<int(int)> root = [&](int a) {
		if (par[a] == a) return a;
		return par[a] = root(par[a]);
	};
	vector<pair<int, int>> dups;
	int comps = n;
	while (q--) {
		int a, b, c;
		scanf("%d%d%d", &a, &b, &c);
		int ra = root(a), rb = root(b);
		if (c == 0) {
			if (ra == rb) continue;
			par[ra] = rb;
			--comps;
		} else {
			dups.emplace_back(a, b);
		}
	}
	if (m < n - 1) no();
	bool has = false;
	for (auto& e : dups) {
		int a = e.first, b = e.second;
		int ra = root(a), rb = root(b);
		if (ra == rb) no();
		has = true;
	}
	if (comps <= 2) {
		if (has) no();
		if (m != n - 1) no();
	} else {
		// At least 3 components.
		if (m == n - 1) {
			if (has) no();
		} else {
			ll mx = (ll)comps * (comps - 1) / 2;
			int used = n - comps;
			if (used + mx < m) no();
		}
	}
	printf("Yes\n");
}

