	REPN(i, 1, n) {
		par_br[i] = par_con[i] = i;
	}
	REP(i, 0, SZ(bridges)) {
		a = bridges[i]._1, b = bridges[i]._2;
		a = get_par_br(a), b = get_par_br(b);
		if (a != b) {
			par_br[b] = a;
		}
	}
	REP(i, 0, SZ(cons)) {
		a = cons[i]._1, b = cons[i]._2;
		a = get_par_br(a), b = get_par_br(b);
		if (a == b) {
			finish_no();
		}
		a = get_par_con(a), b = get_par_con(b);
		if (a != b) {
			par_con[b] = a;
		}
	}
	ll comp_br = 0, comp_con = 0;
	REPN(i, 1, n) {
		int br = get_par_br(i);
		int con = get_par_con(i);
		cnt_br[br]++;
		cnt_con[con]++;
		if (br == i) {
			comp_br++;
		}
		if (con == i) {
			comp_con++;
		}
	}
	/*if (comp_br == 2 && SZ(cons) > 0) {
		finish_no();
	}*/

	ll mx = n - comp_br + (ll)comp_br * (ll)(comp_br - 1) / 2ll;
	ll mn = n - comp_br;
	int cnt2 = 0;
	int active = 0;
	REPN(i, 1, n) {
		if (par_con[i] == i) {
			if (cnt_con[i] > 1) {
				active++;
				mn += cnt_con[i] - 1;
				if (cnt_con[i] == 2) {
					cnt2++;
				}
			}
		}
	}

	if (comp_con == 1 && cnt2 == 1) {
		finish_no();
	}
	if (active == 1 && cnt2 == 1) {
		mn += 2;
	} else {
		mn += active;
	}

	mn = n;
	if (m < mn || m > mx) {
		finish_no();
	}

	//cout << mn << " " << m << " " << mx << endl;
	printf("Yes\n");
}   

