// Union-Find木
// 初期化 UF(N); Nは要素数
// 結合 unite(x,y); 同じ集合か判定 same(x,y);
// 集合の数 count
struct UF{
  vector<int> par,sizes;
  int cnt;
  UF(int N) : par(N),sizes(N, 1),cnt(N){ for(int i=0; i<N; i++) par[i]=i; }

  int find(int x){ return par[x]==x ? x : par[x] = find(par[x]); }

  bool same(int x,int y){ return find(x) == find(y); }

  int size(int x){ return sizes[find(x)]; }

  void unite(int x, int y){
    x = find(x); y = find(y);
    if(x == y) return;
    if(sizes[x] < sizes[y]) swap(x,y);
    par[y] = x;
    sizes[x] += sizes[y];
    cnt--;
  }

  int count() const{return cnt;}
};

void solve(){
  inl(N,M,Q);
  vi a(Q),b(Q),c(Q);
  rep(i,Q) in(a[i],b[i],c[i]);
  UF uf(N);
  rep(i,Q){
    if(c[i] == 1) continue;
    uf.unite(a[i],b[i]);
  }
  int flg = 0;
  rep(i,Q){
    if(c[i]==0) continue;
    if(uf.same(a[i],b[i])) die("No");
    flg = 1;
  } 
  if(flg == 1){
    if(uf.cnt <= 2 || M == N-1) die("No");
  }
  ll maxedge = N - uf.cnt + (ll)uf.cnt * ((ll)uf.cnt - 1) / 2;
  out(maxedge >= M ? "Yes" : "No");
}

