#include<bits/stdc++.h>

using namespace std;

#define ll  long long
#define ld  double

#define sz(x)   (int)x.size()
#define all(x)  x.begin(),x.end()

#define pb  emplace_back
#define X   first
#define Y   second

const int   N   = 2e5 + 5;

typedef pair<int,int>   ii;

int p[N];
int s[N];

int init(int n) {
    iota(p,p + n,0);
    fill(s,s + n,1);
    return  1;
}
int lead(int x) {
    return p[x] == x ? x : p[x] = lead(p[x]);
}
int join(int x,int y)   {
    x = lead(x);
    y = lead(y);

    if (x == y) return  0;
    if (s[x] < s[y])
        swap(x,y);
    p[y] = x;
    s[x] += s[y];

    return  1;
}

int main()  {
    ios_base::sync_with_stdio(0);
    cin.tie(0); cout.tie(0);

    int n;  cin >> n;
    int m;  cin >> m;
    int q;  cin >> q;

    vector<ii>  v1;
    vector<ii>  v2;

    for(int i = 0 ; i < q ; ++i)    {
        int x;  cin >> x;
        int y;  cin >> y;
        int t;  cin >> t;

        if (t)  v2.pb(x,y);
        else    v1.pb(x,y);
    }

    if (m < n)  {
        if (v2.size())
            cout << "No";
        else
            cout << "Yes";

        return  0;
    }

    init(n);

    for(ii  e : v1) join(e.X,e.Y);
    for(ii  e : v2) {
        int x = lead(e.X);
        int y = lead(e.Y);

        if (x == y) {
            cout << "No";
            return  0;
        }
    }
    int comps = 0;

    for(int i = 0 ; i < n ; ++i)
        if (i == lead(i))
            comps++;

    if (m <= n + 1ll * comps * (comps - 3) / 2)
        cout << "Yes";
    else
        cout << "No";
}

