int findset(int v) {
	if (v == parent[v]) {
		return v;
	}
	return parent[v] = findset(parent[v]);
}


void merge(int a, int b) {
	a = findset(a);
	b = findset(b);
	if (a == b) {
		return;
	}
	parent[a] = b;
	sz[b] += sz[a]; 
}


vector<int> g[MAXN];
