int
main(int argc,
     char** argv)
{
  int N;
  int M;
  int Q;
  cin >> N >> M >> Q;

  if ( M > ((N * (N - 1)) / 2) ) {
    abort();
  }

  MFSet mfset(N);

  vector<pair<int, int>> multi_pair_list;
  bool has_single = false;
  for ( int i = 0; i < Q; ++ i ) {
    int a, b, c;
    cin >> a >> b >> c;
    if ( c == 0 ) {
      mfset.merge(a, b);
      has_single = true;
    }
    else {
      multi_pair_list.push_back(make_pair(a, b));
    }
  }

  if ( M == N - 1 ) {
    // M = N - 1 の時は木構造のグラフとなる．
    if ( multi_pair_list.size() > 0 ) {
      // その場合複数経路はありえない．
      no();
    }
    else {
      yes();
    }
  }

#if 0
  if ( !has_single ) {
    yes();
  }
#endif

  int K = 0;
  for ( int i = 0; i < N; ++ i ) {
    if ( mfset.find(i) == i ) {
      ++ K;
    }
  }

  if ( K == 2 ) {
    K = 1;
  }

  int M_max = N + (K * (K - 3)) / 2;
  if ( M > M_max ) {
    if ( !has_single ) {
      if ( K != N ) {
	abort();
      }
    }
    no();
  }

  for ( auto p: multi_pair_list ) {
    int a = p.first;
    int b = p.second;
    if ( mfset.find(a) == mfset.find(b) ) {
      no();
    }
  }

  yes();

  return 0;
}

