void into(){
  scanf("%d%lld%d",&n,&m,&cq);
  for (int i=1;i<=cq;++i){
	scanf("%d%d%d",&qx[i],&qy[i],&qv[i]);
	++qx[i];++qy[i];
  }
}

int uni[N+9],vis[N+9];

int Query_uni(int k){return k==uni[k]?k:uni[k]=Query_uni(uni[k]);}

int ans;

void Get_ans(){
  if (m<n-1) return;
  for (int i=1;i<=n;++i) uni[i]=i;
  for (int i=1;i<=cq;++i){
	if (qv[i]) continue;
	int fx=Query_uni(qx[i]),fy=Query_uni(qy[i]);
	if (fx==fy) continue;
	uni[fx]=fy;
  }
  int flag=0;
  for (int i=1;i<=cq;++i){
	if (!qv[i]) continue;
