#define N 112345
class UF {
public:
	int p[N], d[N], s[N];

	UF(){
		REP(i, N) p[i] = i;
		fill(d, d+N, 0);
		fill(s, s+N, 1);
	}

	int grp(int a){
		if(a==p[a]) return p[a];
		else return p[a]=grp(p[a]);
	}

	bool mrg(int a, int b){
		a = grp(a);
		b = grp(b);
		if(a==b) return false;
		if(d[a] < d[b]) swap(a, b);
		p[b] = a;
		LAR(d[a], d[b]+1);
		s[a] += s[b];
		return true;
	}
} of_tree;

