    for (int i=0;i<q;++i) std::cin >> Q[i].a >> Q[i].b >> Q[i].c;
    std::sort(Q, Q+q);
    bool result = true;
    for (int i=0;i<q;++i)
    {
        if (Q[i].c) Union(Find(Q[i].a), Find(Q[i].b));
        else
        {
            result &= Find(Q[i].a) != Find(Q[i].b);
        }
        U.insert(Q[i].a);
        U.insert(Q[i].b);
    }
    int nn = n - U.size();
    int ml = n-1;
    int mr = n-1;
    std::map<int, int> C;
    for (int i=0;i<n;++i) C[Find(i)]++;
    int maxm = 0;
    for (auto it : C)
    {
        if (it.second > 2)
        {
            maxm = std::max(maxm, it.second);
            ++ml;
            mr += it.second*(it.second-1)/2 - it.second+1;
        }
        else if (it.second == 2)
        {
            if (nn <= 0) result = false;
            --nn;

            maxm = std::max(maxm, 3);
            ++ml;
            mr += 1;
        }
    }
    mr -= maxm*(maxm-1)/2 - maxm+1;
    maxm += nn;
    mr += maxm*(maxm-1)/2 - maxm+1;
    result &= ml <= m && m <= mr;
    if (ml == n-1 && m > n-1) result = false;
    std::cout << (result ? "Yes" : "No") << std::endl;

