	e[++cnt]=(node){y,hd[x],v,0},hd[x]=cnt;
	e[++cnt]=(node){x,hd[y],v,0},hd[y]=cnt;
}

void dfs(int x)
{
	bo[x]=1;
	for (int i=hd[x]; i; i=e[i].next)
		if (e[i].to!=fa[x]&&e[i].bo)
		{
			dep[e[i].to]=dep[x]+1;
			if (!e[i].val) f[e[i].to]=dep[e[i].to],g[e[i].to]=g[x]; else f[e[i].to]=f[x],g[e[i].to]=dep[e[i].to];
			fa[e[i].to]=x,dfs(e[i].to);
		}
}

int lca(int x,int y)
{
	if (dep[x]<dep[y]) swap(x,y);
	for (int j=17; j>=0; j--)
		if (dep[F[x][j]]>=dep[y]) x=F[x][j];
	if (x==y) return x;
	for (int j=17; j>=0; j--)
		if (F[x][j]!=F[y][j]) x=F[x][j],y=F[y][j];
	return F[x][0];
}

int main()
{
	scanf("%d%lld%d",&n,&m,&q);
	for (int i=1; i<=q; i++) scanf("%d%d%d",&x,&y,&v),addedge(x+1,y+1,v);
	for (int i=1; i<=n; i++) fa[i]=i;
	for (int i=1; i<=q; i++)
	{
		if (ask(e[i*2].to)==ask(e[i*2-1].to)) continue;
		fa[ask(e[i*2].to)]=ask(e[i*2-1].to),e[i*2].bo=e[i*2-1].bo=1;
	}
	dep[0]=-1;
	for (int i=1; i<=n; i++) if (!bo[i]) f[i]=dep[i]=fa[i]=g[i]=0,dfs(i);
	for (int i=1; i<=n; i++) F[i][0]=fa[i];
	for (int j=1; j<=17; j++)
		for (int i=1; i<=n; i++) F[i][j]=F[F[i][j-1]][j-1];
	for (int i=1; i<=q; i++)
		if (!e[i*2].bo) 
		{
			int d1=dep[lca(e[i*2].to,e[i*2-1].to)],d2;
			if (e[i*2].val) d2=max(f[e[i*2].to],f[e[i*2-1].to]); else d2=max(g[e[i*2].to],g[e[i*2-1].to]);
			if (d1<d2) return puts("No"),0;
		}
	for (int i=1; i<=n; i++) fa[i]=i,siz[i]=1;
	int cnt0=0,cnt1=0,cnt2=0;
	for (int i=1; i<=q; i++) if (e[i*2].val)
	{
		if (ask(e[i*2].to)==ask(e[i*2-1].to)) continue;
		siz[ask(e[i*2-1].to)]+=siz[ask(e[i*2].to)];
		fa[ask(e[i*2].to)]=ask(e[i*2-1].to),cnt1++;
	}
	for (int i=1; i<=n; i++) if (fa[i]==i&&siz[i]>1) cnt2++;
	for (int i=1; i<=n; i++) fa[i]=i;
	for (int i=1; i<=q; i++) if (!e[i*2].val)
	{
		if (ask(e[i*2].to)==ask(e[i*2-1].to)) continue;
		fa[ask(e[i*2].to)]=ask(e[i*2-1].to),cnt0++;
	}
	if (cnt0==n-2&&cnt1) return puts("No"),0;
	cnt=n-cnt0,m-=cnt0;
	if (m<cnt1+cnt2||m>1ll*cnt*(cnt-1)/2) return puts("No"),0;
	if (m<cnt-1+(cnt1>0)) return puts("No"),0;
	puts("Yes");
	return 0;
}

