    if ( group_id[i] != -1 ) {
      continue;
    }
    dfs(i, K, group_id, adj_list);
    ++ K;
  }

  bool ng = false;
  for ( auto p: multi_pair_list ) {
    int a = p.first;
    int b = p.second;
    if ( group_id[a] == group_id[b] ) {
      cout << "No" << endl;
      return 0;
      ng = true;
      break;
    }
  }

#if 0
  if ( K == 2 ) {
    abort();
    K = 1;
  }
#endif

  if ( !ng && M <= N + K * (K - 3) / 2 ) {
    cout << "Yes" << endl;
  }
  else {
    cout << "No" << endl;
  }

  return 0;
}

