        }else{
            if(uf.same(a,b)){
            }else{
                uf.unite(a,b);
                K++;
            }
        }
    }
    bool flag[100001]={};
    int c = 0;
    rep(i,n){
        if(!flag[uf.find(i)]){
            c++;
            flag[uf.find(i)]=1;
        }
    }
    if(c<=2&&p.size()!=0){
        //assert(0);
        cout << "No" << endl;
        return 0;
    }
    vector<ll> pp(n);
    UnionFind uf2(n);
    rep(i,p.size()){
        int a = p[i].first;
        int b = p[i].second;
        if(!uf2.same(a,b)&&uf.same(a,b)){
