		}
		if (get(v) == get(u)) {
			cout << "No\n";
			return 0;
		}
	}

	ll maxk = cnt;

	if (mink < 3 && bad.size()) {
		mink = 3;
	}

	if (mink > maxk) {
		cout << "No\n";
		return 0;
	}

	ll add = n - cnt;

	ll emin = mink;
	ll emax = maxk * (maxk - 1) / 2;
	if (add + emin > m || add + emax < m) {
		cout << "No\n";
		return 0;
	}

	cout << "Yes\n";
	return 0;

}

