    while (f[t] != t)
    {
        int tmp = f[t];
        f[t] = x;
        t = tmp;
    }
    return x;
}

void insert(int x,int y)
{

    int fx = find(x),fy = find(y);
    if (fx != fy)
    {
        f[fx] = fy;
    }
