            return;
        }

        set<Int> D;
        G.resize(N);
        set<pair<Int, Int>> edges;

        for (auto e : e1) {
            int a = e.first;
            int b = e.second;
            D.insert(uf.find(a));
            D.insert(uf.find(b));
            if (uf.same(a, b)) {
                cout << "No" << endl;
                return;
            }

            pair<Int, Int> edge(uf.find(a), uf.find(b));
            if (edge.first > edge.second) {
                swap(edge.first, edge.second);
            }
            if (edges.count(edge)) {
                cout << "No" << endl;
                return;
            }

            edges.insert(edge);
        }

        vector<Int> appear(N);
        for (auto e : edges) {
            int a = e.first;
            int b = e.second;
            appear[a]++;
            appear[b]++;
        }
        Int rootcnt = 0;
        for (auto e : appear) {
            if (e == 1) rootcnt++;
        }
        Int add = rootcnt / 2 + rootcnt % 2;
        if (e0.size() + e1.size() + add > M) {
            cout << "No" << endl;
            return;
        }

        if (D.size() + e0.size() > M) {
            cout << "No" << endl;
            return;
        }

        if (e1.size() > 0 && T < 3) {
            cout << "No" << endl;
        } else {
            cout << "Yes" << endl;
        }


    }
};


