struct UnionFind {
    int n, cc, *u;
    UnionFind() : n(0), cc(0), u(NULL) {}
    UnionFind(int n_) : n(n_), cc(n_) {
	u = new int[n_];
	memset(u, -1, sizeof (int) * n);
    }
    UnionFind(const UnionFind &y) : n(y.n), cc(y.cc) {
	u = new int[y.n];
	memcpy(u, y.u, sizeof (int) * n);
    }
    ~UnionFind() {
	delete[] u; u = NULL;
	n = cc = 0;
    }
    friend void swap(UnionFind &x, UnionFind &y) {
	swap(x.n, y.n); swap(x.cc, y.cc); swap(x.u, y.u);
    }
    UnionFind& operator=(UnionFind y) { 
	swap(*this, y);
	return *this;
    }
    int root(int x) {
	int y = x, t;
	while (u[y] >= 0) y = u[y];
	while (x != y) { t = u[x]; u[x] = y; x = t; }
	return y;
    }
    bool link(int x, int y) {
	x = root(x); y = root(y);
	if (x == y) return false;
	if (u[y] < u[x]) swap(x, y);
	u[x] += u[y]; u[y] = x; cc--;
	return true;
    }
    bool same(int x, int y) { return root(x) == root(y); }
    int size(int x) { return -u[root(x)]; }
    int count() { return cc; }
};

int N, Q;
LL M;
UnionFind U;
vector<pair<int, int> > P;

bool solve() {
    if (M == N-1) return P.empty();

    EACH (e, P) {
	int a = e->first, b = e->second;
	if (U.same(a, b)) return false;
    }

    LL c = 0;
    REP (i, N) if (U.root(i) == i) {
	c++;
    }

    if (c <= 2) {
	if (P.empty() && M == N-1) return true;
	else return false;
    }

    if (M - N > c*(c-1)/2 - c) return false;
    else return true;
}

void MAIN() {
    scanf("%d%lld%d", &N, &M, &Q);
    U = UnionFind(N);

    REP (i, Q) {
	int a, b, c;
	scanf("%d%d%d", &a, &b, &c);

	if (c == 0) {
	    U.link(a, b);
	} else {
	    P.emplace_back(a, b);
	}
    }

    bool yes = solve();
    puts(yes? "Yes": "No");
}

