int n, u, v, t, q, dsu[N];
long long m;
vector<pair<int, int>> ve;

int trace(int u) {
    return dsu[u] < 0 ? u : dsu[u] = trace(dsu[u]);
}

bool connect(int u, int v) {
    if ((u = trace(u)) == (v = trace(v))) {
        return false;
    }
    if (dsu[u] > dsu[v]) {
        swap(u, v);
    }
    dsu[u] += dsu[v];
    dsu[v] = u;
    return true;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);
    cin >> n >> m >> q;
    fill(dsu, dsu + n, -1);
    m -= q;
    while (q--) {
        cin >> u >> v >> t;
        if (t == 0) {
            if (connect(u, v)) {
                n--;
            }
        } else {
            ve.push_back({u, v});
        }
    }
    for (pair<int, int> &v : ve) {
        if (!connect(v.first, v.second)) {
            return cout << "No", 0;
        } else {
            n -= 2;
            m -= 2;
        }
    }
    if (m < 0) {
        return cout << "No", 0;
    }
    while (n > 1) {
        n--;
        m -= 2;
    }
    cout << (n >= 1 && m <= 0 ? "Yes" : "No");
}

