struct MERGESET{
	int Mfa[N+3],Msiz[N+3];
	void Init(int Nn){
		for(int i=1;i<=Nn;i++)
			Mfa[i]=i,Msiz[i]=1;
	}
	int FindFa(int u){
		if(u==Mfa[u]) return u;
		return Mfa[u]=FindFa(Mfa[u]);
	}
	bool Merge(int u,int v){
		int Fu=FindFa(u),Fv=FindFa(v);
		if(Fu==Fv) return false;
		Mfa[Fu]=Fv;
		Msiz[Fv]+=Msiz[Fu];
		Msiz[Fu]=0;
		return true;
	}
}Mset;

vector< pair<int,int> > Opt1;

