			Opt1.emplace_back(u,v),
			B1=true;
		else
			Mset.Merge(u,v);
	}
	for(auto it : Opt1){
		int u=it.first,v=it.second;
		int Fu=Mset.FindFa(u),Fv=Mset.FindFa(v);
