namespace Xelmh_UFF {
    class UFF {
        using Int = int;
        std::vector<Int> parent;
        std::vector<Int> rank;


    public:
        explicit UFF(Int n) : parent(n, -1), rank(n, 0) {}
        Int find(Int x) {
            auto &px = parent[x];
            if (px < 0) {
                return x;
            } else {
                return px = find(px);
            }
        }

        bool unite(Int a, Int b) {
            const auto pa = find(a);
            const auto pb = find(b);
            if (pa == pb) return false;

            if (rank[pa] > rank[pb]) {
                parent[pa] += parent[pb];
                parent[pb] = pa;
            } else {
                parent[pb] += parent[pa];
                parent[pa] = pb;

                if (rank[pa] == rank[pb]) {
                    rank[pb]++;
                }
            }
            return true;
        };

        Int size(Int x) {
            const auto px = find(x);
            return -parent[px];
        }

        bool is_same(Int a, Int b) {
            const auto pa = find(a);
            const auto pb = find(b);
            return pa == pb;
        }

    };
}
using namespace Xelmh_UFF;



class solver{
    istream& is;
    ostream& os;

public:
    solver(istream& I, ostream& O) :is(I), os(O) {}
    void run(){
        ll N, M, Q;
        is >> N >> M >> Q;
        if(!is) return;
        UFF uf1(N);
        vector<int> A, B;
        for (int i = 0; i < Q; ++i) {
            int a, b, c;
            is >> a >> b >>c;
            if(c == 0){
                uf1.unite(a, b);
            }
            else {
                A.push_back(a);
                B.push_back(b);
            }
        } // end i
        V_Set ds;
        for (int i = 0; i < N; ++i) {
            ds.insert(uf1.find(i));
        } // end i
        unordered_map<int, int> mp;
        int s = 0;
        for (auto &&d : ds) {
            M -= uf1.size(d) - 1;
            mp[d] = s++;
        } // end d
        if(M > ds.size() * (ds.size() - 1) / 2){
            os << "No\n";
            return;
        }
        UFF uf2(s);
        for (int i = 0; i < A.size(); ++i) {
            uf2.unite(mp[uf1.find(A[i])], mp[uf2.find(B[i])]);
        } // end i
        ds.clear();
        for (auto &&p : mp) {
            int i = p.second;
            ds.insert(uf2.find(i));
        } // end p
        for (auto &&d : ds) {
            M -= uf2.size(d) > 1 ? uf2.size(d) : 0;
        } // end d
        if(M < 0) {
            os << "No\n";
            return;
        }
        os << "Yes\n";

    }
};

