struct UF{
    vi dat;
    UF(int n){
        dat.assign(n,-1);
    }
    int root(int x){
        return dat[x]<0?x:dat[x]=root(dat[x]);
    }
    void unite(int a, int b){
        a=root(a);b=root(b);
        if(a==b)return;
        if(dat[a]>dat[b])swap(a,b);
        dat[a] += dat[b];
        dat[b] = a;
    }
    bool same(int a, int b){
        return root(a)==root(b);
    }
    ll size(int a){
        return -dat[root(a)];
    }
};

