    while(q--){
        int a,b,c;
        scanf("%d%d%d",&a,&b,&c);
        if(c==0){
            // single
            if(!suf.same(a,b) && sduf.same(a,b)){
                fail();
            }
            suf.unite(a,b);
            sduf.unite(a,b);
        }else{
            // double
            if(suf.same(a,b)){
                fail();
            }
            duf.unite(a,b);
            sduf.unite(a,b);
        }
    }

    ll low = 0, high = 0;
    REP(i,n){
        if(suf.root(i)==i){
            low += suf.size(i)-1;
            high += suf.size(i)-1;
        }
    }

    int sdufnum = 0;
    REP(i,n)if(sduf.root(i)==i)sdufnum++;
    if(sdufnum==1){
        REP(i,n)if(duf.root(i)==i){
            ll sz = duf.size(i);
            if(sz==2){
                fail();
            }
            low += sz;
            high += sz*(sz-1)/2;
        }
