	D.init();
	int C = n;
	for (int i = 0; i < q; ++i) {
		read(a[i]), read(b[i]), read(c[i]);
		if (!c[i]) {
			C -= D.merge(a[i], b[i]);
		}
	}
	bool flag = 0;
	for (int i = 0; i < q; ++i) {
		if (c[i]) {
			flag = 1;
			if (D.find(a[i]) == D.find(b[i])) {
				printStr("No");
				return 0;
