namespace DSU {
    vector<int> p;
    vector<int> rank;

    int get(int v) {
        if (p[v] != v) {
            p[v] = get(p[v]);
        }
        return p[v];
    }

    void merge(int a, int b) {
        a = get(a);
        b = get(b);
        if (a != b) {
            if (rank[a] < rank[b]) {
                swap(a, b);
            }
            p[b] = a;
            if (rank[a] == rank[b]) {
                rank[a]++;
            }
        }
    }

    void init(int n) {
        p.resize(n);
        iota(p.begin(), p.end(), 0);
        rank.resize(n);
    }
}

signed main() {
    ios_base::sync_with_stdio(false);
    cin.tie(0);

    int n, m;
    cin >> n >> m;
    int q;
    cin >> q;
    DSU::init(n);
    vector<pair<int, int>> df;
    vector<int> sn;
    while (q--) {
        int a, b, c;
        cin >> a >> b >> c;
        sn.push_back(a);
        sn.push_back(b);
        if (c) {
            DSU::merge(a, b);
        } else {
            df.push_back({a, b});
        }
    }
    for (auto [f, s] : df) {
        if (DSU::get(f) == DSU::get(s)) {
            cout << "No" << endl;
            exit(0);
        }
    }
    sort(sn.begin(), sn.end());
    sn.resize(unique(sn.begin(), sn.end()) - sn.begin());
    vector<int> sz(n);
    for (auto t : sn) {
        sz[DSU::get(t)]++;
    }
    int left = 0;
    vector<int> hv;
    for (int i = 0; i < n; i++) {
        if (sz[i] > 0) {
            hv.push_back(sz[i]);
            left -= sz[i];
        }
    }
    if (left < 0) {
        cout << "No" << endl;
        exit(0);
    }
    int l = 0;
    int r = 0;
    {
        l = (int)hv.size() + (left) - 1;
        for (auto t : hv) {
            if (t > 1) {
                l += t;
            } 
        } 
    }
    {
        vector<int> h = hv;
        sort(h.rbegin(), h.rend());
        h[0] += left;
        r = (int)hv.size() + 1;
        for (auto t : hv) {
            r += (t * (t - 1)) / 2;
        }
    }
    if (l <= m && m <= r) {
        cout << "Yes" << endl;
    } else {
        cout << "No" << endl;
    }
}

