    a = get(a);
    b = get(b);
    p[a] = b;
  }

  int get(int a) {
    if (a == p[a]) return a;
    return p[a] = get(p[a]);
  }

};


bool solve(int n, int m, int q) {
  vector<pair<int, int>> bs;
  dsu d(n);
  for (int i = 0; i <q ; i++) {
    int a, b, c;
    scanf("%d%d%d", &a, &b, &c);
    if (c == 0) {
      d.join(a, b);
    } else {
      bs.emplace_back(a, b);
    }
  }
  for (auto x : bs) {
    if (d.get(x.first) == d.get(x.second)) {
      return false;
    }
  }
  int comps = 0;
  for (int i = 0; i < n; i++) {
    if (d.get(i) == i) {
      comps++;
    }
  }
  if (comps < 3 && !bs.empty()) {
    return false;
  }

  ll min_edges = bs.empty() ? n - 1 : n;
  ll max_edges = (n - comps) + comps * 1LL * (comps - 1) / 2;
  return min_edges <= m && m <= max_edges;
}

int main() {
#ifdef LOCAL
  freopen("d.in", "r", stdin);
  freopen("d.out", "w", stdout);
#endif

  int n, m, q;
  while (scanf("%d%d%d", &n, &m, &q) == 3) {
    printf("%s\n", solve(n, m, q) ? "Yes" : "No");
  }


  return 0;
}

