class UnionFind {
	public:
	vector<int> data;
	UnionFind(int size) : data(size, -1) { }
	bool unionSet(int x, int y) {
		x = root(x); y = root(y);
		if (x != y) {
			if (data[y] < data[x]) swap(x, y);
			data[x] += data[y]; data[y] = x;
		}
		return x != y;
	}
	bool findSet(int x, int y) {
		return root(x) == root(y);
	}
	int root(int x) {
		return data[x] < 0 ? x : data[x] = root(data[x]);
	}
	int size(int x) {
		return -data[root(x)];
	}
};


class Solution {
public:
	void solve() {
		int n, m, q;
		cin >> n >> m >> q;
		UnionFind uf0(n), uf1(n), uf01(n);
		vector<pair<int, int>> c0, c1;
		vector<bool> f(n, true);
		for(int Q=0; Q < q; Q++){
			int a, b, c;
			cin >> a >> b >> c;
			if(c == 0){
				c0.push_back(make_pair(a, b));
				m--;
			}
			else c1.push_back(make_pair(a, b));
			f[a] = f[b] = false;
		}
		int sf = accumulate(f.begin(), f.end(), 0);
		for(auto t: c0){
			uf0.unionSet(t.first, t.second);
		}
		for(auto t: c1){
			if(uf0.findSet(t.first, t.second)){
				cout << "No" << endl;
				return;
			}
			uf1.unionSet(uf0.root(t.first), uf0.root(t.second));
		}
		for(int i=0; i < n; i++){
			if(uf1.data[i] == -2){
				sf--;
				m -= 2;
			}
		}
		if(sf < 0 || m < 0)cout << "No" << endl;
		else cout << "Yes" << endl;
		return;
	};
};

