	for (int i = 0; i < n; ++i) {
		p[i] = i, sz[i] = 1;
	}
	vector<pair<int, int>> vv;
	for (int i = 0; i < q; ++i) {
		int a, b, c;
		cin >> a >> b >> c;
		if (c == 0) {
			un(a, b);
		} else {
			vv.emplace_back(a, b);
		}
	}
	if (m == n - 1) {
		if (!vv.empty()) {
			no();
		} else {
			yes();
		}
	}

	for (auto p: vv) {
		if (get(p.first) == get(p.second)) {
			no();
		}
	}

	ll k = 0;
	for (int i = 0; i < n; ++i) {
		if (p[i] == i) {
			++k;
		}
	}

	ll l = n;
	ll r = n - k + k * (k - 1) / 2;
	if (m >= l && m <= r) {
		yes();
	} else {
		no();
	}

	return 0;
}

