        }
    }
    union_find uf;
    uf.init(n);
    REP(i,u1.size()){
        if (uf.same(u1[i], v1[i])){
            return false;
        }
        uf.merge(u1[i], v1[i]);
    }
    REP(i,u2.size()){
        if (uf.same(u2[i], v2[i])){
            return false;
        }
    }
    ll c = 0;
    REP(i,n) if (uf.find(i) == i) c++;
    m -= n - c;
    if (u2.empty()){
        return m >= c - 1 && m <= c * (c - 1) / 2;
    }else{
        return m >= c && m <= c * (c - 1) / 2 && c > 2;
    }
}

