const int MAXN = 100010;
int uf[MAXN], ufcnt[MAXN];
int find(int a) {
	if (uf[a] == a)
		return a;
	return uf[a] = find(uf[a]);
}
void uni(int a, int b) {
	int fa = find(a), fb = find(b);
	if (fa == fb)
		return ;
	if (ufcnt[fa] > ufcnt[fb])
		ufcnt[fa] += ufcnt[fb], uf[fb] = fa;
	else
		ufcnt[fb] += ufcnt[fa], uf[fa] = fb;
}

void clearuf(int n) {
	for (int i=0; i<n; i++)
		uf[i] = i, ufcnt[i] = 1;
}
int main() {
	int n, m, q;
	cin>>n>>m>>q;
	clearuf(n);
	unordered_set<int> used, visited;
	vector<pair<int, int>> multi;
	while(q--) {
		int a, b, c;
		cin>>a>>b>>c;
		if (c == 0)
			uni(a, b);
		else
			multi.push_back(make_pair(a, b));
		used.insert(a);
		used.insert(b);
	}

	for (int i=0; i<n; i++) {
		int fa = find(i);
		if (visited.find(fa) == visited.end())
			m -= ufcnt[fa]-1;
		visited.insert(fa);
	}

	for (auto it: multi) {
		int fa = find(it.first);
		int fb = find(it.second);
		if (fa == fb) {
			cout<<"No"<<endl;
			return 0;
		}
	}


	int availnode = n - used.size();
	clearuf(n);
	for (auto it: multi)
		uni(it.first, it.second);
	long long m_lower=0, m_upper = 0;
	int maxsize = 0;
	visited.clear();
	for (int i=0; i<n; i++) {
		int gid = find(i);
		if (ufcnt[gid]>1 && visited.find(gid) == visited.end()) {
			visited.insert(gid);
			maxsize = max(ufcnt[gid], maxsize);
			if (ufcnt[gid] < 3) {
				if (availnode == 0) {
					cout<<"No"<<endl;
					return 0;
				}
				ufcnt[gid]++; availnode--;
			}
			m_lower += (long long)ufcnt[gid];
			m_upper += (long long)ufcnt[gid]*(long long)(ufcnt[gid]-1)/2ll;
		}
	}

	m_lower -= (long long)maxsize;
	m_upper -= (long long)maxsize*(long long)(maxsize-1)/2ll;
	maxsize += availnode;
	m_lower += (long long)maxsize;
	m_upper += (long long)maxsize*(long long)(maxsize-1)/2ll;

	if (m_lower <= m && m <= m_upper)
		cout<<"Yes"<<endl;
	else
		cout<<"No"<<endl;
	return 0;
}

