        if (!connect(v.fi, v.se, 1)) {
            return cout << "No", 0;
        } else {
            on--;
            om--;
        }
    }
    for (int i = 0; i < n; i++) {
        if (cnt[i] > 0) {
            pq.push(cnt[i]);
        }
    }
    while (pq.size() > 1) {
        int u = pq.top(); pq.pop();
        int v = pq.top(); pq.pop();
        on--; om -= 2;
        if (u + v > 2) {
            pq.push(u + v - 2);
        }
    }
    if (!pq.empty()) {
        int u = pq.top();
        pq.pop();
        on -= u;
        om -= 2 * u;
    }
    if (on <= 0 || om < 0) {
        return cout << "No", 0;
    }
    on = n; om = m;
    fill(dsu, dsu + n, -1);
    for (pair<int, int> &v : tmp) {
        if (connect(v.fi, v.se)) {
            om--;
            on--;
        }
    }
    om -= 1LL * on * (on - 1) / 2;
    if (om > 0) {
        return cout << "No", 0;
    }
    cout << "Yes";
}

