    if(c == 0){
      q0.emplace_back(a, b);
    }else{
      q1.emplace_back(a, b);
    }
  }

  UnionFindTree uft(n);
  for(auto e: q0){
    uft.unite(e.first, e.second);
  }

  set<int> d;
  bool ok = true;
  for(auto e: q1){
    int a,b;
    tie(a,b) = e;
    if(uft.same(a,b)){
      ok = false;
    }
    d.insert(uft.find(a));
    d.insert(uft.find(b));
  }

  set<int> v;
  for(int i=0; i<n; i++){
    v.insert(uft.find(i));
  }

  long long s = v.size();

  if(q1.size() == 0){
    int base = (n-1)-(s-1);
