const string YES = "Yes";
const string NO = "No";

void No()
{
    cout << NO << endl;
    exit(0);
}
struct SizeAwareUnionFind
{
    vector<int> par, cou;
    SizeAwareUnionFind(int N) : par(N), cou(N) { REP(i, N) par[i] = i, cou[i] = 1; }
    int find(int x) { return (par[x] == x) ? x : (par[x] = find(par[x])); }
    void unite(int x, int y) {
        x = find(x), y = find(y); if (x == y) return;
        if (cou[x] < cou[y]) swap(x, y); 
        par[y] = x, cou[x] += cou[y];
    }
    int count(int x) { return cou[find(x)]; }
    bool same(int x, int y) { return find(x) == find(y); }
};

int main()
{
    int N, M, Q;
    cin >> N >> M >> Q;
    SizeAwareUnionFind uf(N + 1);
    vector<pint> E;
    REP(_, Q)
    {
        int a, b, c;
        cin >> a >> b >> c;
        if (c == 0)
        {
            uf.unite(a, b);
        }
        else
        {
            E.emplace_back(a, b);
        }
    }
    map<int, lint> g2s;
    REP(i, N) g2s[uf.find(i)] = uf.count(i);

    lint tree_edge = 0;
    for (auto p : g2s) tree_edge += p.second - 1;

    map<int, set<int>> soto;

    for (auto p : E)
    {
        if (uf.same(p.first, p.second))
        {
            No();
        }
        soto[uf.find(p.first)].insert(p.first);
        if (soto[uf.find(p.first)].size() > 1) No();
        soto[uf.find(p.second)].insert(p.second);
        if (soto[uf.find(p.second)].size() > 1) No();
    }

    lint req_o_edge = soto.size();

    lint n_tree = g2s.size();

    lint maxi_o_edge = n_tree * (n_tree - 1) / 2;
    if (req_o_edge + tree_edge <= M and M <= tree_edge + maxi_o_edge) cout << YES << endl;
    else No();
}

