        if(vis[v]) flag=false;
        m--;
        dfs(v,u);
    }
}
int main()
{
    scanf("%d%lld%d",&n,&m,&q);
    for(int i=1;i<=n;i++) f[i]=i;
    for(int i=1;i<=q;i++)
    {
        int u,v,c;scanf("%d%d%d",&u,&v,&c);
        u++;v++;
        vis[u]=vis[v]=true;
        if(u>v) swap(u,v);
        vc[c].push_back({u,v});
    }
    for(int i=1;i<=n;i++) if(!vis[i]) cnt++;
    memset(vis,false,sizeof(vis));
    for(int i=0;i<vc[1].size();i++)
        f[getf(vc[1][i].fi)]=getf(vc[1][i].se);
    sort(vc[0].begin(),vc[0].end());
    for(int i=0;i<vc[0].size();i++)
        if(getf(vc[0][i].fi)==getf(vc[0][i].se)||i&&vc[i]==vc[i-1])
    {
        printf("No\n");return 0;
    }
    for(int i=0;i<vc[0].size();i++)
    {
        int u=getf(vc[0][i].fi),v=getf(vc[0][i].se);
        add(u,v);add(v,u);
    }
    for(int i=1;i<=n;i++)
        if(f[i]==i&&!vis[i])
        dfs(i,0);
    if(!flag||m<0){printf("No\n");return 0;}
    for(int i=1;i<=n;i++)
        sum[getf(i)]++;
    for(int i=1;i<=n;i++)
        if(f[i]==i&&sum[i]>=2)
    {
        if(sum[i]==2) cnt--,sum[i]++;
        m-=sum[i];
        res+=(ll)sum[i]*(sum[i]+1)/2-sum[i];
    }
    if(m>=0&&m<=res&&cnt>=0) printf("Yes\n");
    else printf("No\n");
}

