  for(ll i:irange(0l,n)) {
    roots.insert(uf.root(i));
  }
  ll rts = roots.size();
  ll mxcnt = rts * (rts-1) / 2 + (n - rts);
  bool ok = m <= mxcnt;
  set<ll> loopnodes;
  for(auto t:vt) {
    ll a,b;
    tie(a,b) = t;
    if(uf.root(a) == uf.root(b)) {
