  for (int i = 0; i < n; i++) {
    root[i] = i;
  }

  vector<pair<int, int>> ones;
  for (int i = 0; i < q; i++) {
    int u, v, c;
    cin >> u >> v >> c;

    if (c == 0) {
      merge(u, v);
    } else {
      ones.push_back(make_pair(u, v));
    }
  }

  int compc = 0;
  for (int i = 0; i < n; i++) {
    if (root[i] == i) {
      compc++;
    }
  }

  if (compc <= 2) {
    if (m != n - 1 || !ones.empty()) {
      failure();
    } else {
      success();
    }
  }

  for (auto pr : ones) {
    int u = pr.first;
    int v = pr.second;

    if (find(u) == find(v)) {
      failure();
    }
  }

  if (m == n - 1) {
    failure();
  }

  ll maxe = (n - compc) + sq(compc);
  if (m > maxe) {
    failure();
  }

  success();
}

