    int N2 = N1 / 2;
    if ( M > N2 ) {
      abort();
    }
  }

  MFSet mfset(N);

  vector<pair<int, int>> multi_pair_list;
  bool has_single = false;
  for ( int i = 0; i < Q; ++ i ) {
    int a, b, c;
