void uni (ll a, ll b)
{
	ll ra = root (a);
	ll rb = root (b);
	if (ra == rb) { return; }
	if (sz[ra] > sz[rb]) { id[rb] = ra, sz[ra] += sz[rb]; }
	else { id[ra] = rb, sz[rb] += sz[ra]; }
}
