	while (n > 0) {
		if (n & 1) res = res * x % mod;
x = x * x % mod;
n >>= 1;
	}
	return res;
}
ll nCr(ll n, ll r) {
	return ((fact[n] * inv[r] % mod) * inv[n - r]) % mod;
}
ll nPr(ll n, ll r) {
	return (fact[n] * inv[n - r]) % mod;
}
ll nHr(ll n, ll r) {
	return nCr(r + n - 1, r);
}
Combination(ll n, ll _mod) {
	mod = _mod;
	fact.resize(n + 1);
