struct union_find{
	int n;
  vector<int> par,rank,size;

  // 頂点xの根を見たいときはuf.find(x)を使う
  union_find(int _n) : n(_n),par(_n),rank(_n),size(_n){init(n);}

  void init(int n){
    rep(i,n) par[i]=i,rank[i]=i,size[i]=1;
  }

  int GetRoot(int x){
    if(par[x] == x) return x;
    else return GetRoot(par[x]);
  }

  int GetSize(int x){
    return size[GetRoot(x)];
  }

  int getNumOfComponents(){
    int num=0;
    rep(i,n)if(GetRoot(i)==i)num++;
    return num;
  }

  void Unite(int x,int y){
    x = GetRoot(x);
    y = GetRoot(y);
    if(x == y) return;
    if(rank[x] < rank[y]){
      par[x] = y;
      size[y]+=size[x];
    }else{
      par[y] = x;
      size[x]+=size[y];
      if(rank[x] == rank[y]) rank[x]++;
    }
  }

  bool Same(int x,int y){
    return GetRoot(x) == GetRoot(y);
  }
};

int main()
{
