	}

	bool flag=false;
	union_find uf(n);
	rep(i,q){
		if(get<0>(query[i])==1)continue;
		int a=get<1>(query[i]), b = get<2>(query[i]);
		if(!uf.Same(a,b))uf.Unite(a,b),flag=true;
	}

	rep(i,q){
		if(get<0>(query[i])==0) continue;
		int a=get<1>(query[i]), b = get<2>(query[i]);
		if(uf.Same(a,b)){
			cout<<"No"<<endl;
			return 0;
		}
	}

	ll comp = uf.getNumOfComponents();

	ll large = comp*(comp-1)/2 + (n-comp);
	ll small = (flag?n:n-1);

	if(small<=m&&m<=large)cout<<"Yes"<<endl;
	else cout<<"No"<<endl;
	return 0;
}

