const int N = 1e5;
ll n,m,q;
int par[N + 5];
vector < pii > lst;
ll used[N + 5], sz[N + 5];
ll cnt[N + 5];

int find(int x){
	if(par[x] == x) return x;
	return par[x] = find(par[x]);
}

bool vis[N + 5], flag[N + 5];
map < int , bool > vis2[N + 5];

bool solve(){
	for(int i=0; i<lst.size(); i++){
		int u = lst[i].first;
		int v = lst[i].second;
		int pu = find(u);
		int pv = find(v);
		if(pu == pv) return false;
		if(!vis[u] && !flag[u]) vis[u] = true;
		if(!vis[v] && !flag[v]) vis[v] = true;
		if(!vis2[pu][pv]){
			vis2[pu][pv] = vis2[pv][pu] = true;
		}
		else return false;
	}
	bool fg = false;
	for(int i=0; i<n; i++){
		if(!flag[i] && !vis[i]){
			m -= (n-1);
			fg = true;
		}
		else if(flag[i] && find(i) == i){
			m -= sz[i] * (sz[i-1]) / 2 - used[i];
		}
	}
	for(int i=0; i<n; i++){
		if(sz[i] > 1 && !fg) return false;
	}
	return m <= 0;
}

