		cin >> u >> v >> w;
		if(w == 1){
			int pu = find(u);
			int pv = find(v);
			if(pu != pv){
				par[pu] = pv;	
				sz[pv] += sz[pu];
				used[pv] = used[pu] + 1;
				sz[pu] = used[pu] = 0;
			}
			cnt[u]--;
			cnt[v]--;
			flag[u] = flag[v] = true;
		}
		else{
			lst.push_back(make_pair(u,v));
			cnt[u]--;
			cnt[v]--;
		}
	}
	if(solve()) cout << "Yes" << endl;
	else cout << "No" << endl;
	return 0;
}

