    if(c == 1) { one.push_back({ a, b }); }
    else {
      uf.unite(a, b);
    }
  }

  set<i64> st;
  rep(i,0,N) st.insert(uf.root(i));

  i64 need = N - 1 - (st.size() - 1);

  i64 CNT = st.size();
  if(one.size() == 0) {
    if(need <= M && M <= N - 1 - (st.size() - 1) + (CNT - 1) * (CNT) / 2) {
      cout << "Yes" << endl;
    }
    else {
      cout << "No" << endl;
    }
    return 0;
  }
  union_find loop(N);
  for(auto p: one) {
    i64 x = uf.root(p.first);
    i64 y = uf.root(p.second);
    if(x == y) {
      cout << "No" << endl;
