int N, M, Q;
int A[202020], B[202020], C[202020];
int uf[202020];

int root(int p)
{
	return uf[p] < 0 ? p : (uf[p] = root(uf[p]));
}
void join(int p, int q)
{
	p = root(p);
	q = root(q);
	if (p == q) return;
	uf[p] += uf[q];
	uf[q] = p;
}
int main()
{
	scanf("%d%d%d", &N, &M, &Q);
	for (int i = 0; i < N; ++i) uf[i] = -1;
	int rem = M;
	for (int i = 0; i < Q; ++i) {
		scanf("%d%d%d", A + i, B + i, C + i);
		if (C[i] == 0) {
			join(A[i], B[i]);
			--rem;
		}
	}
	for (int i = 0; i < Q; ++i) {
		if (C[i] == 1 && root(A[i]) == root(B[i])) {
			puts("No");
			return 0;
		}
	}
	int n_root = 0;
	set<int> con;
	for (int i = 0; i < N; ++i) {
		if (root(i) == i) ++n_root;
	}
	for (int i = 0; i < Q; ++i) {
		if (C[i] == 0) continue;
		int u = root(A[i]), v = root(B[i]);
		if (u > v) swap(u, v);
		con.insert(u);
		con.insert(v);
	}
	if (con.size() == 2 && n_root == 2) {
		puts("No");
		return 0;
	}
	//printf("%d %d %d\n", con.size(), n_root, rem);
	i64 req;
	if (con.size() == 2) req = 3;
	else req = con.size();

	i64 rmax = (i64)n_root * (n_root - 1) / 2;

	if (req <= rem && rem <= rmax) puts("Yes");
	else puts("No");
	return 0;
}

