#include<bits/stdc++.h>
using namespace std;
typedef long long ll;



class UnionFind{
    public:
    //親の番号を格納する。親だった場合は-(その集合のサイズ)
    vector<ll> parent;

    //-1で初期化。最初はすべてバラバラ
    UnionFind(ll N){
        parent = vector<ll>(N,-1);
    }

    //Aがどのグループに属しているか(Aの根)を調べる
    ll root(ll A){
        if(parent[A] < 0) return A;
        return parent[A]=root(parent[A]);
    }

    //自分のいるグループの頂点数を調べる
    ll size(ll A){
        return -parent[root(A)];
    }

    //AとBをくっつける
    bool unite(ll A, ll B) {
    //AとBを直接つなぐのではなく、root(A)にroot(B)をくっつける
        A = root(A);
        B = root(B);
        //既にくっついているからくっつけない
        if(A == B) return false; 

        //大きいほう(A)に小さいほう(B)をくっつける
        //大小が逆ならひっくり返す
        if(size(A) < size(B)) swap(A,B);

        //Aのサイズを更新する
        parent[A] += parent[B];
        //Bの親をAに変更する
        parent[B] = A;

        return true;
    }

    //AとBが同じグループならtrueを返す
    bool same(ll A, ll B){
        return root(A)==root(B);
    } 
};

signed main(){
    ios::sync_with_stdio(false);
    cin.tie(0);
    cout << fixed << setprecision(20);

    ll n,m,q;
    cin>>n>>m>>q;
