class dsu {
public:
   vector<int> p;
   vector<int> sz;
   int n , cc;

   dsu(int _n) : n(_n) , cc(_n) {
      p.resize(n);
      sz.resize(n);
      fill(sz.begin() , sz.end() , 1);
      iota(p.begin(), p.end(), 0);
   }

   inline int get(int u) {
      return (u == p[u] ? u : (p[u] = get(p[u])));
   }

   inline bool unite(int u, int v) {
      u = get(u);
      v = get(v);

      if(u == v)return false;

      if(sz[v] < sz[u])swap(u , v);
      p[u] = v;
      sz[v] += sz[u];
      cc--;
      return true;
   }
};


