class UF {
  vector<int> v;
public:
  UF(int n) : v(n) {
    for (int i = 0; i < n; ++i) {
      v[i] = i;
    }
  }

  int root(int i) {
    if (v[i] == i) return i;
    return v[i] = root(v[i]);
  }

  bool same(int i, int j) {
    return root(i) == root(j);
  }

  void unite(int i, int j) {
    int ri = root(i);
    int rj = root(j);
    if (ri == rj) return;
    v[ri] = rj;
  }
};

int n, q;
