bool sub() {
  bool has_mult = false;
  for (int k = 0; k < q; ++k) {
    if (c[k] == 1) {
      has_mult = true;
    }
  }

  UF uniq(n);
  UF mult(n);
  for (int k = 0; k < q; ++k) {
    if (c[k] == 0) {
      if (mult.same(a[k], b[k])) return false;
      uniq.unite(a[k], b[k]);
    } else {
      if (uniq.same(a[k], b[k])) return false;
      mult.unite(a[k], b[k]);
    }
  }

  set<int> rs;
  for (int i = 0; i < n; ++i) {
    rs.insert(uniq.root(i));
  }

  if (has_mult && rs.size() < 3) return true;

  set<int> qs;
  for (int k = 0; k < q; ++k) {
    if (c[k] == 1) {
      qs.insert(uniq.root(a[k]));
      qs.insert(uniq.root(b[k]));
    }
  }

  long mn = has_mult ? n : n - 1;
  long mx = n - rs.size() + (long)rs.size() * (rs.size() - 1) / 2;
  return m >= mn && m <= mx;
}

