class U {
	private:
		vi p,rk;
		int n,nc;
	public:
		U(int _n) {
			n = _n;
			nc = n;
			rk.assign(n,0);
			for(int i=0;i<n;i++) {
				p.push_back(i);
			}
		}
		int find(int a) {
			if(a == p[a]) return a;
			return p[a] = find(p[a]);
		}
		bool same(int a, int b) {
			return find(a) == find(b);
		}
		bool un(int a, int b) {
			if(same(a,b)) return false;
			nc--;
			int x = find(a),y = find(b);
			if(rk[x] > rk[y]) {
				p[y] = x;
				return true;
			}
			if(rk[x] == rk[y]) {rk[y]++;}
			p[x] = y;
			return true;
		}
		int con() {
			return nc;
		}
};
int main() {
	ios::sync_with_stdio(0);
	bool rec = false;
	ll n,m,q;
	cin >> n >> m >> q;
