	for(int i=0;i<q;i++) {
		int a,b,c;
		cin >> a >> b >> c;
		if(c) {
			rec = true;
			co.un(a,b+n);
			co.un(b,a+n);
		} else {
			co.un(a,b);
			co.un(a+n,b+n);
			br.un(a,b);
		}
	}
	bool po = true;
	for(int i=0;i<n;i++) {
		if(co.same(i,n+i)) {po = false;break;}
	}
	ll sz = br.con();
	//cout << sz << '\n';
	ll ma,mb;
	if(rec) {mb = n;} else {mb = n-1;}
	ma = n-sz+(sz*(sz-1)/2);
	//cout << ma << " " << mb << '\n';
	if(rec && (sz <= 2)) {
		po = false;
	}
	if(!(m <= ma && m >= mb)) {
		po = false;
	}
	cout << (po?"Yes":"No") << '\n';
}

