struct UF{
    vi dat;
    UF(int n){
        dat.assign(n,-1);
    }
    int root(int x){
        return dat[x]<0?x:dat[x]=root(dat[x]);
    }
    void unite(int a, int b){
        a=root(a);b=root(b);
        if(a==b)return;
        if(dat[a]>dat[b])swap(a,b);
        dat[a] += dat[b];
        dat[b] = a;
    }
    bool same(int a, int b){
        return root(a)==root(b);
    }
    ll size(int a){
        return -dat[root(a)];
    }
};

int n;
ll m;
int q;

int main(){
    auto fail = [&](){puts("No");exit(0);};

    scanf("%d%lld%d",&n,&m,&q);
    UF suf(n), sduf(n), duf(n);
    while(q--){
        int a,b,c;
        scanf("%d%d%d",&a,&b,&c);
        if(c==0){
            // single
            if(!suf.same(a,b) && sduf.same(a,b)){
                fail();
            }
            suf.unite(a,b);
            sduf.unite(a,b);
        }else{
            // double
            if(suf.same(a,b)){
                fail();
            }
            duf.unite(a,b);
            sduf.unite(a,b);
        }
    }

    ll low = 0, high = 0;
    REP(i,n){
        if(suf.root(i)==i){
            low += suf.size(i)-1;
            high += suf.size(i)-1;
        }
    }

    int sdufnum = 0;
    REP(i,n)if(sduf.root(i)==i)sdufnum++;
    if(sdufnum==1){
        REP(i,n)if(duf.root(i)==i){
            ll sz = duf.size(i);
            if(sz==2){
                fail();
            }
            low += sz;
            high += sz*(sz-1)/2;
        }
    }else{
        ll whinion = 0;
        vi dufs(n,-1);
        REP(i,n){
            if(duf.root(i)==i && duf.size(i)>=2){
                int par = sduf.root(i);
                CHMAX(dufs[par], (int)duf.size(i));
                low += duf.size(i);
                high += duf.size(i) * (duf.size(i)-1) / 2;
            }
        }
        REP(i,n)if(sduf.root(i)==i){
            ll sz = dufs[i]==-1 ? 1 : dufs[i];
            high += sz * whinion;
            whinion += sz;
        }
    }
    DEBUG(low); DEBUG(high);
    if(m < low || high < m)fail();
    puts("Yes");
    return 0;
}

