using namespace std;

template <class T>
class UnionFind
{
public:
	struct Elem {
		int i;
		int num; // root 以外は無効
		T   val;
	};

	UnionFind(int min, int max)
		: elems_(max - min + 1)
		, min_(min)
		, rank_(max - min + 1)
	{
		for (int i = min; i <= max; i++) {
			Elem& elem = this->elems_[i - min];
			elem.i = i;
			elem.num = 1;
		}
	}

	Elem& find(int i) {
		vector<int> res;

		Elem& ans = this->elems_[0];

		while (true) {
			int idx = i - this->min_;
			if (this->elems_[idx].i == i) {
				ans = this->elems_[idx];
				break;
			}

			res.push_back(idx);
			i = this->elems_[idx].i;
		}

		// 簡略化
		for (int r : res) {
			this->elems_[r].i = i;
		}

		return ans;
	}

	int size(int i) {
		Elem& root = this->find(i);
		int idx = root.i - this->min_;
		return this->elems_[idx].num;
	}

	int rank() {
		return rank_;
	}

	void merge(int i, int j) {
		Elem& i_root = this->find(i);
		Elem& j_root = this->find(j);
		if (i_root.i == j_root.i) return;

		int i_idx = i_root.i - this->min_;
		int j_idx = j_root.i - this->min_;

		int i_size = this->elems_[i_idx].num;
		int j_size = this->elems_[j_idx].num;

		if (i_size < j_size) {
			this->elems_[i_idx].i = j_root.i;
			this->elems_[j_idx].num += this->elems_[i_idx].num;
		}
		else {
			this->elems_[j_idx].i = i_root.i;
			this->elems_[i_idx].num += this->elems_[j_idx].num;
		}
		this->rank_--;
	}

private:
	vector<Elem> elems_;
	int          min_;
	int          rank_;
};


