class UnionFind {
	vector<int> data;
	public:
	int independentSet;
	UnionFind(int size) : data(size, -1), independentSet(size) { }
	bool unionSet(int x, int y) {
		x = root(x); y = root(y);
		if (x != y) {
			if (data[y] < data[x]) swap(x, y);
			data[x] += data[y]; data[y] = x;
			independentSet--;
		}
		return x != y;
	}
	bool findSet(int x, int y) {
		return root(x) == root(y);
	}
	int root(int x) {
		return data[x] < 0 ? x : data[x] = root(data[x]);
	}
	int size(int x) {
		return -data[root(x)];
	}
};

class Solution {
public:
	void solve() {
		int n, m, q;
		cin >> n >> m >> q;
		UnionFind uf0(n), uf1(n), uf01(n);
