namespace tree {

struct UnionFind {
    vec<ll> rank, par;
    vec<ssize_t> sz;

    UnionFind(ll n) : rank(n, 1), par(n), sz(n, 1) {
        iota(ALL(par), 0);
    }

    ll find(ll n) {
        return (n == par[n] ? n : par[n] = find(par[n]));
    }

    bool unit(ll x, ll y) {
        ll px = find(x), py = find(y);
        if (px == py) return false;
        if (rank[px] < rank[py]) std::swap(px, py);
        par[py] = px;
        rank[px] += (rank[px] == rank[py]);
        sz[px] += sz[py];
        return true;
    }

    bool same(ll x, ll y) {
        return find(x) == find(y);
    }

    ssize_t size(ll n) {
        return sz[find(n)];
    }
};

}

bool solve() {
    ll n, m, q;
    std::cin >> n >> m >> q;
    tree::UnionFind uf(n);
    vec<pll> q1, q2;
    while (q--) {
        ll a, b, c;
        std::cin >> a >> b >> c;
        (c == 0 ? q1 : q2).emplace_back(a, b);
    }

    ll cnt = 0;
    for (auto &&e : q1) {
        ll a, b;
        std::tie(a, b) = e;
        cnt += uf.unit(a, b);
    }

    for (auto &&e : q2) {
        ll a, b;
        std::tie(a, b) = e;
        if (uf.same(a, b)) return false;
    }

    std::set<ll> pars;
    for (ll i = 0; i < n; i++) if (uf.find(i) == i) pars.insert(i);
    ll minv = pars.size();
    ll maxv = minv * (minv - 1) / 2;
    ll rest = m - cnt;
    return minv <= rest && rest <= maxv;
}

