struct UnionFind {
  vector< int > data;

  UnionFind(int sz) {
    data.assign(sz, -1);
  }

  bool unite(int x, int y) {
    x = find(x), y = find(y);
    if(x == y) return (false);
    if(data[x] > data[y]) swap(x, y);
    data[x] += data[y];
    data[y] = x;
    return (true);
  }

  int find(int k) {
    if(data[k] < 0) return (k);
    return (data[k] = find(data[k]));
  }

  int size(int k) {
    return (-data[find(k)]);
  }
};


int main() {
  int64 N, M, Q;
  cin >> N >> M >> Q;
  UnionFind uf(N);
  vector< int > A(Q), B(Q), C(Q);
  for(int i = 0; i < Q; i++) {
    cin >> A[i] >> B[i] >> C[i];
  }

  int used = 0;
  for(int i = 0; i < Q; i++) {
    if(C[i] == 0) if(uf.unite(A[i], B[i])) ++used;
  }


  auto Yes = []() {
    cout << "Yes" << endl;
    exit(0);
  };
  auto No = []() {
    cout << "No" << endl;
    exit(0);
  };

  for(int i = 0; i < Q; i++) {
    if(C[i] == 1) {
      if(uf.find(A[i]) == uf.find(B[i])) No();
    }
  }

  vector< int > rot;
  for(int i = 0; i < N; i++) {
    if(uf.find(i) == i) rot.emplace_back(i);
  }


  if(rot.size() == 1) {
    if(used == M) Yes();
    else No();
  } else if(rot.size() == 2) {

    for(int i = 0; i < Q; i++) {
      if(C[i] == 1) No();
    }
    ++used;
    if(used == M) Yes();
    else No();
  } else {
    int64 low = used, high = used;

    bool exist = false;
    for(int i = 0; i < Q; i++) {
      if(C[i] == 1) exist = true;
    }

    int64 v = rot.size();
    high += v * (v - 1) / 2;
    low += rot.size() - 1;
    low += exist;

    if(low <= M && M <= high) Yes();
    else No();
  }
}

