int rt[100001];

int findrt(int x){
    if (x == rt[x])
        return x;
    return rt[x] = findrt(rt[x]);
}

int main(){
    ios::sync_with_stdio(0);
    cin.tie(0);

    int n, m, q;

    cin >> n >> m >> q;

    int cnt[100001];
    for (int i = 0; i < n; i++){
        cnt[i] = 1;
        rt[i] = i;
    }

    vector<pair<int, int>> sp;

    bool ok = true;
    int a, b, c;
    for (int i = 0; i < q; i++){
        cin >> a >> b >> c;
        if (c == 0){
            if (findrt(a) != findrt(b)){
                int x = findrt(a);
                int y = findrt(b);
                rt[max(x, y)] = min(x, y);
                cnt[min(x, y)] += cnt[max(x, y)];
                rt[a] = min(x, y);
                rt[b] = min(x, y);
            }
        }
        else {
            sp.push_back({a, b});
        }
    }

    bool done[200001] = {0};
    int dk = 0;
    for (int i = 0; ok && i < n; i++)
        if (rt[i] == i && cnt[i] == 1)
            dk++;

    if (sp.size() == 0 && cnt[0] != n && m != n - 1)
        ok = false;


    for (int i = 0; ok && i < sp.size(); i++){
        int x = findrt(sp[i].first);
        int y = findrt(sp[i].second);

        if (x == y)
            ok = false;
        else if (dk < 1){
            ok = false;
        }

        done[x] = true;
        done[y] = true;
    }

    ok ? cout << "Yes\n" : cout << "No\n";

    return 0;
}

