int par[100005];
vector<pair<int, int>> v;

int find(int a) {
	return par[a] == a ? a : par[a] = find(par[a]);
}

int main() {
	scanf("%d%lld%d", &n, &m, &q);
	for (int i = 0; i < n; i++)
		par[i] = i;
	while (q--) {
		int ta, tb, tc;
		scanf("%d%d%d", &ta, &tb, &tc);
		if (tc)
			v.emplace_back(ta, tb);
		else {
			ta = find(ta);
			tb = find(tb);
			if (ta != tb)
				par[ta] = tb;
		}
	}
	int cnt = 0;
	for (int i = 0; i < n; i++)
		if (find(i) == i)
			cnt++;
	if (cnt <= 2 && !v.empty()) {
		puts("No");
		return 0;
	}
	for (auto& i : v)
		if (par[i.first] == par[i.second]) {
			puts("No");
			return 0;
		}
	long long mi = v.empty() ? n - 1 : n;
	long long ma = (n - 1) - (cnt - 1) + (long long)cnt * (cnt - 1) / 2;
	puts(mi <= m && m <= ma ? "Yes" : "No");
}

