vector<ll> fac;
void c_fac(int x=pow(10,6)+10) { fac.resize(x,true); rep(i,x) fac[i] = i ? (fac[i-1]*i)%MOD : 1; }
ll inv(ll a, ll m=MOD) { ll b = m, x = 1, y = 0; while (b!=0) { int d = a/b; a -= b*d; swap(a,b); x -= y*d; swap(x,y); } return (x+m)%m; }
ll nck(ll n, ll k) { return fac[n]*inv(fac[k]*fac[n-k]%MOD)%MOD; }
ll gcd(ll a, ll b) { if (a<b) swap(a,b); return b==0 ? a : gcd(b, a%b); }
ll lcm(ll a, ll b) { return a/gcd(a,b)*b; }

struct UnionFind {
  vector<int> par, s; 
  UnionFind(int N) : par(N), s(N) { rep(i,N) { par[i] = i; s[i] = 1; } }
  int root(int x) { return par[x]==x ? x : par[x] = root(par[x]); }
  int size(int x) { return par[x]==x ? s[x] : s[x] = size(root(x)); }
  void unite(int x, int y) { int rx=root(x), ry=root(y); if (rx!=ry) { s[rx] += s[ry]; par[ry] = rx; } }
  bool same(int x, int y) {  int rx=root(x), ry=root(y); return rx==ry; }
};

int main() {
  ll N, M, Q; cin >> N >> M >> Q;
  UnionFind uf(N);
  rep(i,Q) {
    int A, B, C; cin >> A >> B >> C;
    if (C==0) uf.unite(A,B);
  }
  map<int, int> tr; rep(i,N) tr[uf.root(i)]++;
  ll ts = tr.size();
  // cout << ts << endl;

  string result;
  if (ts==1) result = M==N-1 ? "Yes" : "No";
  else if (ts==2) result = "No";
  else result = (M>=N&&M<=N+ts*(ts+1)/2) ? "Yes" : "No";
  cout << result << endl;
  return 0;
}

