const ll mod = 1e9 + 7;

ll modexp(ll x, ll ex) {
    ll ans = 1ll;
    while (ex > 0) {
        if (ex & 1ll) ans = (ans * x) % mod;
        ex >>= 1ll;
        x = (x * x) % mod;
    }
    return ans;
}

const int maxn = 1e5 + 7;

const ll inf = 1e9 + 7;

int ranki[maxn];
int parent[maxn];
vector<pair<ll,ll>> ones;

int find_dsu(ll x)
{
    if(parent[x]==-1)
        return x;
    ll par = parent[x];
    parent[x] = find_dsu(par);
    return parent[x];
}

int merge_dsu(ll x, ll y)
{
    x = find_dsu(x);
    y = find_dsu(y);

    if(x==y)
        return 0;
    if(ranki[x]>ranki[y])
    {
        parent[y] = x;
        ranki[x] += ranki[y];
    }
    else
    {
        parent[x] = y;
        ranki[y] += ranki[x];
    }
    return 1;
}


