    for (int i = 0; i < q; ++i) {
        int a, b, c; cin >> a >> b >> c; 
        kek.insert(mp(mp(a, b), c)); 
    }
    for (auto v : kek) {
        e.pb({v.ff.ff, v.ff.ss, v.ss}); 
    }
    for (auto v : e) {
        if (v.c == 0) {
            int t = unite(v.a, v.b); 
            ctr -= t; 
        }
    } 
    set<pii> ms; 
    int ptr = 0; 
    for (auto v : e) {
        if (v.c == 1) {
            ptr++; 
            int a = get(v.a); 
            int b = get(v.b); 
            if (a == b) {
                cout << "No" ; 
                return;             
            }
            if (a > b) swap(a, b); 
            ms.insert(mp(a, b)); 
