            u1.push_back(u);
            v1.push_back(v);
        }else{
            u2.push_back(u);
            v2.push_back(v);
        }
    }
    union_find uf;
    uf.init(n);
    REP(i,u1.size()){
        if (uf.same(u1[i], v1[i])){
            return false;
        }
        uf.merge(u1[i], v1[i]);
    }
    REP(i,u2.size()){
