vector<pii> edges[2];
bool Union(int x, int y) {
	x = find(x), y = find(y);
	if(x == y) return 0;
	if(sz[x] < sz[y]) swap(x, y);
	p[y] = x, sz[x] += sz[y];
	return 1;
}
int main() {
	scanf("%d%lld%d", &n, &m, &q);
