}
const int maxn=1e5+10;
const int maxq=1e5+10;
int n,m,q,one,c;
namespace uns {
    int f[maxn];
    void init() {
        for (int i=1;i<=n;++i) f[i]=i;
    }
    int find(int x) {
        return f[x]==x?x:(f[x]=find(f[x]));
    }
    bool same(int x,int y) {
        x=find(x),y=find(y);
        return x==y;
    }
    void merge(int x,int y) {
        x=find(x),y=find(y);
        f[x]=y;
    }
}
struct query {
    int a,b,c;
    inline bool operator < (const query &q) const {
        return c<q.c;
    }
    void input() {
        a=read(),b=read(),c=read();
    }
} req[maxq];
void No() {
    puts("No");
    exit(0);
}
int main() {
    n=read(),m=read(),q=read(),c=n;
    uns::init();
    for (int i=1;i<=q;++i) req[i].input();
    sort(req+1,req+q+1);
    for (one=1;one<=q && req[one].c==0;++one);
    for (int i=1;i<one;++i) {
        int x=req[i].a,y=req[i].b;
        if (uns::same(x,y)) continue;
        --c,uns::merge(x,y);
    }
    bool valid=false;
    for (int i=one;i<=q;++i) {
        int x=req[i].a,y=req[i].b;
        if (uns::same(x,y)) No();
        valid=true;
    }
    long long mx=(long long)c*(c-1)/2-c+n;
    if (m>mx) No();
    if (valid && m<n) No();
    if (!valid && m<n-1) No();
    puts("Yes");
    return 0;
}

