#include <bits/stdc++.h>
#define fi first
#define se second
using namespace std;

const int N = 1E5 + 5;

int n, on, u, v, t, q, dsu[N], cnt[N];
long long m, om;
vector<pair<int, int>> ve, tmp;

int trace(int u) {
    return dsu[u] < 0 ? u : dsu[u] = trace(dsu[u]);
}

bool connect(int u, int v, int val = 0) {
    if ((u = trace(u)) == (v = trace(v))) {
        return false;
    }
    if (dsu[u] > dsu[v]) {
        swap(u, v);
    }
    dsu[u] += dsu[v];
    cnt[u] += cnt[v] + val;
    dsu[v] = u;
    return true;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);
    cin >> n >> m >> q;
    om = m; on = n;
    fill(dsu, dsu + n, -1);
    while (q--) {
        cin >> u >> v >> t;
        if (t == 0) {
            if (connect(u, v, 0)) {
                n--;
                m--;
                tmp.push_back({u, v});
            }
        } else {
            ve.push_back({u, v});
        }
    }
    for (pair<int, int> &v : ve) {
        if (!connect(v.fi, v.se, 1)) {
            return cout << "No", 0;
        } else {
            n--;
            m--;
        }
    }
    int sum = 0, cur = 0;
    for (int i = 1; i <= on; i++) {
        if (dsu[i] < 0 && cnt[i] > 0) {
            sum += cnt[i];
            cur++;
        }
    }
    if (cur >= 0) {
        m -= 2 * (cur - 1);
        n -= cur - 1;
        sum -= (cur == 1 ? 0 : cur);
        m -= 2 * sum;
        n -= sum;
    }
    if (m < 0 || n <= 0) {
        return cout << "No", 0;
    }
    fill(dsu, dsu + on, -1);
    for (pair<int, int> &v : tmp) {
        if (connect(v.fi, v.se)) {
            om--;
            on--;
        }
    }
    om -= 1LL * on * (on - 1) / 2;
    if (om > 0) {
        return cout << "No", 0;
    }
    cout << "Yes";
}

