    edge(int U,int V) {u=U,v=V;}
};
vector<edge>G;
int Find(int u) {
    if(u==fa[u])
        return u;
    return fa[u]=Find(fa[u]);
}
void Union(int u,int v) {
    int fu=fa[u],fv=fa[v];
    if(fu!=fv)
        fa[fu]=fv;
    return;
}
