using namespace std;

typedef long long ll;
ll N, M;
ll Q;
vector<pair<ll, ll>> Black;

const ll MAX_N = 100000;
ll Parent[MAX_N], Rank[MAX_N], NGroups;
void init() {
  fill(Parent, Parent + N, -1);
  fill(Rank, Rank + N, 1);
  NGroups = N;
}
ll root(ll x) {
  if (Parent[x] == -1) return x;
  return Parent[x] = root(Parent[x]);
}
void unite(ll x, ll y) {
  x = root(x);
  y = root(y);
  if (x == y) return;
  --NGroups;
  if (Rank[x] > Rank[y]) {
    Parent[y] = x;
  } else {
    Parent[x] = y;
    if (Rank[x] == Rank[y]) {
      ++Rank[y];
    }
  }
}
bool same(ll x, ll y) { return root(x) == root(y); }

bool solve() {
  for (ll i = 0; i < Q; ++i) {
    ll a, b, c;
    cin >> a >> b >> c;
    if (c == 0) {
      unite(a, b);
    } else {
      Black.push_back(make_pair(a, b));
    }
  }
  for (auto pair : Black) {
    if (M == N - 1) return false;
    if (same(pair.first, pair.second)) return false;
  }
  return M - N <= NGroups * (NGroups - 3) / 2;
}
int main() {
  cin >> N >> M >> Q;
  init();
  cout << (solve() ? "Yes" : "No") << endl;
  return 0;
}

