  int flg = 0;
  rep(i,Q){
    if(c[i]==0) continue;
    if(uf.same(a[i],b[i])) die("No");
    flg = 1;
  } 
  if(flg == 1){
    if(uf.cnt == 2 || M == N-1) die("No");
  }
  int maxedge = N - uf.cnt + (ll)uf.cnt * ((ll)uf.cnt - 1) / 2;
  out(maxedge >= M ? "Yes" : "No");
}

