vector<pair<int, int>> ve, tmp;

int trace(int u) {
    return dsu[u] < 0 ? u : dsu[u] = trace(dsu[u]);
}

bool connect(int u, int v) {
    if ((u = trace(u)) == (v = trace(v))) {
        return false;
    }
    if (dsu[u] > dsu[v]) {
        swap(u, v);
    }
    dsu[u] += dsu[v];
    dsu[v] = u;
    return true;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);
    cin >> n >> m >> q;
    om = m; on = n;
    fill(dsu, dsu + n, -1);
    while (q--) {
        cin >> u >> v >> t;
        if (t == 0) {
            if (connect(u, v)) {
                n--;
                m--;
                tmp.push_back({u, v});
            }
        } else {
            ve.push_back({u, v});
        }
    }
    for (pair<int, int> &v : ve) {
        if (!connect(v.fi, v.se)) {
            return cout << "No", 0;
        } else {
            n -= 2;
            m -= 3;
        }
    }
    if (m < 0 || n <= 0) {
        return cout << "No", 0;
    }
    fill(dsu, dsu + on, -1);
    for (pair<int, int> &v : tmp) {
        if (connect(v.fi, v.se)) {
            om--;
            on--;
        }
    }
    om -= 1LL * on * (on - 1) / 2;
    if (om > 0) {
        return cout << "No", 0;
    }
    cout << "Yes";
}

