    }
    dsu1.combine(p.first, p.second);
  }

  int cnt1 = dsu1.count(n);

  if (cnt1 == 2) return 0 * printf("No\n");

  if (e[1].size() > 0 && m == n-1) return 0 * printf("No\n");

  int cnt0 = dsu0.count(n);
  if (m > (1LL * cnt0 * cnt0 - 1) / 2 + n - cnt0) return 0 * printf("No\n");

  printf("Yes\n");
  return 0;
}

