#include <iostream>
#include <vector>
using namespace std;
using ll = long long;

class DSU {
	private:
		vector<int> comp, siz;
	public:
		DSU(int n) : comp(n), siz(n, 1) {
			for (int i = 0; i < n; ++i) comp[i] = i;
		}
		int get(int i) {
			if (comp[i] != i) comp[i] = get(comp[i]);
			return comp[i];
		}
		bool join(int a, int b) {
			a = get(a);
			b = get(b);
			if (a == b) return false;

			if (siz[a] < siz[b]) swap(a, b);
			siz[a] += siz[b];
			comp[b] = a;
			return true;
		}
		int compSize(int i) { return siz[get(i)]; }
};

bool solve() {
	int n, q;
	ll m;
	cin >> n >> m >> q;

	int cc = n; // component count
	DSU dsu(n);
	vector<pair<int, int>> bans;
	for (int i = 0; i < q; ++i) {
		int a, b, c;
		cin >> a >> b >> c;
		if (c == 0) cc -= dsu.join(a, b);
		else bans.emplace_back(a, b);
	}
	for (auto pr : bans) {
		if (dsu.get(pr.first) == dsu.get(pr.second)) return false;
	}
	ll low = n-cc + cc;
	ll high = n-cc + (ll)cc * (cc - 1) / 2;
	if (cc == 1 || bans.empty()) --low;
	return (low <= m && m <= high);
}

int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(0);

	bool res = solve();
	cout << (res ? "Yes" : "No") << '\n';
}

