  }

  if (msz == 2 && cand.size() == 1) {
    if (unused.empty())ok = false;
    else {
      int p = unused.front(); unused.pop();
      uf.unite(p, root);
      tmin++;
      tmax++;
      cand.clear();
    }
  }
  REP(i, cand.size()) {
    if (uf.root(cand[i]) == uf.root(root))continue;
    uf.unite(cand[i], root);
    tmin += 2;
    tmax += 2 * msz;
    msz += 2;
  }
  map<int, ll> cnt2;
  REP(i, n)cnt2[uf.root(i)]++;
  int nn = cnt2.size();
  map<int, int> mp, rmp;
  vi sz(nn);
  {
