      mp[a.first] = i;
      rmp[i] = a.first;
      sz[i] = a.second;
      i++;
    }

  }
  UnionFind uf2(nn);


  REP(i, a.size()) {
    int uu = mp[uf.root(a[i].first)], vv = mp[uf.root(a[i].second)];
    if (uf2.same(uu, vv))ok = false;
    uf2.unite(uu, vv);
    tmin++;
