  map<int, ll> cnt3;
  REP(i, nn) cnt3[uf2.root(i)]++;
  for (auto &&a : cnt3) {
    if (a.second == 1) {
      tmin++;
      tmax += msz * sz[a.first];
      msz += sz[a.first];
    }
  }
  if (tmin < m || m > tmax)
    ok = false;
  cout << (ok ? "Yes" : "No") << endl;
}

