{
  cout << "No" << endl;
  exit(0);
}

int main()
{
  ios_base::sync_with_stdio(0);
  cin.tie(0);

  int n, q;
  long long m;
  cin >> n >> m >> q;
  for (int i = 0; i < n; i++)
    ds[i] = i;
  vector<pair<int, int>> queries;
  set<pair<int, int>> cache[2];
  while (q--)
  {
    int x, y, c;
    cin >> x >> y >> c;
    if (x > y)
      swap(x, y);
    if (cache[c].count({x, y}))
      continue;
    cache[c].insert({x, y});
    if (c) queries.push_back({x, y});
    else
    {
      int dx = get(x, ds), dy = get(y, ds);
      if (dx != dy)
      {
        ds[dx] = dy;
        m--;
      }
    }
  }

  int dsCnt = 0;
  memset(ds2, -1, sizeof ds2);
  vector<int> b;
  for (int i = 0; i < n; i++)
    if (get(i, ds) == i)
    {
      dsCnt++;
      ds2[i] = i;
      b.push_back(i);
    }

  set<pair<int, int>> refinedQueries;
  for (auto u : queries)
  {
    int x = get(u.first, ds), y = get(u.second, ds);
    if (x == y)
      noAnswer();
    if (x > y)
      swap(x, y);
    refinedQueries.insert({x, y});
  }


  for (auto u : refinedQueries)
  {
    int x = u.first, y = u.second;
    int dx = get(x, ds2), dy = get(y, ds2);

    int found = 0;
    for (int z : b)
      if (z != x && z != y)
      {
        int dz = get(z, ds2);
        ds2[dx] = ds2[dy] = dz;
        found = 1;
        break;
      }
    if (!found)
      noAnswer();
  }

  vector<int> cnt(n, 0);
  for (int x : b)
    cnt[get(x, ds2)]++;

  int need = 0;
  for (int i = 0; i < n; i++)
    if (cnt[i] > 1)
      need += cnt[i];
  if (need > m)
    noAnswer();

  cout << "Yes" << endl;
}

