struct UnionFindTree {
    vector<int> par;
    vector<int> rank;
    vector<int> siz;
    int cnt;

    void init(int n) {
        cnt = n;
        par.resize(n);
        rank.resize(n);
        siz.resize(n);
        for (int i = 0; i < n; i++) {
            par[i] = i;
            rank[i] = 0;
            siz[i] = 1;
        }
    }
    int find(int x) {
        if (par[x] == x) {
            return x;
        } else {
            return par[x] = find(par[x]);
        }
    }
    void unite(int x, int y) {
        x = find(x);
        y = find(y);
        if (x == y) return;
        if (rank[x] < rank[y]) swap(x, y);
        if (rank[x] == rank[y]) rank[x]++;
        par[y] = x;
        siz[x] += siz[y];
        cnt--;
    }
    bool is_same(int x, int y) {
        return find(x) == find(y);
    }
    int size(int x) {
        x = find(x);
        return siz[x];
    }
};

int main(){
    ll n, m, q;
    cin >> n >> m >> q;
    UnionFindTree uf;
    uf.init(n);
    set<P> ls;
    for(int i=0;i<q;i++){
        int a, b, c;
        cin >> a >> b >> c;
        if(c) ls.insert(P(a,b));
        else uf.unite(a, b);
    }
    bool ok = true;
    if(ls.size() > 0 && m == n-1) ok = false;
    for(auto p : ls){
        int a = p.first, b = p.second;
        a = uf.find(a);
        b = uf.find(b);
        if(a > b) swap(a,b);
        if(uf.is_same(a,b)) ok = false;
    }
    ok &= m <= n-uf.cnt + ll(uf.cnt-1)*uf.cnt/2;
    cout << (ok ? "Yes" : "No") << endl;
    return 0;
}

