class Dsu{
public:
  std::vector<int> mult;
  std::vector<int> sz;
  Dsu(int n) {
    mult.resize(1 + n);
    sz.resize(1 + n);
    for(int i = 1;i <= n; i++){
      mult[i] = i;
      sz[i] = 1;
    }
  }
  int jump(int gala) {
    if(gala != mult[gala])
      mult[gala] = jump(mult[gala]);
    return mult[gala];
  }
  void unite(int a, int b) {
    a = jump(a);
    b = jump(b);
    if(a == b)
      return ;
    if(sz[b] < sz[a])
      std::swap(a, b);
    sz[b] += sz[a];
    mult[a] = b;
  }
  int _count(int n){
    int result = 0;
    for(int i = 1;i <= n; i++)
      if(mult[i] == i)
        result++;
    return result;
  }
};

