const int MAXN = 2e5 + 5;

vector<pii> bridges, cons;
int par_br[MAXN];

int get_par_br(int v) {
	return par_br[v] == v ? v : par_br[v] = get_par_br(par_br[v]);
}

void finish_no() {
	printf("No\n");
	exit(0);
}

void solve(){
	int n, q, a, b, t;
	ll m;
	scanf("%d%lld%d", &n, &m, &q);
	REP(i, 0, q) {
		scanf("%d%d%d", &a, &b, &t);
		a++, b++;
		if (t == 0) {
			bridges.pb(mp(a, b));
		} else {
			cons.pb(mp(a, b));
		}
	}

	if (m == n - 1) {
		if (SZ(cons) > 0) {
			finish_no();
		}
		printf("Yes\n");
		return;
	}

	REPN(i, 1, n) {
		par_br[i] = i;
	}
	REP(i, 0, SZ(bridges)) {
		a = bridges[i]._1, b = bridges[i]._2;
		a = get_par_br(a), b = get_par_br(b);
		if (a != b) {
			par_br[b] = a;
		}
	}
	REP(i, 0, SZ(cons)) {
		a = cons[i]._1, b = cons[i]._2;
		a = get_par_br(a), b = get_par_br(b);
		if (a == b) {
			finish_no();
		}
	}
	ll comp_br = 0, comp_con = 0;
	REPN(i, 1, n) {
		int br = get_par_br(i);
		if (br == i) {
			comp_br++;
		}
	}

	ll mx = n - comp_br + comp_br * (comp_br - 1) / 2ll;

	if (m > mx) {
		finish_no();
	}

	if (comp_br < 3) {
		finish_no();
	}
	printf("Yes\n");
}   

