constexpr int MOD = 1e9 + 7;
inline int quick_pow(int a, int n)
{
	int res = 1;
	while (n)
	{
		if (n & 1)
			res = (ll)res * a % MOD;
		a = (ll)a * a % MOD;
		n >>= 1;
	}
	return res;
}
int fa[100005], sz[100005];
bool vis[100005];
int getfa(int u) { return u == fa[u] ? u : fa[u] = getfa(fa[u]); }
std::pair<int, int> seq[100005];
int main()
{
	// freopen("AGC038-D.in", "r", stdin);
	int n, q, fix = 0, cnt = 0, rem = 0, comp = 0;
	ll m, mn = 0;
	scanf("%d%lld%d", &n, &m, &q);
	for (int i = 0; i < n; i++)
	{
		fa[i] = i;
		sz[i] = 1;
	}
	for (int i = 0; i < q; i++)
	{
		int u, v, c;
		scanf("%d%d%d", &u, &v, &c);
		if (!c)
		{
			u = getfa(u);
			v = getfa(v);
			if (u == v)
				continue;
			fa[u] = v;
			sz[v] += sz[u];
		}
		else
			seq[cnt++] = {u, v};
	}
	for (int i = 0; i < n; i++)
	{
		if (i == fa[i])
		{
			rem += sz[i] == 1;
			comp++;
			fix += sz[i] - 1;
		}
	}
	for (int i = 0; i < cnt; i++)
	{
		if (getfa(seq[i].first) == getfa(seq[i].second) ||
				(comp == 2 && !rem))
		{
			puts("No");
			return 0;
		}
		int u = getfa(seq[i].first), v = getfa(seq[i].second);
		mn += !vis[u] + !vis[v];
		vis[u] = vis[v] = true;
	}
	puts(m < fix + mn + (mn == 1) || m > fix + (ll)comp * (rem + 1) ? "No" : "Yes");
	return 0;
}

