struct UF{
    vi par;
    vi rank;

    UF( int n ){
        init(n);
    }

    void init( int n ){
        par.assign(n,0);
        for( int i = 0; i < n; i++ ) par[i] = i;
        rank.assign(n,0);
    }

    int find( int x ){
        if( par[x] == x ) return x;
        else return par[x] = find(par[x]);
    }

    int unite( int x, int y ){
        x = find(x);
        y = find(y);
        if( x == y ) return -1;
        if( rank[x] < rank[y] ){
            par[x] = y;
        }else{
            par[y] = x;
            if( rank[x] == rank[y] ) rank[x]++;
        }
        return 1;
    }

    bool same( int x, int y ) {
        return find(x) == find(y);
    }

};
