		}
		for(auto t: c1){
			if(uf0.findSet(t.first, t.second)){
				cout << "No" << endl;
				return;
			}
		}
		long long k = uf0.independentSet;
		if(m <= n + (k*(k-3))/2)cout << "Yes" << "\n";
		else cout << "No" << "\n";
		return;
	};
};

