using namespace std;

class MFSetCell
{
public:

  long mId;

  MFSetCell* mParent;

  long mRank;

};

class MFSet
{
public:

  MFSet(long num);

  ~MFSet() = default;

  long
  find(long id);

  long
  merge(long id1,
	long id2);


private:

  MFSetCell*
  _find_top(MFSetCell* cell);

  vector<MFSetCell> mArray;

};


MFSet::MFSet(long num) :
  mArray(num)
{
  for ( long i = 0; i < num; ++ i ) {
    MFSetCell& cell = mArray[i];
    cell.mId = i;
    cell.mParent = &cell;
    cell.mRank = 0;
  }
}

long
MFSet::find(long id)
{
  auto tmp = &mArray[id];
  auto top = _find_top(tmp);
  return top->mId;
}

MFSetCell*
MFSet::_find_top(MFSetCell* cell)
{
  auto parent = cell->mParent;
  while ( parent->mParent != parent ) {
    cell = cell->mParent = parent->mParent;
    parent = cell->mParent;
  }
  return parent;
}

long
MFSet::merge(long id1,
	     long id2)
{
  auto cell1 = &mArray[id1];
  auto cell2 = &mArray[id2];

  if ( cell1->mParent != cell1 ) {
    cell1 = _find_top(cell1);
  }
  if ( cell2->mParent != cell2 ) {
    cell2 = _find_top(cell2);
  }
  if ( cell1 == cell2 ) {
    return cell1->mId;
  }

  if ( cell1->mRank > cell2->mRank ) {
    cell2->mParent = cell1;
    return cell1->mId;
  }
  else if ( cell1->mRank == cell2->mRank ) {
    ++ cell1->mRank;
    cell2->mParent = cell1;
    return cell1->mId;
  }
  else {
    cell1->mParent = cell2;
    return cell2->mId;
  }
}

