#define N 200005

int n, K, a[N];

int mx[N << 2], mi[N << 2];

void Build(int l, int r, int pos) {
    if (l == r) {
        mx[pos] = a[l];
        mi[pos] = a[l];
        return ;
    } rint mid = (l + r) >> 1;
    Build(l, mid, pos << 1);
    Build(mid + 1, r, pos << 1 | 1);
    mx[pos] = max(mx[pos << 1], mx[pos << 1 | 1]);
    mi[pos] = min(mi[pos << 1], mi[pos << 1 | 1]);
}

int Queryx(int l, int r, int L, int R, int pos) {
    if (L <= l && r <= R) return mx[pos];
    int mid = (l + r) >> 1, res = -1;
    if (L <= mid) res = Queryx(l, mid, L, R, pos << 1);
    if (mid < R) res = max(res, Queryx(mid + 1, r, L, R, pos << 1 | 1));
    return res;
}

int Queryi(int l, int r, int L, int R, int pos) {
    if (L <= l && r <= R) return mi[pos];
    int mid = (l + r) >> 1, res = n + 2;
    if (L <= mid) res = Queryi(l, mid, L, R, pos << 1);
    if (mid < R) res = min(res, Queryi(mid + 1, r, L, R, pos << 1 | 1));
    return res;
}

int f[N];

int T[N];

inline void Modify(int pos, int val) {
    while (pos <= n) T[pos] = max(T[pos], val), pos += pos & (-pos);
}

inline int Query(int pos) {
    int res = 0;
    while (pos) res = max(res, T[pos]), pos -= pos & (-pos);
    return res;
}

