		if (used[i]) mxUsedComp = max(mxUsedComp, comp[i]);
	}

	for (int i = 0; i < n; i++) {
		if ((comp[i] == mxUsedComp && !used[i]) || (mxUsedComp == 0 && mxComp == comp[i])) {
			while (!freeNodes.empty()) {
				int c = freeNodes.top().second;
				freeNodes.pop();
				comp[i] += comp[c];
				comp[c] = 0;
			}
		}
	}
	long long minM = n-1;
	long long maxM = n-1;
	for (int i = 0; i < n; i++) {
		if (comp[i] == 0)
			continue;
		if (comp[i] > 1) minM++;
		maxM += (comp[i] * 1ll * (comp[i] - 1)) / 2;
	}
	if (minM <= m && m <= maxM) {
		printf("Yes\n");
	} else printf("No\n");
}

