struct UnionFind {
  std::vector<int> par;
  std::vector<int> sizes;

  UnionFind(int n) {
    par.resize(n);
    sizes.resize(n);
    for (int i = 0; i < n; ++i) {
      par[i] = i;
      sizes[i] = 1;
    }
  }

  int root(int a) { return par[a] == a ? a : par[a] = root(par[a]); }

  bool same(int x, int y) { return root(x) == root(y); }

  void unite(int x, int y) {
    x = root(x);
    y = root(y);
    if (x == y)
      return;
    if (sizes[x] < sizes[y])
      std::swap(x, y);

    par[y] = x;
    sizes[x] += sizes[y];
  }
  int size(int x) { return sizes[root(x)]; }
};

int main() {
  cin.tie(0);
  ios::sync_with_stdio(false);
  int n, m, q;
  cin >> n >> m >> q;
  vector<pii> a, b;
  vi used(n);
  REP(i, q) {
    int u, v, c;
    cin >> u >> v >> c;
    used[u] = 1;
    used[v] = 1;
    if (c == 0) {
      a.push_back({u, v});
    } else {
      b.push_back({u, v});
    }
  }
  queue<int> unused;
  REP(i, n) if (used[i] == 0) unused.push(i);
  UnionFind uf(n);
  REP(i, b.size()) { uf.unite(b[i].first, b[i].second); }
  map<int, ll> cnt;
  REP(i, n) cnt[uf.root(i)]++;
  ll tmax = 0, tmin = 0;
  bool ok = true;
  ll msz = 0, root = 0;
  for (auto &&a : cnt) {
    if (a.second == 2) {
      if (unused.empty())
        ok = false;
      else {
        int tmp = unused.front();
        unused.pop();
        a.second++;
        uf.unite(tmp, a.first);
      }
    }
    if (chmax(msz, a.second)) {
      root = a.first;
    }
    if (a.second > 1)
      tmin += a.second;
    tmax += a.second * (a.second - 1) / 2;
  }
  REP(i, a.size()) {
    if (uf.same(a[i].first, a[i].second))
      ok = false;
    uf.unite(a[i].first, a[i].second);
    tmin++;
    tmax++;
  }
  map<int, ll> cnt2;
  REP(i, n) cnt2[uf.root(i)]++;
  for (auto &&a : cnt2) {
    if (uf.same(root, a.first))
      continue;
    tmax += a.second * msz;
    msz += a.second;
    tmin++;
  }
  if (tmin < m || m > tmax)
    ok = false;
  cout << (ok ? "Yes" : "No") << endl;
}

