int
main(int argc,
     char** argv)
{
  cin.tie(0);
  ios::sync_with_stdio(0);

  long N;
  long M;
  long Q;
  cin >> N
      >> M
      >> Q;

  if ( Q == 0 ) {
    abort();
  }
  if ( M > ((N * (N - 1)) / 2) ) {
    abort();
  }

  MFSet mfset(N);

  vector<pair<long, long>> single_pair_list;
  vector<pair<long, long>> multi_pair_list;
  bool has_single = false;
  for ( long i = 0; i < Q; ++ i ) {
    long a, b, c;
    cin >> a >> b >> c;
    if ( c == 0 ) {
      single_pair_list.push_back(make_pair(a, b));
      mfset.merge(a, b);
      has_single = true;
    }
    else {
      multi_pair_list.push_back(make_pair(a, b));
    }
  }

  if ( M == N - 1 ) {
    // M = N - 1 の時は木構造のグラフとなる．
    if ( multi_pair_list.size() > 0 ) {
      // その場合複数経路はありえない．
      no();
    }
    else {
      yes();
    }
  }

  if ( !has_single ) {
    yes();
  }

  for ( auto p: multi_pair_list ) {
    long a = p.first;
    long b = p.second;
    if ( mfset.find(a) == mfset.find(b) ) {
      no();
    }
  }

  long K = 0;
  for ( long i = 0; i < N; ++ i ) {
    if ( mfset.find(i) == i ) {
      ++ K;
    }
  }

  long M_max = N - K + (K * (K - 1)) / 2;
  if ( M > M_max ) {
    no();
  }

  yes();

  return 0;
}

