const int max_n = 200022, inf = 1000111222;

struct dsu {
    int p[max_n], sz[max_n];
    dsu() {
        for (int i = 0; i < max_n; ++i) {
            p[i] = i;
            sz[i] = 1;
        }
    }
    int find_set(int x) {
        if (p[x] == x) return x;
        return p[x] = find_set(p[x]);
    }
    void union_set(int x, int y) {
        x = find_set(x);
        y = find_set(y);
        if (x != y) {
            if (sz[x] < sz[y]) swap(x, y);
            sz[x] += sz[y];
            p[y] = x;
        }
    }
};

