int used[N + 5], sz[N + 5];
int cnt[N + 5];

int find(int x){
	if(par[x] == x) return x;
	return par[x] = find(par[x]);
}

bool vis[N + 5], flag[N + 5];

bool solve(){
	int cnt = 0;
	for(int i=0; i<lst.size(); i++){
		int u = lst[i].first;
		int v = lst[i].second;
		int pu = find(u);
		int pv = find(v);
		if(pu == pv) return false;
		m -= (sz[pu] * sz[pv] - 1);
		if(!vis[u] && !flag[u]){
			vis[u] = true;
			cnt++;
		}
		if(!vis[v] && !flag[v]){
			vis[v] = true;
			cnt++;
		}
	}
	bool fg = false;
	for(int i=0; i<n; i++){
		if(!flag[i] && !vis[i]){
			m -= (n-1);
			fg = true;
		}
		else if(flag[i] && find(i) == i){
			m -= sz[i] * (sz[i-1]) / 2 - used[i];
		}
	}
	for(int i=0; i<n; i++){
		if(sz[i] > 1 && !fg) return false;
	}
	return m <= 0;
}

