const int N = 210000;

int n, m, q;

int p[N];
int sz[N];

int get(int x) {
	if (x == p[x]) {
		return x;
	}
	return p[x] = get(p[x]);
}

void un(int a, int b) {
	a = get(a), b = get(b);
	if (a == b) {
		return;
	}
	if (sz[a] > sz[b]) {
		swap(a, b);
	}
	sz[b] += sz[a];
	p[a] = b;
}

void no() {
	cout << "No\n";
	exit(0);
}

void yes() {
	cout << "Yes\n";
	exit(0);
}

int main() {
	ios_base::sync_with_stdio(false), cin.tie(0), cout.tie(0);
	cout.setf(ios::fixed), cout.precision(20);
