    ios::sync_with_stdio(false);
    ll N,M,Q; cin >> N >> M >> Q;
    UnionFind uf(N);
    vector<Pii> query;
    rep(i,Q){
        int a,b,c; cin >> a >> b >> c;
        if (!c) uf.merge(a,b);
        else query.emplace_back(a,b);
    }
    set<int> pars;
    ll minimum=0,maximum=0;
    rep(i,N){
        if (pars.count(uf.root(i))) continue;
        pars.insert(uf.root(i));
        minimum+=(ll)uf.size(i)-1,maximum+=(ll)uf.size(i)-1;
    }
