struct UnionFind{
    vector<ll> par;
    vector<ll> siz;
    ll c;

    void init(ll n){
        c=n;
        for(ll i=0;i<n;i++){
            par.push_back(i);
            siz.push_back(1);
        }
    }

    UnionFind(ll n){
        init(n);
    }

    ll root(ll x){
        //根を返す
        if(par[x]==x){
            return x;
        }
        else{
            return (par[x]=root(par[x]));
        }
    }
    bool sameParent(ll x,ll y){
        return(root(x)==root(y));
    }
    void unite(ll x, ll y){
        x=root(x);y=root(y);
        if(x==y)    return;
        if(siz[x]<siz[y]) swap(x,y);
        siz[x] += siz[y];
        par[y]=x;
        c--;
    }

    ll size(ll x){
        return siz[root(x)];
    }
};
