class UnionFindTree{
  struct base_node{
    int parent;
    int rank;
    int size;
  };

  vector<base_node> node;
 public:
  UnionFindTree(int n){
    node.resize(n);
    for(int i=0; i<n; i++){
      node[i].parent=i;
      node[i].rank=0;
      node[i].size=1;
    }
  }

  int find(int x){  //return root node of x
    if(node[x].parent == x) return x;
    else{
      return node[x].parent = find(node[x].parent);
    }
  }

  bool same(int x, int y){
    return find(x) == find(y);
  }

  int size(int at){
    return node[find(at)].size;
  }

  void unite(int x, int y){
    x = find(node[x].parent);
    y = find(node[y].parent);

    if(x==y) return;

    if(node[x].rank < node[y].rank){
      node[x].parent = y;
      node[y].size += node[x].size;
    }else if(node[x].rank > node[y].rank){
      node[y].parent = x;
      node[x].size += node[y].size;
    }else{
      node[x].rank++;
      unite(x,y);
    }
  }
};


int main(){
  long long n, m, q;
  cin >> n, m, q;

  vector<pair<int, int>> q0, q1;
  for(int i=0; i<q; i++){
    long long a, b, c;
    cin >> a, b, c;
    if(c == 0){
      q0.emplace_back(a, b);
    }else{
      q1.emplace_back(a, b);
    }
  }

  UnionFindTree uft(n);
  for(auto e: q0){
    uft.unite(e.first, e.second);
  }

  set<int> d;
  bool ok = true;
  for(auto e: q1){
    int a,b;
    tie(a,b) = e;
    if(uft.same(a,b)){
      ok = false;
    }
    d.insert(uft.find(a));
    d.insert(uft.find(b));
  }

  set<int> v;
  for(int i=0; i<n; i++){
    v.insert(uft.find(i));
  }

  long long s = v.size();

  if(q1.size() == 0){
    long long base = (n-1)-(s-1);
    long long e_min = base + (s-1);
    long long e_max = base + (s * s-1) / 2;

    ok = e_min <= m && m <= e_max;
  } else {
    long long base = (n-1)-(s-1);
    long long e_min = base + s;
    long long e_max = base + (s * s-1) / 2;

    ok = e_min <= m && m <= e_max;
  }

  println(ok ? "Yes" : "No");

  return 0;
}

