using namespace std;
typedef long long ll;
typedef vector<int> vi;
typedef vector<vi> vvi;
class U {
	private:
		vi p,rk;
		int n,nc;
	public:
		U(int _n) {
			n = _n;
			nc = n;
			rk.assign(n,0);
			for(int i=0;i<n;i++) {
				p.push_back(i);
			}
		}
		int find(int a) {
			if(a == p[a]) return a;
			return p[a] = find(p[a]);
		}
		bool same(int a, int b) {
			return find(a) == find(b);
		}
		bool un(int a, int b) {
			if(same(a,b)) return false;
			nc--;
			int x = find(a),y = find(b);
			if(rk[x] > rk[y]) {
				p[y] = x;
				return true;
			}
			if(rk[x] == rk[y]) {rk[y]++;}
			p[x] = y;
			return true;
		}
		int con() {
			return nc;
		}
};
int main() {
	ios::sync_with_stdio(0);
	bool rec = false;
	ll n,m,q;
	cin >> n >> m >> q;
	U co(2*n),br(n);
	for(int i=0;i<q;i++) {
		int a,b,c;
		cin >> a >> b >> c;
		if(c) {
			rec = true;
			co.un(a,b+n);
			co.un(b,a+n);
		} else {
			co.un(a,b);
			co.un(a+n,b+n);
			br.un(a,b);
		}
	}
	bool po = true;
	for(int i=0;i<n;i++) {
		if(co.same(i,n+i)) {po = false;break;}
	}
	if(m == n-1) {
		cout << (rec?"Yes":"No") << '\n';
		return 0;
	}
	ll sz = br.con();
	//cout << sz << '\n';
	ll ma,mb;
	mb = n;
	ma = n-sz+(sz*(sz-1)/2);
	//cout << ma << " " << mb << '\n';
	if(!(m <= ma && m >= mb)) {
		po = false;
	}
	cout << (po?"Yes":"No") << '\n';
}

