		}
	}
	bool has = false;
	for (auto& e : dups) {
		int a = e.first, b = e.second;
		int ra = root(a), rb = root(b);
		if (ra == rb) no();
		has = true;
	}
	if (comps <= 2) {
		if (has) no();
		if (m != n - 1) no();
	} else {
		// At least 3 components.
		if (m == n - 1) {
			if (has) no();
		} else {
			ll mx = (ll)comps * (comps - 1) / 2;
			int used = n - comps;
			if (used + mx < m) no();
		}
	}
	printf("Yes\n");
}

