	out.tie(nullptr);

	in >> N>>M>>Q;
	union_find single(N+10);
	for (int i = 0; i < Q; i++)
	{
		in >> A[i] >> B[i] >> T[i];//--A[i]; --B[i];
	}
	for (int i = 0; i < Q; i++)
	{
		if (T[i] == 0) {
			single.unite(A[i], B[i]);
		}
	}
	bool T1find = false;
	for (int i = 0; i < Q; i++)
	{
		if (T[i] == 1) {
			T1find = true;
			if (single.check(A[i], B[i])) {
				out << "No" << endl;
				return 0;
			}
			auto a = single.find(A[i]);
			auto b = single.find(B[i]);
			graph[a].insert(b);
			graph[b].insert(a);
		}
	}


	int nnn = 0;
	int64_t needM = 0, maxM = 0;
	for (int i = 0; i < N; i++)
	{
		if (single.find(i) == i) {
			++nnn;
			needM += single.getsize(i) - 1;
		}
	}
	maxM = needM + int64_t(nnn) * int64_t(nnn - 1) / 2;
	if ((M < needM) || (maxM < int64_t(M))) {
		out << "No" << endl;
