static const int MAX = 100000;

// Union-Find木
int par[MAX]; // 親の番号

// n要素で初期化
void init(int n) {
  for(int i = 0; i < n; i++) par[i] = i;
}

// 木の根を求める
int find(int x) {
  if(par[x] == x) return x;
  else return par[x] = find(par[x]);
}

// xとyが同じ集合に属するか
bool same(int x, int y) {
  return find(x) == find(y);
}

// xとyの属する集合を併合
void unite(int x, int y) {
  x = find(x);
  y = find(y);
  if(x == y) return;
  par[x] = y;
}

int main() {
  int n, m, q;
  cin >> n >> m >> q;

  init(n);

  vector<int> used(n);
  vector<pair<int, int>> keep;
  for(int i = 0; i < q; i++){
    int a, b, c;
    cin >> a >> b >> c;
    used.at(a) = used.at(b) = 1;

    if(c == 0){
      if(!(same(a, b))){
        unite(a, b);
      }
    }
    else{
      keep.push_back(make_pair(a, b));
    }
  }

  int count = 0;
  for(int i = 0; i < n; i++){
    if(used.at(i) == 0) count++;
  }

  bool ans = true;
  int count2 = 0;
  for(int i = 0; i < keep.size(); i++){
    if(same(keep.at(i).first, keep.at(i).second)) ans = false;
    else{
      unite(keep.at(i).first, keep.at(i).second);
      count2++;
    }
  }

  if(ans == false || count < count2) cout << "No" << endl;
  else cout << "Yes" << endl;
}

