struct DisjointSet {
  vector<int> pset, setSize;
  int setNum;

  DisjointSet() {}
  DisjointSet(int n) {
    initSet(n);
  }

  void initSet(int n) {
    pset.resize(n);
    setSize.assign(n, 1);
    setNum = n;
    for (int i = 0; i < n; i++) pset[i] = i;
  }

  int find(int n) { return pset[n] == n ? n : (pset[n] = find(pset[n])); }

  bool isSameSet(int i, int j) { return find(i) == find(j); }

  void merge(int i, int j) {
    if(isSameSet(i, j)) return;
    setNum--;
    i = find(i);
    j = find(j);
    if(setSize[i] < setSize[j]) {
      pset[i] = j;
      setSize[j] += setSize[i];
    } else {
      pset[j] = i;
      setSize[i] += setSize[j];
    }
  }
};

void Main() {
  int n, m, q;
  cin >> n >> m >> q;
  vector<pii> diffQuery;
  DisjointSet ds(n);
  REP(i, q) {
    int a, b, c;
    cin >> a >> b >> c;
    if (c == 0) ds.merge(a, b);
    else diffQuery.eb(a, b);
  }
  for (auto &it : diffQuery) {
    if (ds.isSameSet(it.fi, it.se)) {
      cout << "No" << endl;
      return;
    }
  }
  ll mn = diffQuery.empty() ? (n - 1) : n;
  ll mx = n - ds.setNum + 1LL * ds.setNum * (ds.setNum - 1) / 2;
  if (m < mn || m > mx) {
    cout << "No" << endl;
    return;
  }
  cout << "Yes" << endl;
}

