int f[MAXN];
int F(int x) {
	if (f[x] == x) return x;
	else return f[x] = F(f[x]);
}
int x[MAXN], y[MAXN], type[MAXN];
int main() {
	int n, q; ll m;
    ll pos=0;
	read(n), read(m), read(q);
	for (int i = 1; i <= n; i++)
		f[i] = i;
	for (int i = 1; i <= q; i++) {
		read(x[i]), read(y[i]), read(type[i]);
		x[i]++, y[i]++;
		if (type[i] == 0) {
            if(F(x[i])!=F(y[i])){
			f[F(x[i])] = F(y[i]);pos++;}
		} else {
			if (m == n - 1) {
				puts("No");
				return 0;
			}
		}
	}
	for (int i = 1; i <= q; i++)
		if (type[i] && F(x[i]) == F(y[i])) {
			puts("No");
			return 0;
		}
	int cnt = 0;
	for (int i = 1; i <= n; i++)
		cnt += F(i) == i;
	if (cnt <= 2) {
		for (int i = 1; i <= q; i++)
			if (type[i]) {
				puts("No");
				return 0;
			}
	}
	ll ans = pos;
	ans += 1ll * cnt * (cnt - 1) / 2;
	if (ans >= m) puts("Yes");
	else puts("No");
	return 0;
}

