	if(U.size()==2 && V.size()==1){ puts("No"); return 0; }

	lint k=U.size();
	lint mn,mx=k*(k-1)/2;
	if(E2.empty()) mn=k-1; // spanning tree
	else           mn=k;   // cycle

	if((n-k)+mn<=m && m<=(n-k)+mx) puts("Yes");
	else                           puts("No");

	return 0;
}

