class UnionFind {
    vector<int> par, Size;

  public:
    int c; // 連結成分
    UnionFind(int n) : par(n), Size(n, 1), c(n) { rep(i, n) par[i] = i; }

    int root(int x) {
        if(par[x] == x) return x;
        return par[x] = root(par[x]);
    }
    bool same(int x, int y) { return root(x) == root(y); }
    bool unite(int x, int y) {
        x = root(x);
        y = root(y);
        if(x == y) return false;
        if(Size[x] > Size[y]) {
            Size[x] += Size[y];
            par[y] = x;
        } else {
            Size[y] += Size[x];
            par[x] = y;
        }
        c--;
        return true;
    }
    int size(int x) { return Size[root(x)]; }
};

