class union_find{
	int n;
	vector<int> p;
public:
	union_find(int n):n(n),p(n,-1){}
	int find(int u){ return p[u]<0?u:p[u]=find(p[u]); }
	void unite(int u,int v){
		u=find(u); v=find(v);
		if(u!=v){
			if(p[v]<p[u]) swap(u,v);
			p[u]+=p[v]; p[v]=u; n--;
		}
	}
	bool is_same(int u,int v){ return find(u)==find(v); }
	int size(){ return n; }
	int size(int u){ return -p[find(u)]; }
};

int main(){
	int n,m,q; scanf("%d%d%d",&n,&m,&q);
	vector<pair<int,int>> E1,E2;
	rep(i,q){
		int u,v,c; scanf("%d%d%d",&u,&v,&c);
		if(c==0) E1.emplace_back(u,v);
		else     E2.emplace_back(u,v);
	}

	union_find U(n);
	for(auto e:E1){
		int u,v; tie(u,v)=e;
		if(U.is_same(u,v)) return puts("No"),0;
		U.unite(u,v);
	}

	map<int,int> f;
	rep(u,n) if(f.count(U.find(u))==0) f[U.find(u)]=f.size();

	union_find V(U.size());
	for(auto e:E2){
		int u,v; tie(u,v)=e;
		if(U.is_same(u,v)) return puts("No"),0;
		V.unite(f[U.find(u)],f[U.find(v)]);
	}

	if(U.size()==2 && V.size()==1) return puts("No"),0;

	int k=U.size();
	lint mn=-1,mx=k*(k-1LL)/2;
	{ // calculate mn
		vector<bool> used(k);
		rep(i,k) if(!used[V.find(i)]) {
			used[V.find(i)]=true;
			mn+=V.size(i);
		}
	}
	if(E1.size()+mn<=m && m<=E1.size()+mx){
		puts("Yes");
	}
	else{
		puts("No");
	}

	return 0;
}

