void
dfs(int i,
    int gid,
    vector<int>& group_id,
    const vector<vector<int>>& adj_list)
{
  if ( group_id[i] != -1 ) {
    return;
  }
  group_id[i] = gid;
  for ( int j: adj_list[i] ) {
    dfs(j, gid, group_id, adj_list);
  }
}

int
main(int argc,
     char** argv)
{
  int N;
  int M;
  int Q;
  cin >> N >> M >> Q;

  vector<vector<int>> adj_list(N);
  vector<pair<int, int>> multi_pair_list;
  vector<int> group_id(N, -1);
  int K = 0;

  for ( int i = 0; i < Q; ++ i ) {
    int a, b, c;
    cin >> a >> b >> c;
    if ( c == 0 ) {
      adj_list[a].push_back(b);
      adj_list[b].push_back(a);
    }
    else {
      multi_pair_list.push_back(make_pair(a, b));
    }
  }

  if ( M == N - 1 ) {
    // M = N - 1 の時は木構造のグラフとなる．
    if ( multi_pair_list.size() > 0 ) {
      // その場合複数経路はありえない．
      cout << "No" << endl;
      return 0;
    }
    else {
      cout << "Yes" << endl;
      return 0;
    }
  }

  for ( int i = 0; i < N; ++ i ) {
    if ( group_id[i] != -1 ) {
      continue;
    }
    dfs(i, K, group_id, adj_list);
    ++ K;
  }

  bool ng = false;
  for ( auto p: multi_pair_list ) {
    int a = p.first;
    int b = p.second;
    if ( group_id[a] == group_id[b] ) {
      cout << "No" << endl;
      return;
      ng = true;
      break;
    }
  }

#if 0
  if ( K == 2 ) {
    abort();
    K = 1;
  }
#endif

  if ( !ng && M <= N + K * (K - 3) / 2 ) {
    cout << "Yes" << endl;
  }
  else {
    cout << "No" << endl;
  }

  return 0;
}

