 			s.insert({t, t1});
 			g[t].pb(t1);
 			g[t1].pb(t);
 		}
 	}
 	int k = n - 1;
 	vector<pair<int, int> > gays;
 	for (int i = 0; i < n; i++) {
 		if (findset(i) == i) {
 			if (!used[i]) {
 				st.clear();
