		a--, b--;
		if (!c) {
			uni(a, b);
		} else {
			bad.push_back({a, b});
		}
	}

	vector <bool> used(n, false);

	ll mink = 0;

	for (auto t : bad) {
		int v = t.first, u = t.second;
		if (!used[get(v)]) {
			used[get(v)] = true;
			mink++;
		}
		if (!used[get(u)]) {
			used[get(u)] = true;
			mink++;
		}
		if (get(v) == get(u)) {
			cout << "No\n";
			return 0;
		}
	}

