class unionfind {
	vector<int> par, rank;

public:
	void init(int n) {
		par.resize(n);
		rank.resize(n);

		for (int i = 0; i < n; i++) {
			par[i] = i;
			rank[i] = 0;
		}
	}

	int find(int x) {
		if (par[x] == x) return x;
		else return par[x] = find(par[x]);
	}

	void unite(int x, int y) {
		x = find(x);
		y = find(y);
		if (x == y) return ;

		if (rank[x] < rank[y]) par[x] = y;
		else {
			par[y] = x;
			if (rank[x] == rank[y]) ++rank[x];
		}
	}

	bool same(int x, int y) { return (find(x) == find(y)); }
} uf;

int main() {
	int N, Q; ll M;
	cin >> N >> M >> Q;

	uf.init(N);

	int e = 0;

	vector<pii> two;

	rep(i, Q) {
		int A, B, C;
		cin >> A >> B >> C;
		if (C == 0) {
			if (!uf.same(A, B)) {
				uf.unite(A, B);
				++e;
			}
		} else {
			two.eb(A, B);
		}
	}

	for (pii p : two) {
		if (uf.same(p.fi, p.se)) {
			puts("No");
			return 0;
		}
	}

	ll cmp = N - e;
	ll mini = N - 1 + (two.size() > 0);
	ll maxi = e + cmp * (cmp - 1) / 2;

	if (M < mini || M > maxi) {
		puts("No");
		return 0;		
	}

	puts("Yes");

	return 0;
}

