    bool ng = false;
    for (auto& p : ps) {
        if (uf.is_same(p.fi, p.se)) ng = true;
        uf.unite(p.fi, p.se);
    }
    int cnt = 0;
    REP (i, n) {
        if (uf.size(i) == 1) cnt++;
    }
    if (cnt == 0 && ps.size() != 0) ng = true;

    int e = uf.cnt - 1;
    REP (i, n) {
        if (uf.root(i) == i) e += uf.size(i) - 1;
    }
    int mi = e;
    if (ps.size()) mi++;
    if (m < mi) ng = true;

