#define range(i, m, n) for(int i = m; i < n; i++)
#define husk(i, m, n) for(int i = m; i > n; i--)

class dsu {
 public:
  vector<int> p;
  int n;

  dsu(int _n) : n(_n) {
    p.resize(n);
    iota(p.begin(), p.end(), 0);
  }

  inline int get(int x) {
    return (x == p[x] ? x : (p[x] = get(p[x])));
  }

  inline bool unite(int x, int y) {
    x = get(x);
    y = get(y);
    if (x != y) {
      p[x] = y;
      return true;
    }
    return false;
  }
};

int n, m, q;

int main() {
  cin >> n >> m >> q;
  vector<pair<int, int>> s[2];
  while(q--) {
    int a, b, c;
    scanf("%d%d%d", &a, &b, &c);
    s[c].emplace_back(a, b);
  }
  dsu ss(n);
  for(auto u : s[0]) {
    ss.unite(u.first, u.second);
  }
  for(auto u : s[1]) {
    if(ss.get(u.first) == ss.get(u.second)) {
      cout << "No";
      return 0;
    }
  }
  vector<int> scc(n);
  range(i, 0, n) scc[ss.get(i)]++;
  sort(scc.begin(), scc.end(), greater<int>());
  while(scc.back() == 0) scc.pop_back();
  if((int) scc.size() < 3) {
    cout << "No";
    return 0;
  }
  int sz = scc.size();
  int cnt = 0;
  range(i, 0, 3) if(scc[i] == scc[0]) cnt++;
  while(cnt < 3) {
    if((int) scc.size() < 3) {
      cout << "No";
      return 0;
    }
    if(cnt == 1) {
      scc[0]--; scc[sz - 1]--; scc[sz - 2]--;
    }
    if(cnt == 2) {
      scc[0]--; scc[1]--; scc[sz - 1]--;
    }
    range(i, 0, 3) if(scc[i] == scc[0]) cnt++;
    while(scc.back() == 0) scc.pop_back();
    sz = scc.size();
  }
  cout << "Yes";
  return 0;
}

