ull parent[1010101], size[1010101];
void init (ull n) {
	for (sll i = 0; i < n; i++) {
		parent[i] = i;
		size[i] = 1;
	}
}
ull find (ull x) {
	if (parent[x] == x) return x;
	return parent[x] = find(parent[x]);
}
bool unite (ull a, ull b) {
	a = find(a);
	b = find(b);

	if (a == b) return false;

	if (size[a] < size[b]) {
		ull t = a;
		a = b;
		b = t;
	}
	size[a] += size[b];
	parent[b] = a;
	return true;
}

