import java.util.InputMismatchException;

public class Main {
	static InputStream is;
	static PrintWriter out;
	static String INPUT = "";

	static void solve()
	{
		int n = ni();
		long m = nl();
		int Q = ni();
		int[][] qs = new int[Q][];
		for(int i = 0;i < Q;i++){
			qs[i] = na(3);
		}
		DJSet ds = new DJSet(n);
		for(int[] q : qs){
			if(q[2] == 0){
				ds.union(q[0], q[1]);
			}
		}
		int one = 0;
		for(int[] q : qs){
			if(q[2] == 1){
				one = 1;
				if(ds.equiv(q[0], q[1])){
					out.println("No");
				}
			}
		}

		if(one > 0 && ds.count() == 2){
			out.println("No");
			return;
		}

		long E = 0;
		for(int i = 0;i < n;i++){
			if(ds.upper[i] < 0){
				E += -ds.upper[i] - 1;
			}
		}

		int[] multi = new int[n];
		for(int[] q : qs){
			if(q[2] == 1){
				multi[ds.root(q[0])] = 1;
				multi[ds.root(q[1])] = 1;
			}
		}
		int sm = 0;
		for(int i = 0;i < n;i++){
			sm += multi[i];
		}
		long min = E + (sm == 0 ? 0 : Math.max(3, sm));
		long max = E + (long)ds.count() * ((long)ds.count()-1) / 2;
		if(min <= m && m <= max){
			out.println("Yes");
		}else{
			out.println("No");
		}
	}

	public static class DJSet {
		public int[] upper;

		public DJSet(int n) {
			upper = new int[n];
			Arrays.fill(upper, -1);
		}

		public int root(int x) {
			return upper[x] < 0 ? x : (upper[x] = root(upper[x]));
		}

		public boolean equiv(int x, int y) {
			return root(x) == root(y);
		}

		public boolean union(int x, int y) {
			x = root(x);
			y = root(y);
			if (x != y) {
				if (upper[y] < upper[x]) {
					int d = x;
					x = y;
					y = d;
				}
				upper[x] += upper[y];
				upper[y] = x;
			}
			return x == y;
		}

		public int count() {
			int ct = 0;
			for (int u : upper)
				if (u < 0)
					ct++;
			return ct;
		}
	}


