    static class DUniquePath {
        public void solve(int testNumber, InputReader in, OutputWriter out) {
            int n = in.readInt();
            int m = in.readInt();
            int q = in.readInt();

            Set<Integer> set = new TreeSet<>();
            UnionFind uf1 = new UnionFind(n);
            UnionFind uf2 = new UnionFind(n);
            for (int i = 0; i < q; i++) {
