import java.util.Collections;
import java.io.InputStream;

/**
 * Built using CHelper plug-in Actual solution is at the top
 *
 * @author ilyakor
 */
public class Main {

  public static void main(String[] args) {
    InputStream inputStream = System.in;
    OutputStream outputStream = System.out;
    InputReader in = new InputReader(inputStream);
    OutputWriter out = new OutputWriter(outputStream);
    TaskD solver = new TaskD();
    solver.solve(1, in, out);
    out.close();
  }

  static class TaskD {

    public void solve(int testNumber, InputReader in, OutputWriter out) {
      int n = in.nextInt();
      long m = in.nextLong();
      int q = in.nextInt();
      DisjointSets dsu = new DisjointSets(n);
      int[] cnt = new int[n];
      Arrays.fill(cnt, 1);
      ArrayList<ii> forbidden = new ArrayList<>();
      for (int i = 0; i < q; ++i) {
        int x = in.nextInt();
        int y = in.nextInt();
        int c = in.nextInt();
        if (c == 1) {
          int rx = dsu.root(x), ry = dsu.root(y);
          if (rx != ry) {
            int cr = cnt[rx] + cnt[ry];
            dsu.unite(rx, ry);
            cnt[dsu.root(rx)] = cr;
          }
        } else {
          forbidden.add(new ii(x, y));
        }
      }
      HashSet<ii> newForb = new HashSet<>();
      for (ii e : forbidden) {
        int x = dsu.root(e.first), y = dsu.root(e.second);
        if (x == y) {
          out.printLine("No");
          return;
        }
        if (x > y) {
          int t = x;
          x = y;
          y = t;
        }
        ii entry = new ii(x, y);
        if (!newForb.contains(entry)) {
          newForb.add(entry);
        }
      }
      forbidden = new ArrayList<>(newForb);

      DisjointSets dsu2 = new DisjointSets(n);
      int[] cnt2 = new int[n];
      Arrays.fill(cnt2, 1);
      for (ii e : forbidden) {
        int x = e.first;
        int y = e.second;
        int rx = dsu2.root(x), ry = dsu2.root(y);
        if (rx != ry) {
          int cr = cnt2[rx] + cnt2[ry];
          dsu2.unite(rx, ry);
          cnt2[dsu2.root(rx)] = cr;
        }
      }

      ArrayList<Integer> roots = new ArrayList<>();
      for (int i = 0; i < n; ++i) {
        if (dsu.root(i) == i) {
          roots.add(i);
        }
      }
      int k = roots.size();

      long minEdges = 0;
      int[] num2s = new int[n];
      for (int x : roots) {
        if (cnt[x] == 1) {
          continue;
        }
        minEdges += cnt[x];
        if (cnt[x] > 2) {
          continue;
        }
        num2s[dsu2.root(x)] += 1;
      }
      for (int i = 0; i < n; ++i) {
        if (num2s[i] > k - cnt2[i]) {
          out.printLine("No");
          return;
        }
      }
      minEdges += roots.size() - 1;
      if (m < minEdges) {
        out.printLine("No");
        return;
      }

      long maxEdges = 0;
      ArrayList<Integer>[] sizesPerCluster = new ArrayList[n];
      HashSet<Integer> alive = new HashSet<>();
      for (int x : roots) {
        if (dsu2.root(x) == x) {
          sizesPerCluster[x] = new ArrayList<>();
          alive.add(x);
        }
      }
      for (int x : roots) {
        sizesPerCluster[dsu2.root(x)].add(cnt[x]);
      }
      for (int x : alive) {
        Collections.sort(sizesPerCluster[x]);
        Collections.reverse(sizesPerCluster[x]);
      }
      int worst = -1;
      for (int x : alive) {
        if (worst == -1 || num2s[x] - (k - cnt2[x]) > num2s[worst] - (k - cnt2[worst])) {
          worst = x;
        }
      }
      int kInc = 0;
      while (alive.size() > 1) {
        boolean blocked = false;
        ArrayList<ii> cur = new ArrayList<>();
        for (int x : alive) {
          int s = sizesPerCluster[x].get(sizesPerCluster[x].size() - 1);
          cur.add(new ii(-s, x));
        }
        Collections.sort(cur);
        long val = 0;
        for (ii e : cur) {
          int x = e.second, s = -e.first;
          int newNum2 = num2s[x] - (s == 2 ? 1 : 0);
          int newSumOther = k - cnt2[x];
          if (newNum2 > newSumOther) {
            blocked = true;
            continue;
          }
          if (worst != -1 && worst != x) {
            if (num2s[worst] > k - 1 - cnt2[worst]) {
              blocked = true;
              continue;
            }
          }
          val += s;
          --k;
          --cnt2[x];
          if (s == 2) {
            --num2s[x];
          }
          sizesPerCluster[x].remove(sizesPerCluster[x].size() - 1);
          if (sizesPerCluster[x].isEmpty()) {
            alive.remove(x);
          }
          if (worst == -1 || num2s[x] - (k - cnt2[x]) > num2s[worst] - (k - cnt2[worst])) {
            worst = x;
          }
        }
        maxEdges += val * (val - 1L) / 2L;
        kInc += 1;
        if (blocked) {
          break;
        }
      }

      for (int x : alive) {
        if (worst == -1 || num2s[x] - (k - cnt2[x]) > num2s[worst] - (k - cnt2[worst])) {
          worst = x;
        }
      }
      ArrayList<Integer> toMatch = new ArrayList<>();
      int twos = 0;
      ArrayList<Integer> other = new ArrayList<>();
      for (int x : alive) {
        if (x != worst) {
          toMatch.addAll(sizesPerCluster[x]);
        } else {
          twos = num2s[x];
          for (int y : sizesPerCluster[x]) {
            if (y != 2) {
              other.add(y);
            }
          }
        }
      }
      if (twos > toMatch.size()) {
        throw new RuntimeException();
      }
      Collections.sort(toMatch);
      for (int i = 0; i < twos; ++i) {
        toMatch.set(toMatch.size() - i - 1, toMatch.get(toMatch.size() - i - 1) + 2);
      }
      other.addAll(toMatch);
      for (int x : other) {
        maxEdges += x * (long) (x - 1L) / 2L;
      }
      maxEdges += other.size() + kInc - 1;
      if (m > maxEdges) {
        out.printLine("No");
        return;
      }

      out.printLine("Yes");
    }

  }

  static class DisjointSets {

    int[] p;
    int[] rank;

    public DisjointSets(int size) {
      p = new int[size];
      for (int i = 0; i < size; i++) {
        p[i] = i;
      }
      rank = new int[size];
    }

    public DisjointSets(int[] p, int[] rank) {
      this.p = p;
      this.rank = rank;
    }

    public int root(int x) {
      while (x != p[x]) {
        x = p[x];
      }
      return x;
    }

    public void unite(int a, int b) {
      a = root(a);
      b = root(b);
      if (a == b) {
        return;
      }
      if (rank[a] < rank[b]) {
        p[a] = b;
      } else {
        p[b] = a;
        if (rank[a] == rank[b]) {
          ++rank[a];
        }
      }
    }

  }

