        self.id = id
        self.parent = None
        self.child_num = 0
        self.is_root = True
        self.grand_parent = False

    def root(self):
        node = self
        while not node.is_root:
            # print(node.id)
            node = node.parent
        return node

def main():
    N, M, Q = map(int, input().split())
    abc = sorted([list(map(int, input().split())) for i in range(Q)], key=lambda x: x[2])

    nodes = [Node(i) for i in range(N)]
    edge_count = 0
    count_rest = True
    ok = True
    for i in range(Q):
        # print(i)
        a, b, c = abc[i]
        if c == 0:# Union-find
            root_a = nodes[a].root()
            root_b = nodes[b].root()
            if root_a != root_b:
                if root_a.child_num > root_b.child_num:
                    root_b, root_a = root_a, root_b
                root_a.child_num += root_b.child_num + 1
                root_b.parent = root_a
                root_b.is_root = False
                edge_count += 1
                if edge_count > M:
                    ok = False
                    break
        else:
            if count_rest:
                rest_node = 0
                for i in range(N):
                    if nodes[i].is_root and nodes[i].child_num == 0:
                        rest_node += 1
                count_rest = False
            if rest_node == 0:
                ok = False
                break
            root_a = nodes[a].root()
            root_b = nodes[b].root()
            if root_a == root_b:
                ok = False
                break
            elif root_a.grand_parent and root_b.grand_parent:
                pass
            elif root_a.grand_parent and not root_b.grand_parent:
                root_b.grand_parent = True
                edge_count += 1
            elif (not root_a.grand_parent) and root_b.grand_parent:
                root_a.grand_parent = True
                edge_count += 1
            else:
                root_a.grand_parent = True
                root_b.grand_parent = True
                edge_count += 2

    has_grand = 0
    for i in range(N):
        if nodes[i].grand_parent:
            has_grand += 1
    yoyu = (has_grand * (has_grand - 1)) // 2

    if edge_count > M:
        ok = False
    elif edge_count < M:
        if edge_count + rest_node - 1 <= M:
            if edge_count + rest_node - 1 + yoyu < M:
                ok = False
        else:
            ok = False

    if not ok:
        print("No")
    else:
        print("Yes")


