/**
 * Union-Find tree.
 * Verified by https://atcoder.jp/contests/keyence2019/submissions/4071067
 */
struct UnionFind { disj: Vec<usize>, rank: Vec<usize> }

impl UnionFind {
    fn new(n: usize) -> Self {
        let disj = (0..n).collect();
        UnionFind { disj: disj, rank: vec![0; n] }
    }
    fn root(&mut self, x: usize) -> usize {
        if x != self.disj[x] {
            let par = self.disj[x];
            let r = self.root(par);
            self.disj[x] = r;
        }
        self.disj[x]
    }
    fn unite(&mut self, x: usize, y: usize) {
        let mut x = self.root(x);
        let mut y = self.root(y);
        if x == y { return }
        if self.rank[x] > self.rank[y] {
            std::mem::swap(&mut x, &mut y);
        }
        self.disj[x] = y;
        self.rank[y] = std::cmp::max(self.rank[y], self.rank[x] + 1);
    }
    #[allow(unused)]
    fn is_same_set(&mut self, x: usize, y: usize) -> bool {
        self.root(x) == self.root(y)
    }
}

fn solve() {
    let out = std::io::stdout();
    let mut out = BufWriter::new(out.lock());
    macro_rules! puts {
        ($($format:tt)*) => (write!(out,$($format)*).unwrap());
    }
    input! {
        n: usize, m: usize, q: usize,
        abc: [(usize, usize, i32); q],
    }
    let mut ment = vec![false; n];
    let mut uf = UnionFind::new(n);
    let mut nec: usize = 0;
    let mut ma: usize = 0;
    for &(a, b, c) in &abc {
        if c == 1 {
            uf.unite(a, b);
        }
        ment[a] = true;
        ment[b] = true;
    }
    let mut sz = vec![0; n];
    for i in 0..n {
        sz[uf.root(i)] += 1;
    }

    // vars
    let mut unused = 0;
    let mut united: Vec<usize> = vec![];

    for i in 0..n {
        if !ment[i] {
            unused += 1;
            continue;
        }
        if sz[i] >= 2 {
            united.push(sz[i]);
            nec += sz[i];
        }
        if sz[i] == 1 {
            united.push(sz[i]);
        }
    }
    // debugln!("unused = {}, united = {:?}", unused, united);
    for u in united.iter_mut() {
        if *u == 2 {
            if unused > 0 {
                unused -= 1;
                *u += 1;
                nec += 1;
            } else {
                puts!("No\n");
                return;
            }
        }
    }
    united.sort();
    if unused >= 1 {
        if let Some(l) = united.pop() {
            united.push(l + unused);
            nec += unused;
        } else {
            united.push(unused);
            nec += unused - 1;
        }
    }
    for &(a, b, c) in &abc {
        if c == 0 {
            if uf.is_same_set(a, b) {
                puts!("No\n");
                return;
            }
            uf.unite(a, b);
            nec += 1;
            ma += 1;
        }
    }
    for v in united {
        ma += v * (v - 1) / 2;
    }
    debugln!("m = {}, [nec, ma] = [{}, {}]", m, nec, ma);
    puts!("{}\n", if nec <= m && m <= ma { "Yes" } else { "No" });
}

