struct UnionFind {
      n: usize,
      parent: Vec<usize>,
      count: Vec<usize>
}

impl UnionFind {
     fn new(n: usize) -> Self {
           let mut p = vec![0; n];
           for i in 0..n {
                 p[i] = i;
           }
           UnionFind { n: n, parent: p, count: vec![1; n] }
     }

     fn find(&mut self, a: usize) -> usize {
           if self.parent[a] == a {
                 return a;
           }
           let par = self.parent[a];
           self.parent[a] = self.find(par);
           self.parent[a]
     }

     fn unite(&mut self, a: usize, b: usize) {
           let a = self.find(a);
           let b = self.find(b);
           if a == b {
                 return;
           }
           let ca = self.count[a];
           let cb = self.count[b];
           let total = ca + cb;
           self.count[b] = total;
           self.count[a] = total;
           if ca < cb {
                 self.parent[a] = b;
           } else {
                 self.parent[b] = a;
           }
     }

     fn same(&mut self, a: usize, b: usize) -> bool {
           self.find(a) == self.find(b)
     }

     fn count(&mut self, a: usize) -> usize {
           let a = self.find(a);
           self.count[a]
     }
}

type Info = (usize, usize, i32);

fn solve(n: usize, m: usize, mut zeros: Vec<Info>, mut ones: Vec<Info>) -> bool {
    zeros.dedup();
    ones.dedup();

    let mut uf0 = UnionFind::new(n);
    let mut fedges = 0;

    let mut cmp = n;
    for z in zeros {
        if uf0.same(z.0, z.1) {
            continue;
        }
        uf0.unite(z.0, z.1);
        fedges += 1;
        cmp -= 1;
    }
    if ones.len() == 0 {
        let wedge = cmp * (cmp - 1) / 2;
        return m <= wedge + fedges;
    }
    for o in ones {
        if uf0.same(o.0, o.1) {
            return false;
        }
    }

    if cmp == 2 {
        return false;
    }

    let wedge = cmp * (cmp - 1) / 2;
    return m <= wedge + fedges && m >= n;
}

