    input! {
        n: usize, m: usize, q: usize,
        info: [(usize, usize, i32); q]
    };
    let zeros = info.clone().into_iter().filter(|&(a, b, c)| c == 0).collect::<Vec<_>>();
    let ones  = info.clone().into_iter().filter(|&(a, b, c)| c == 1).collect::<Vec<_>>();

    println!("{}", ifv!(solve(n, m, zeros, ones), "Yes", "No"));
}

