/**
 * Union-Find tree.
 * Verified by https://atcoder.jp/contests/keyence2019/submissions/4071067
 */
struct UnionFind { disj: Vec<usize>, rank: Vec<usize> }

impl UnionFind {
    fn new(n: usize) -> Self {
        let disj = (0..n).collect();
        UnionFind { disj: disj, rank: vec![0; n] }
    }
    fn root(&mut self, x: usize) -> usize {
        if x != self.disj[x] {
            let par = self.disj[x];
            let r = self.root(par);
            self.disj[x] = r;
        }
        self.disj[x]
    }
    fn unite(&mut self, x: usize, y: usize) {
        let mut x = self.root(x);
        let mut y = self.root(y);
        if x == y { return }
        if self.rank[x] > self.rank[y] {
            std::mem::swap(&mut x, &mut y);
        }
        self.disj[x] = y;
        self.rank[y] = std::cmp::max(self.rank[y], self.rank[x] + 1);
    }
    #[allow(unused)]
    fn is_same_set(&mut self, x: usize, y: usize) -> bool {
        self.root(x) == self.root(y)
    }
}

fn calc(n: usize, abc: &[(usize, usize, i32)]) -> (usize, usize) {
    let mut ment = vec![false; n];
    let mut uf = UnionFind::new(n);
    // How many more edges are necessary?
    let mut nec: usize = 0;
    let mut ma: usize = 0;
    for &(a, b, c) in abc {
        if c == 1 {
            uf.unite(a, b);
        }
        ment[a] = true;
        ment[b] = true;
    }
    let mut sz = vec![0; n];
    for i in 0..n {
        sz[uf.root(i)] += 1;
    }

    // vars
    let mut unused = 0;
    let mut united: Vec<usize> = vec![];

    for i in 0..n {
        if !ment[i] {
            unused += 1;
            continue;
        }
        if sz[i] >= 2 {
            united.push(sz[i]);
            nec += 1;
        }
        if sz[i] == 1 {
            united.push(sz[i]);
        }
    }
    // debugln!("unused = {}, united = {:?}", unused, united);
    if united.is_empty() {
        return (n - 1, n * (n - 1) / 2);
    }
    for u in united.iter_mut() {
        if *u == 2 {
            if unused > 0 {
                unused -= 1;
                *u += 1;
            } else {
                return (1, 0);
            }
        }
    }
    united.sort();
    if unused >= 1 {
        if let Some(l) = united.pop() {
            united.push(l + unused);
        } else {
            unreachable!();
        }
    }
    for &(a, b, c) in abc {
        if c == 0 {
            if uf.is_same_set(a, b) {
                return (1, 0);
            }
            uf.unite(a, b);
        }
    }
    for v in united {
        ma += v * (v - 1) / 2 - (v - 1);
    }
    nec += n - 1; // spanning tree
    ma += n - 1;
    debugln!("[nec, ma] = [{}, {}]", nec, ma);
    (nec, ma)
}

fn solve() {
    let out = std::io::stdout();
    let mut out = BufWriter::new(out.lock());
    macro_rules! puts {
        ($($format:tt)*) => (write!(out,$($format)*).unwrap());
    }
    input! {
        n: usize, m: usize, q: usize,
        abc: [(usize, usize, i32); q],
    }
    let (nec, ma) = calc(n, &abc);
    puts!("{}\n", if nec <= m && m <= ma { "Yes" } else { "No" });
}

fn main() {
    // In order to avoid potential stack overflow, spawn a new thread.
    let stack_size = 104_857_600; // 100 MB
    let thd = std::thread::Builder::new().stack_size(stack_size);
    thd.spawn(|| solve()).unwrap().join().unwrap();
}

