fn main() {
    let out = std::io::stdout();
    let mut out = BufWriter::new(out.lock());
    macro_rules! puts {
        ($($format:tt)*) => (write!(out,$($format)*).unwrap());
    }

    input!{
      n: usize,
      m: usize,
      q: usize,
      abcs: [(usize, usize, usize); q],
    }

    let mut uf = UnionFind::new(n);
    for &(a, b, c) in abcs.iter() {
        if c == 0 {
            uf.unite(a, b);
        }
    }

    let mut pars = vec![];
    for i in 0..n {
        pars.push(uf.find(i));
    }
    pars.sort();
    pars.dedup();
    let k = pars.len();

    use std::collections::HashSet;
    let mut seen = HashSet::new();
    for &(a, b, c) in abcs.iter() {
        if c == 0 {
            continue;
        }
        if k == 2 {
            return puts!("{}\n", "No");
        }
        if uf.same(a, b) {
            return puts!("{}\n", "No");
        }

        let mut p1 = uf.find(a);
        let mut p2 = uf.find(b);
        if p1 > p2 {
            std::mem::swap(&mut p1, &mut p2);
        }
        if seen.contains(&(p1, p2)) {
            return puts!("{}\n", "No");
        }
        seen.insert((p1, p2));
    }

    let max_m = (n-1) - (k-1) + k * (k-1) / 2;

    debug!(m, n, max_m, k);
    if m >= n && m <= max_m {
        puts!("{}\n", "Yes");
    } else {
        puts!("{}\n", "No");
    }
}

