#[derive(Debug)]
pub struct UnionFind {
    par: Vec<usize>,
}
impl UnionFind {
    pub fn new(n: usize) -> UnionFind {
        let mut vec = vec![0; n];
        for i in 0..n {
            vec[i] = i;
        }
        UnionFind { par: vec }
    }
    pub fn find(&mut self, x: usize) -> usize {
        if x == self.par[x] {
            x
        } else {
            let par = self.par[x];
            let res = self.find(par);
            self.par[x] = res;
            res
        }
    }
    pub fn same(&mut self, a: usize, b: usize) -> bool {
        self.find(a) == self.find(b)
    }
    pub fn unite(&mut self, a: usize, b: usize) {
        let apar = self.find(a);
        let bpar = self.find(b);
        self.par[apar] = bpar;
    }
}

fn main() {
    let out = std::io::stdout();
    let mut out = BufWriter::new(out.lock());
    macro_rules! puts {
        ($($format:tt)*) => (write!(out,$($format)*).unwrap());
    }

    input!{
      n: usize,
      m: usize,
      q: usize,
      abcs: [(usize, usize, usize); q],
    }

    let mut uf = UnionFind::new(n);
    for &(a, b, c) in abcs.iter() {
        if c == 0 {
            uf.unite(a, b);
        }
    }

    use std::collections::HashSet;
    let mut seen = HashSet::new();
    for &(mut a, mut b, c) in abcs.iter() {
        if c == 0 {
            continue;
        }

        if uf.same(a, b) {
            return puts!("{}\n", "No");
        }
        let mut p1 = uf.find(a);
        let mut p2 = uf.find(b);

        if p1 > p2 {
            std::mem::swap(&mut p1, &mut p2);
        }

        if c == 1 {
            if seen.contains(&(p1, p2)) {
                return puts!("{}\n", "No");
            }
            seen.insert((p1, p2));
        }
    }
    let mut pars = vec![];
    for i in 0..n {
        pars.push(uf.find(i));
    }
    pars.sort();
    pars.dedup();
    let k = pars.len();
    let max_m = (n-1) - (k-1) + k * (k-1) / 2;

    // debug!(m, n, max_m, k);
    if m >= n && m <= max_m {
        puts!("{}\n", "Yes");
    } else {
        puts!("{}\n", "No");
    }
}

