#[derive(Debug)]
pub struct UnionFind {
    par: Vec<usize>,
}
impl UnionFind {
    pub fn new(n: usize) -> UnionFind {
        let mut vec = vec![0; n];
        for i in 0..n {
            vec[i] = i;
        }
        UnionFind { par: vec }
    }
    pub fn find(&mut self, x: usize) -> usize {
        if x == self.par[x] {
            x
        } else {
            let par = self.par[x];
            let res = self.find(par);
            self.par[x] = res;
            res
        }
    }
    pub fn same(&mut self, a: usize, b: usize) -> bool {
        self.find(a) == self.find(b)
    }
    pub fn unite(&mut self, a: usize, b: usize) {
        let apar = self.find(a);
        let bpar = self.find(b);
        self.par[apar] = bpar;
    }
}

fn main() {
    let out = std::io::stdout();
    let mut out = BufWriter::new(out.lock());
    macro_rules! puts {
        ($($format:tt)*) => (write!(out,$($format)*).unwrap());
    }

    input!{
      n: usize,
      m: usize,
      q: usize,
      abcs: [(usize, usize, usize); q],
    }

    let mut nodes = vec![];
    let mut uf = UnionFind::new(n);
    for &(a, b, c) in abcs.iter() {
        if c == 0 {
            uf.unite(a, b);
        }
        nodes.push(a);
        nodes.push(b);
    }

    let mut ex = 0;
    let mut flag = vec![false; n];
    for &(a, b, c) in abcs.iter() {
        if c == 1 {
            uf.unite(a, b);
            if !flag[a] && !flag[b] {
                ex += 1;
            }
            flag[a] = true;
            flag[b] = true;
        }
        nodes.push(a);
        nodes.push(b);
    }

    nodes.sort();
    nodes.dedup();

    if nodes.len() + ex > n {
        return puts!("{}\n", "No");
    }
    let req = (n-1) + ex;
    if req <= m {
        puts!("{}\n", "Yes");
    } else {
        puts!("{}\n", "No");
    }
}

