    let cond1 = queries.iter().all(|&(a, b)| !sets.set_eq(&a, &b).unwrap());
    let k = sets.count();
    let cond2 = m <= (n-k) + k*(k-1)/2;
    let cond3 = !(!queries.is_empty() && m == n-1);
    yn(cond1 && cond2 && cond3);
}
